// 🛡️ 서버 저장 안전장치
//  1) 서버에 더 진행된(레벨 높은) 데이터가 있는데 이 폰은 낮으면 → 자동저장을 멈추고 물어봄 (좋은 데이터를 새 데이터가 덮어쓰는 사고 방지)
//  2) 서버 저장이 연속 실패하면 → 화면에 알려주고, 알아서 다시 시도 + [지금 저장] 버튼
(function () {
  'use strict';
  var FAIL_SHOW = 2, RETRY_MS = 30000;
  var THROTTLE_MS = 60000;                       // 자동 저장은 1분에 한 번만 (서버 쓰기 한도 아끼기)
  var IMMEDIATE = { firstLoad: 1, signup: 1, manual: 1, retry: 1, leave: 1 };
  var lastTry = 0, dirty = false, thrT = null;
  var blocked = false, checked = false, checking = null, fails = 0, retryT = null;
  function $(id) { return document.getElementById(id); }
  function lv() { try { return Number(playerLevel) || 1; } catch (e) { return 1; } }

  function banner(html) {
    var b = $('sg-banner');
    if (!html) { if (b) b.remove(); return; }
    if (!b) {
      b = document.createElement('div'); b.id = 'sg-banner';
      b.style.cssText = 'position:fixed;left:50%;transform:translateX(-50%);top:calc(8px + env(safe-area-inset-top));z-index:9500;width:calc(100% - 20px);max-width:410px;background:rgba(120,30,30,.96);color:#fff;border:1.5px solid #ff9a9a;border-radius:14px;padding:9px 12px;font-size:12px;line-height:1.5;font-family:inherit;box-shadow:0 4px 14px #0008;';
      document.body.appendChild(b);
    }
    b.innerHTML = html;
  }

  function askRestore(server) {
    blocked = true;
    var old = $('sg-ask'); if (old) old.remove();
    var ov = document.createElement('div'); ov.id = 'sg-ask';
    ov.style.cssText = 'position:fixed;inset:0;z-index:9600;background:rgba(0,0,0,.82);display:flex;align-items:center;justify-content:center;padding:20px;';
    ov.innerHTML = '<div style="background:#1a1a2e;border:2px solid #FF6B9D;border-radius:20px;padding:22px 18px;width:100%;max-width:320px;text-align:center;color:#fff;font-family:inherit;">' +
      '<div style="font-size:30px;">☁️</div>' +
      '<div style="font-size:15px;font-weight:900;margin:6px 0;">서버에 더 진행된 데이터가 있어요</div>' +
      '<div style="font-size:12.5px;line-height:1.7;color:#ddd;margin-bottom:14px;">서버: <b>Lv.' + (server.playerLevel || '?') + '</b> · 🍔 ' + Number(server.coins || 0).toLocaleString() + '<br>이 폰: <b>Lv.' + lv() + '</b> · 🍔 ' + Number(typeof coins !== 'undefined' ? coins : 0).toLocaleString() + '<br><span style="color:#ffd6e8;">보통은 서버 데이터를 불러오는 게 맞아요.</span></div>' +
      '<button id="sg-load" style="width:100%;padding:12px;margin-bottom:8px;border:none;border-radius:12px;background:linear-gradient(135deg,#FF6B9D,#C084FC);color:#fff;font-size:14px;font-weight:900;">서버 데이터 불러오기</button>' +
      '<button id="sg-keep" style="width:100%;padding:9px;border:1px solid #666;border-radius:12px;background:none;color:#aaa;font-size:12px;">이 폰 데이터로 계속 (서버를 덮어써요)</button></div>';
    document.body.appendChild(ov);
    $('sg-load').onclick = function () {
      try { if (typeof restorePocaDataFromServer === 'function') restorePocaDataFromServer(server); } catch (e) {}
      ov.querySelector('div').innerHTML = '<div style="padding:20px;color:#fff;">불러왔어요! 새로고침할게요 ✨</div>';
      setTimeout(function () { location.reload(); }, 900);
    };
    $('sg-keep').onclick = function () {
      if (!confirm('정말 서버의 더 진행된 데이터를 이 폰 데이터로 덮어쓸까요?\n되돌릴 수 없어요.')) return;
      blocked = false; ov.remove();
    };
  }

  // 서버 데이터를 한 번 읽어서 비교
  function checkServer() {
    if (checked) return Promise.resolve(!blocked);
    if (checking) return checking;
    checking = (async function () {
      try {
        var F = window.pocaFirebase;
        if (!F || !F.getDoc || !F.doc || !F.db || !window.pocaLoggedInUid) return true;
        var snap = await F.getDoc(F.doc(F.db, 'users', (typeof getPocaServerUid === 'function' ? getPocaServerUid() : window.pocaLoggedInUid)));
        checked = true;
        if (snap.exists()) {
          var d = snap.data() || {};
          if (Number(d.playerLevel || 0) > lv() + 1) { askRestore(d); return false; }
        }
        return true;
      } catch (e) { return true; }   // 읽기 실패는 막지 않음 (저장 쪽에서 실패 처리)
      finally { checking = null; }
    })();
    return checking;
  }

  function scheduleRetry() {
    if (retryT) return;
    retryT = setTimeout(function () { retryT = null; if (typeof savePocaUserToServer === 'function') savePocaUserToServer('retry'); }, RETRY_MS);
  }
  function showFail() {
    banner('⚠️ <b>서버 저장이 안 되고 있어요</b><br>인터넷 연결을 확인해주세요. 연결되면 자동으로 다시 저장해요 (이 폰에는 계속 저장돼요).' +
      '<br><button id="sg-now" style="margin-top:6px;padding:5px 12px;border:none;border-radius:8px;background:#fff;color:#a00;font-size:12px;font-weight:900;">지금 저장 시도</button>');
    var n = $('sg-now'); if (n) n.onclick = function () { n.textContent = '저장 중...'; savePocaUserToServer('manual'); };
  }

  function install() {
    if (typeof window.savePocaUserToServer !== 'function' || window.savePocaUserToServer.__sg) return false;
    var orig = window.savePocaUserToServer;
    var w = async function (reason) {
      if (!window.pocaLoggedInUid || !window.pocaFirebaseReady || !window.pocaFirebase) return orig.call(this, reason);
      if (blocked) return false;
      if (!IMMEDIATE[reason]) {           // 자주 호출되는 자동 저장은 모아서 한 번만
        var wait = THROTTLE_MS - (Date.now() - lastTry);
        if (wait > 0) {
          dirty = true;
          if (!thrT) thrT = setTimeout(function () { thrT = null; if (dirty) window.savePocaUserToServer('throttled'); }, wait + 200);
          return false;
        }
      }
      lastTry = Date.now(); dirty = false;
      var ok = await checkServer();
      if (!ok || blocked) return false;
      var res = await orig.call(this, reason);
      if (res) { fails = 0; window.__lastServerSave = Date.now(); banner(null); }
      else { fails++; if (fails >= FAIL_SHOW) showFail(); scheduleRetry(); }
      return res;
    };
    w.__sg = true;
    window.savePocaUserToServer = w;
    try { savePocaUserToServer = w; } catch (e) {}
    return true;
  }
  // 앱을 닫거나 다른 앱으로 넘어갈 때, 아직 못 올린 변경이 있으면 바로 저장
  function flush() { if (dirty && typeof window.savePocaUserToServer === 'function') window.savePocaUserToServer('leave'); }
  document.addEventListener('visibilitychange', function () { if (document.visibilityState === 'hidden') flush(); });
  window.addEventListener('pagehide', flush);
  var tries = 0, t = setInterval(function () { if (install() || ++tries > 60) clearInterval(t); }, 300);
})();

// ════════════════════════════════
// 🌙 특별 탐험 (1단계: 수동 탐험)
// ════════════════════════════════

const SPECIAL_LOCATIONS = [
  { id:'sky_ruins',         name:'천공성 유적',   emoji:'🏛️', color:'#60A5FA', bg:'https://raw.githubusercontent.com/chaei7775/Poca-house/main/special-sky_ruins.png' },
  { id:'moonlit_corridor',  name:'달빛 회랑',     emoji:'🌙', color:'#A78BFA', bg:'https://raw.githubusercontent.com/chaei7775/Poca-house/main/special-moonlit_corridor.png' },
  { id:'workshop_basement', name:'공방 지하',     emoji:'🔮', color:'#F472B6', bg:'https://raw.githubusercontent.com/chaei7775/Poca-house/main/special-workshop_basement.png' }
];

const SPECIAL_FOODS = ['반짝열매', '달빛열매', '오색열매'];
const SPECIAL_FOOD_PRICE = 30;

const SPECIAL_CREATURES = [
  { id:'rainbow_butterfly', emoji:'🦋', name:'무지개 나비',   correctFood:'오색열매', rare:false, img:'creature-rainbow_butterfly.png' },
  { id:'silver_sparrow',    emoji:'🕊️', name:'은빛 참새',     correctFood:'반짝열매', rare:false, img:'creature-silver_sparrow.png' },
  { id:'star_fox',          emoji:'🦊', name:'별빛 여우',     correctFood:'달빛열매', rare:false, img:'creature-star_fox.png' },
  { id:'silver_salmon',     emoji:'🐟', name:'은빛 연어',     correctFood:'반짝열매', rare:false, img:'creature-silver_salmon.png' },
  { id:'moon_rabbit',       emoji:'🐇', name:'달토끼',        correctFood:'달빛열매', rare:false, img:'creature-moon_rabbit.png' },
  { id:'crystal_deer',      emoji:'🦌', name:'수정 사슴',     correctFood:'오색열매', rare:false, img:'creature-crystal_deer.png' },
  { id:'aurora_peacock',    emoji:'🦚', name:'오로라 공작',   correctFood:'반짝열매', rare:true,  img:'creature-aurora_peacock.png' },
  { id:'wish_dragon',       emoji:'🐉', name:'소원의 새끼용', correctFood:'달빛열매', rare:true,  img:'creature-wish_dragon.png' }
];

function creatureImgHtml(creature, size) {
  return '<img src="https://raw.githubusercontent.com/chaei7775/Poca-house/main/' + creature.img + '" style="width:' + size + 'px;height:' + size + 'px;object-fit:contain;" onerror="this.outerHTML=\'<div style=&quot;font-size:' + size + 'px;&quot;>' + creature.emoji + '</div>\'">';
}

const LOCATION_CREATURES = {
  sky_ruins:         ['rainbow_butterfly', 'silver_sparrow', 'crystal_deer'],
  moonlit_corridor:  ['moon_rabbit', 'star_fox', 'aurora_peacock'],
  workshop_basement: ['silver_salmon', 'wish_dragon']
};

const RARE_VARIANTS = {
  rainbow_butterfly: { name:'프리즘 나비',       img:'variant-prism_butterfly.png' },
  silver_sparrow:    { name:'황금 깃털 참새',     img:'variant-gold_feather_sparrow.png' },
  crystal_deer:      { name:'다이아 수정사슴',     img:'variant-diamond_deer.png' },
  moon_rabbit:       { name:'월광 달토끼',         img:'variant-moonlight_rabbit.png' },
  star_fox:          { name:'은하수 별빛 여우',    img:'variant-galaxy_fox.png' },
  aurora_peacock:    { name:'성운 공작',           img:'variant-nebula_peacock.png' },
  silver_salmon:     { name:'붉은비늘 연어',       img:'variant-red_scale_salmon.png' },
  wish_dragon:       { name:'별빛 새끼용',         img:'variant-starlight_dragon.png' }
};

const SPECIAL_JAPTEM = [
  { emoji:'🦄', name:'별빛 털' },
  { emoji:'🪄', name:'반짝이는 날개가루' },
  { emoji:'🦢', name:'은빛 깃털' },
  { emoji:'🪷', name:'신비한 꽃가루' },
  { emoji:'🌾', name:'달빛 잎사귀' },
  { emoji:'🧊', name:'수정 조각' }
];
// 이미 가방에 있는 옛 이모지 재료/소품을 새 값으로 갱신 (가방은 이름으로 찾음)
function migrateSpecialMaterialEmoji() {
  if (typeof bagItems === 'undefined' || !Array.isArray(bagItems)) return;
  let changed = false;
  bagItems.forEach(function(i) {
    if (i.type === 'material') {
      const m = SPECIAL_JAPTEM.find(function(j) { return j.name === i.name; });
      if (m && i.emoji !== m.emoji) { i.emoji = m.emoji; changed = true; }
    } else if (i.type === 'gear') {
      const parsed = parseGearBagName(i.name);
      if (parsed) {
        const desc = '팬덤 원정 소품 · ' + gearEffectText(parsed.effect, parsed.value);
        if (i.desc !== desc || i.emoji !== parsed.emoji) { i.desc = desc; i.emoji = parsed.emoji; changed = true; }
      }
    }
  });
  if (changed && typeof saveBag === 'function') saveBag();
}
setInterval(migrateSpecialMaterialEmoji, 2000);
const SPECIAL_GEAR = [
  { name:'월광 리본',       emoji:'🎀', effect:'reach',   value:10 },
  { name:'프리즘 브로치',   emoji:'🌈', effect:'cd',      value:15 },
  { name:'천공 깃털 배지',  emoji:'🪽', effect:'reward',  value:20 },
  { name:'은하수 브로치',   emoji:'🌌', effect:'reward',  value:35 },
  { name:'수정 왕관 배지',  emoji:'💎', effect:'forgive', value:1 },
  { name:'불꽃 펜던트',     emoji:'🔥', effect:'cd',      value:30 },
  { name:'성운 펜던트',     emoji:'🌠', effect:'reach',   value:25 },
  { name:'용의 심장 브로치', emoji:'❤️', effect:'box',     value:50 }
];
const CAPTURE_TOOLS = [
  { id:'net',   name:'카메라',     emoji:'📷', price:50, value:20 },
  { id:'spray', name:'무드조명',   emoji:'💡', price:80, value:35 },
  { id:'scent', name:'분위기 향수', emoji:'🌸', price:65, value:25 }
];
// 이름이 바뀐 촬영도구: 이미 가방에 있는 옛 이름 아이템을 새 이름으로 옮김 (가방은 이름으로 찾기 때문)
const LEGACY_TOOL_NAMES = { '포획망':'net', '수면스프레이':'spray', '유인향수':'scent' };
function migrateCaptureToolNames() {
  if (typeof bagItems === 'undefined' || !Array.isArray(bagItems)) return;
  let changed = false;
  Object.keys(LEGACY_TOOL_NAMES).forEach(function(oldName) {
    const idx = bagItems.findIndex(function(i) { return i.name === oldName && i.type === 'tool'; });
    if (idx === -1) return;
    const tool = CAPTURE_TOOLS.find(function(t) { return t.id === LEGACY_TOOL_NAMES[oldName]; });
    const target = bagItems.find(function(i) { return i.name === tool.name; });
    if (target) { target.qty += bagItems[idx].qty; bagItems.splice(idx, 1); }
    else { bagItems[idx].name = tool.name; bagItems[idx].emoji = tool.emoji; bagItems[idx].desc = '레어 변종 촬영 마무리용'; }
    changed = true;
  });
  if (changed && typeof saveBag === 'function') saveBag();
}
setInterval(migrateCaptureToolNames, 2000);
const VARIANT_CORRECT_TOOL = {
  rainbow_butterfly: 'scent',
  silver_sparrow:    'net',
  crystal_deer:       'spray',
  moon_rabbit:        'spray',
  star_fox:           'net',
  aurora_peacock:     'scent',
  silver_salmon:       'net',
  wish_dragon:        'spray'
};

function getEquippedGearMap() {
  try { return JSON.parse(localStorage.getItem('ph_equippedGearByChar') || '{}'); } catch (e) { return {}; }
}
// 소품 능력: 등급이 높을수록 수치가 커짐 (재도전 횟수는 전설만 2회)
const SPECIAL_GEAR_GRADE_MULT = { common:1, great:1.2, rare:1.5, legend:2 };
function gearScaledValue(gear, grade) {
  if (gear.effect === 'forgive') return grade === 'legend' ? 2 : 1;
  return Math.round(gear.value * (SPECIAL_GEAR_GRADE_MULT[grade] || 1));
}
function gearEffectText(effect, value) {
  return effect === 'reach' ? '팬덤 원정 스킬 사거리 +' + value + '%' :
    effect === 'cd' ? '팬덤 원정 스킬 쿨타임 -' + value + '%' :
    effect === 'reward' ? '팬덤 원정 코인·경험치 +' + value + '%' :
    effect === 'box' ? '팬 응원 상자 떨어질 확률 +' + value + '%' :
    '팬덤 원정 스킬 순서 실수 ' + value + '회 막아줌';
}
// 가방 이름 '[고급] 월광 리본' → { name, baseName, emoji, effect, value, grade }
function parseGearBagName(bagName) {
  const labels = Object.keys(SPECIAL_GEAR_GRADES);
  let grade = 'common';
  for (let k = 0; k < labels.length; k++) {
    if (bagName.indexOf('[' + SPECIAL_GEAR_GRADES[labels[k]] + ']') === 0) { grade = labels[k]; break; }
  }
  const base = SPECIAL_GEAR.find(function(g) { return bagName.indexOf(g.name) !== -1; });
  if (!base) return null;
  return { name: bagName, baseName: base.name, emoji: base.emoji, effect: base.effect, value: gearScaledValue(base, grade), grade: grade };
}
// 🎟️ 세연(체험용 히든카드) — 아이돌 목록(CHARS)에는 없지만 체험 기간 동안은 출전할 수 있다
const SEYEON_TRIAL_CHAR = { name: '세연', emoji: '🌟', gradeColor: '#F59E0B' };
function exChar(cid) { return (cid === 'seyeon_trial') ? SEYEON_TRIAL_CHAR : CHARS[cid]; }
function pickGrowingIdol() {
  try {
    let best = null, bestLv = -1;
    Object.keys(CHARS).forEach(function(cid) {
      const has = CARDS.some(function(c) { return c.charId === cid && owned.indexOf(c.id) !== -1; });
      if (!has) return;
      const lv = (typeof getCardLevel === 'function') ? getCardLevel(cid) : 1;
      if (lv > bestLv) { best = cid; bestLv = lv; }
    });
    return best;
  } catch (e) { return null; }
}
window.pickGrowingIdol = pickGrowingIdol;
function trialActiveNow() { try { return !!(window.__trialTest && window.__trialTest.isActive()); } catch (e) { return false; } }

function getEquippedGearFor(charId) {
  const map = getEquippedGearMap();
  const name = map[charId];
  if (!name) return null;
  return parseGearBagName(name);
}
function setEquippedGearFor(charId, gearName) {
  const map = getEquippedGearMap();
  if (gearName) map[charId] = gearName;
  else delete map[charId];
  localStorage.setItem('ph_equippedGearByChar', JSON.stringify(map));
}
const SPECIAL_GEAR_GRADES = { common:'일반', great:'고급', rare:'희귀', legend:'전설' };

let specialExploreState = null; // { locationId, charId, creature, foodChosen }

function getGearBonus(charId, effectType) {
  const gear = getEquippedGearFor(charId);
  if (!gear || gear.effect !== effectType) return 0;
  return gear.value;
}
function hasRetryGear(charId) {
  return getGearBonus(charId, 'retry') > 0;
}

function openGearEquipScreen(charId) {
  const old = document.getElementById('gear-equip-popup');
  if (old) old.remove();
  const popup = document.createElement('div');
  popup.id = 'gear-equip-popup';
  popup.style.cssText = 'position:fixed;inset:0;z-index:1100;background:rgba(0,0,0,0.75);display:flex;align-items:center;justify-content:center;padding:20px;';
  popup.onclick = function(e) { if (e.target === popup) popup.remove(); };

  const owned = (typeof bagItems !== 'undefined' ? bagItems : []).filter(function(i) { return i.type === 'gear'; });
  const equipped = getEquippedGearFor(charId);
  const ch = exChar(charId);

  let listHtml;
  if (owned.length === 0) {
    listHtml = '<div style="font-size:12px;color:#888;text-align:center;padding:20px 0;">아직 보유한 촬영 소품이 없어요.<br>레어 변종을 촬영하면 소품을 얻을 수 있어요!</div>';
  } else {
    listHtml = owned.map(function(item) {
      const gear = parseGearBagName(item.name);
      if (!gear) return '';
      const isEquipped = equipped && equipped.name === item.name;
      const effectText = gearEffectText(gear.effect, gear.value);
      return '<div style="display:flex;align-items:center;justify-content:space-between;background:rgba(255,255,255,0.06);border:1.5px solid ' + (isEquipped ? '#FFD700' : 'rgba(255,255,255,0.15)') + ';border-radius:14px;padding:12px 14px;margin-bottom:8px;">' +
        '<div style="display:flex;align-items:center;gap:10px;"><span style="font-size:22px;">' + gear.emoji + '</span>' +
        '<div><div style="font-size:13px;font-weight:900;color:#fff;">' + item.name + '</div>' +
        '<div style="font-size:11px;color:#FFD700;margin-top:2px;">' + effectText + '</div></div></div>' +
        '<button onclick="equipSpecialGear(\'' + charId + '\',\'' + item.name + '\')" style="flex-shrink:0;padding:7px 12px;background:' + (isEquipped ? '#FFD700' : '#C084FC') + ';border:none;border-radius:10px;color:' + (isEquipped ? '#1a1a2e' : '#fff') + ';font-size:11px;font-weight:900;cursor:pointer;">' + (isEquipped ? '장착중' : '장착') + '</button>' +
        '</div>';
    }).join('');
  }

