    '<div style="font-size:15px;font-weight:900;color:#222;margin-bottom:4px;">🛒 먹이 구매</div>' +
    '<div style="font-size:11px;color:#888;margin-bottom:14px;">보유 코인: 🍔 ' + (typeof coins !== 'undefined' ? coins : 0) + '</div>' +
