    };
  })();
})();

// ════════════════════════════════
// ✨ 반짝이 가루 (sparkle-dust.js)
// 낚시로 잡은 물고기를 모아 "반짝이 가루"를 만들고, 카드 재조합할 때 써서 히든 확률을 올리는 소모품.
//  - 제작: 재조합 화면의 [만들기] 버튼. 물고기를 "점수"로 환산해서 6점 = 가루 1개.
//          손해가 가장 적은 조합(싼 물고기 위주)을 자동으로 골라 보여주고, 확인하면 만든다.
//  - 사용: [사용] 버튼을 켜고 재조합하면 가루 1개를 쓰고 이번 한 번만 레어히든 확률 +DUST_BONUS %p
//          (천장이 적용되는 SR_SR 이상 조합에서만 효과. 낮은 조합에선 안 쓰이고 안 사라짐)
// 필요: recombine-patch.js (천장 패치)가 같이 있어야 함. 값은 아래 설정만 고치면 됨.
// ════════════════════════════════
(function () {
  'use strict';

  var DUST_NAME = '반짝이 가루';
  var DUST_EMOJI = '✨';
  var DUST_BONUS = 5;          // 가루 1개 사용 시 레어히든 확률 증가(%p)
  var POINTS_PER_DUST = 6;     // 가루 1개에 필요한 물고기 점수
  // 물고기 점수 (비싼 물고기일수록 높음). 판매가(price)는 fishing.js와 같은 값
  var FISH = [
    { name: '별빛 송사리', emoji: '🐟', points: 1, price: 20 },
    { name: '은빛 붕어',   emoji: '🐟', points: 1, price: 30 },
    { name: '달빛 잉어',   emoji: '🐠', points: 2, price: 50 },
    { name: '꽃잎 금붕어', emoji: '🐠', points: 3, price: 90 },
    { name: '황금 잉어',   emoji: '🐡', points: 6, price: 180 }
  ];

  // ════ 순수 로직 ════
  // counts: { 물고기이름: 보유수 } → 가루 n개를 만들 때 "판매가 합이 가장 적은" 조합 {이름: 개수} (불가능하면 null)
  function planCraft(counts, n) {
    var need = POINTS_PER_DUST * n;
    var units = [];
    FISH.forEach(function (f) {
      var have = counts[f.name] || 0, cap = Math.min(have, Math.ceil(need / f.points));
      for (var i = 0; i < cap; i++) units.push(f);
    });
    var INF = 1e12, dp = [], pick = [];
    for (var p = 0; p <= need; p++) { dp.push(INF); pick.push(null); }
    dp[0] = 0;
    // 0/1 배낭: need 이상이면 need로 합침. 같은 물고기 여러 마리는 unit 단위로 처리
    var ids = [];
    units.forEach(function (u, idx) {
      for (var q = need; q >= 0; q--) {
        if (dp[q] >= INF) continue;
        var np = Math.min(need, q + u.points), cost = dp[q] + u.price;
        if (cost < dp[np]) { dp[np] = cost; pick[np] = { from: q, unit: idx, prev: pick[q] }; }
      }
    });
    if (dp[need] >= INF) return null;
    // 역추적 (각 칸이 마지막으로 갱신된 unit 기준이라 사슬을 따라가며 같은 unit 중복 사용 방지)
    var plan = {}, used = {}, node = pick[need], guard = 0;
    while (node && guard++ < 1000) {
      if (used[node.unit]) return planFallback(counts, n);
      used[node.unit] = true;
      var name = units[node.unit].name; plan[name] = (plan[name] || 0) + 1;
      node = node.prev;
    }
    var pts = 0; Object.keys(plan).forEach(function (k) { pts += plan[k] * pointsOf(k); });
    return pts >= need ? plan : planFallback(counts, n);
  }
  function pointsOf(name) { for (var i = 0; i < FISH.length; i++) if (FISH[i].name === name) return FISH[i].points; return 0; }
  // 역추적이 꼬였을 때를 위한 단순 대체: 싼 물고기부터 채움
  function planFallback(counts, n) {
    var need = POINTS_PER_DUST * n, got = 0, plan = {};
    FISH.slice().sort(function (a, b) { return a.price - b.price; }).forEach(function (f) {
      var have = counts[f.name] || 0;
      while (have > 0 && got < need) { plan[f.name] = (plan[f.name] || 0) + 1; have--; got += f.points; }
    });
    return got >= need ? plan : null;
  }
  function maxCraft(counts) {
    var total = 0; FISH.forEach(function (f) { total += (counts[f.name] || 0) * f.points; });
    var n = Math.floor(total / POINTS_PER_DUST);
    while (n > 0 && !planCraft(counts, n)) n--;
    return n;
  }

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { FISH: FISH, planCraft: planCraft, maxCraft: maxCraft, POINTS_PER_DUST: POINTS_PER_DUST };
  }
  if (typeof document === 'undefined') return;

  // ════ 게임 연동 ════
  var useDust = false;   // [사용] 켜짐 여부 (화면을 나가면 다시 꺼짐)

  function qty(name) {
    var it = bagItems.find(function (i) { return i.name === name; });
    return it ? it.qty : 0;
  }
  function fishCounts() {
    var c = {}; FISH.forEach(function (f) { c[f.name] = qty(f.name); });
    return c;
  }
  function planText(plan) {
    return FISH.filter(function (f) { return plan[f.name]; }).map(function (f) { return f.emoji + ' ' + f.name + ' ×' + plan[f.name]; }).join('<br>');
  }

  function craft(n) {
    var plan = planCraft(fishCounts(), n);
    if (!plan) { showBagToast('물고기가 부족해요!'); return; }
    // 가방 자리 확인 (가루 칸이 없고 가방이 꽉 찬 경우, 물고기 칸이 비면 자리가 생기므로 일단 진행 후 결과 확인)
    FISH.forEach(function (f) { if (plan[f.name]) useFromBag(f.name, plan[f.name]); });
    if (!addToBag(DUST_EMOJI, DUST_NAME, 'material', n, '재조합 히든 확률 +' + DUST_BONUS + '%p (SR_SR 이상 조합, 1회 1개)')) {
      FISH.forEach(function (f) { if (plan[f.name]) addToBag(f.emoji, f.name, 'material', plan[f.name], '낚시로 잡은 물고기 · 재료 상점에서 팔 수 있어요'); });
      return;
    }
    if (typeof MATERIAL_EMOJI_MAP !== 'undefined') MATERIAL_EMOJI_MAP[DUST_NAME] = DUST_EMOJI;
    showBagToast('✨ 반짝이 가루 ' + n + '개를 만들었어요!');
    var ov = document.getElementById('dust-craft-overlay'); if (ov) ov.remove();
    refreshPanel();
  }

  function openCraft() {
    var old = document.getElementById('dust-craft-overlay'); if (old) old.remove();
    var counts = fishCounts(), max = maxCraft(counts), one = planCraft(counts, 1);
    var ov = document.createElement('div');
    ov.id = 'dust-craft-overlay';
    ov.style.cssText = 'position:fixed;inset:0;z-index:985;background:rgba(0,0,0,0.8);display:flex;align-items:center;justify-content:center;';
    var have = FISH.map(function (f) { return counts[f.name] ? f.emoji + ' ' + f.name + ' ' + counts[f.name] + '마리 (' + f.points + '점)' : ''; }).filter(Boolean).join('<br>') || '물고기가 없어요. 호수에서 낚시해봐요 🎣';
    var body = '<div style="background:linear-gradient(135deg,#1a1a2e,#2d1b4e);border:2px solid #C084FC;border-radius:20px;padding:24px 20px;text-align:center;width:86%;max-width:310px;">' +
      '<div style="font-size:34px;margin-bottom:4px;">✨</div>' +
      '<div style="font-size:18px;font-weight:900;color:#fff;margin-bottom:6px;">반짝이 가루 만들기</div>' +
      '<div style="font-size:12px;color:#aaa;line-height:1.6;margin-bottom:12px;">물고기 ' + POINTS_PER_DUST + '점 = 가루 1개<br>쓰면 재조합 히든 확률 +' + DUST_BONUS + '%p (SR_SR 이상)</div>' +
      '<div style="font-size:13px;color:#ddd;line-height:1.7;margin-bottom:12px;text-align:left;background:rgba(255,255,255,0.06);border-radius:12px;padding:10px 12px;">' + have + '</div>';
    if (one) {
      body += '<div style="font-size:12px;color:#FFD700;margin-bottom:10px;">1개 만들 때 사라지는 물고기<br>' + planText(one) + '</div>' +
        '<button id="dust-make-1" style="width:100%;padding:13px;margin-bottom:8px;background:linear-gradient(135deg,#FF6B9D,#C084FC);border:none;border-radius:12px;color:#fff;font-size:15px;font-weight:700;cursor:pointer;font-family:\'Noto Sans KR\',sans-serif;">1개 만들기</button>';
      if (max > 1) body += '<button id="dust-make-max" style="width:100%;padding:12px;margin-bottom:8px;background:rgba(192,132,252,0.2);border:1px solid #C084FC;border-radius:12px;color:#fff;font-size:14px;font-weight:700;cursor:pointer;font-family:\'Noto Sans KR\',sans-serif;">최대 ' + max + '개 만들기</button>';
    } else {
      body += '<div style="font-size:12px;color:#FF6B9D;margin-bottom:10px;">점수가 모자라요 (현재 ' + FISH.reduce(function (a, f) { return a + (counts[f.name] || 0) * f.points; }, 0) + '점 / ' + POINTS_PER_DUST + '점 필요)</div>';
    }
    body += '<button id="dust-close" style="width:100%;padding:12px;background:rgba(255,255,255,0.1);border:none;border-radius:12px;color:#ccc;font-size:14px;cursor:pointer;font-family:\'Noto Sans KR\',sans-serif;">닫기</button></div>';
    ov.innerHTML = body;
    document.body.appendChild(ov);
    var m1 = document.getElementById('dust-make-1'); if (m1) m1.onclick = function () { craft(1); };
    var mm = document.getElementById('dust-make-max'); if (mm) mm.onclick = function () { craft(max); };
    document.getElementById('dust-close').onclick = function () { ov.remove(); };
  }

  // 재조합 화면의 가루 패널
  function refreshPanel() {
    var btn = document.getElementById('rc-start-btn');
    if (!btn || !btn.parentNode) return;
    var box = document.getElementById('rc-dust-box');
    if (!box) {
      box = document.createElement('div');
      box.id = 'rc-dust-box';
      box.style.cssText = 'display:flex;align-items:center;justify-content:center;gap:6px;flex-wrap:wrap;margin:auto 0 6px;font-size:12px;font-weight:700;color:#fff;';
      var info = document.getElementById('rc-pity-info');
      btn.parentNode.insertBefore(box, info || btn);
      if (info) info.style.marginTop = '0';
      else btn.style.marginTop = '0';
    }
    var n = qty(DUST_NAME), recipe = null, eligible = true;
    try {
      recipe = getRcCurrentRecipe();
      eligible = recipe ? rcPityApplies(recipe.key) : true;
    } catch (e) {}
    if (n <= 0) useDust = false;
    var on = useDust && n > 0 && eligible;
    var style = 'padding:6px 10px;border-radius:10px;font-size:12px;font-weight:700;cursor:pointer;font-family:\'Noto Sans KR\',sans-serif;';
    box.innerHTML = '<span>✨ 반짝이 가루 ' + n + '개</span>' +
      '<button id="rc-dust-use" style="' + style + 'background:' + (on ? 'linear-gradient(135deg,#FF6B9D,#C084FC)' : 'rgba(255,255,255,0.12)') + ';border:' + (on ? 'none' : '1px solid rgba(255,255,255,0.25)') + ';color:#fff;">' + (on ? '사용 중 (+' + DUST_BONUS + '%p)' : '사용 안 함') + '</button>' +
      '<button id="rc-dust-make" style="' + style + 'background:rgba(192,132,252,0.2);border:1px solid #C084FC;color:#fff;">만들기</button>' +
      (recipe && !eligible ? '<div style="width:100%;text-align:center;font-size:11px;font-weight:400;color:#aaa;">이 조합은 가루 효과 없음 (SR_SR 이상부터)</div>' : '');
    document.getElementById('rc-dust-use').onclick = function () {
      if (qty(DUST_NAME) <= 0) { showBagToast('반짝이 가루가 없어요. [만들기]로 만들어봐요 ✨'); return; }
      if (recipe && !eligible) { showBagToast('SR_SR 이상 조합에서만 쓸 수 있어요'); return; }
      useDust = !useDust; refreshPanel();
    };
    document.getElementById('rc-dust-make').onclick = openCraft;
  }

  (function applyDustPatch() {
    // recombine-patch.js가 doRecombine을 먼저 덮어쓴 뒤에 그 위에 얹어야 해서 기다림
    if (!window.__rcPatchApplied || typeof window.doRecombine !== 'function' || typeof window.updateRcStartButton !== 'function') {
      setTimeout(applyDustPatch, 50);
      return;
    }
    if (window.__dustPatchApplied) return;
    window.__dustPatchApplied = true;
    if (typeof MATERIAL_EMOJI_MAP !== 'undefined') MATERIAL_EMOJI_MAP[DUST_NAME] = DUST_EMOJI;

    var patchedDoRecombine = window.doRecombine;
    window.doRecombine = function () {
      var spent = false;
      try {
        var recipe = getRcCurrentRecipe();
        if (useDust && recipe && rcPityApplies(recipe.key) && qty(DUST_NAME) >= 1 && canDoRecombine()) {
          useFromBag(DUST_NAME, 1);
          window.__rcExtraRare = DUST_BONUS;
          spent = true;
        }
      } catch (e) {}
      try {
        return patchedDoRecombine.apply(this, arguments);
      } finally {
        window.__rcExtraRare = 0;
        if (spent && qty(DUST_NAME) <= 0) useDust = false;
      }
    };

    var prevUpdate = window.updateRcStartButton;
    window.updateRcStartButton = function () {
      var r = prevUpdate.apply(this, arguments);
      try { refreshPanel(); } catch (e) {}
      return r;
    };
  })();
})();

// ════════════════════════════════
// 🛒 수량 선택 패치 (1~100개 한 번에 사고팔기)
// game.js / recombine.js / special-explore.js 는 건드리지 않고 아래 함수만 덮어쓴다.
//  - 상점 선물/음료 구매 (buyGift, buyDrink)
//  - 재료 판매 (재료 탭의 '판매' 버튼)
//  - 가방에서 음료 마시기 (useDrinkFromBag)
//  - 특별탐험 먹이/촬영도구 구매 (buySpecialFood, buyCaptureTool)
// 한 번에 고를 수 있는 최대 수량만 바꾸고 싶으면 아래 한 줄만 수정.
// ════════════════════════════════

const QP_MAX = 100;

function qpEsc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function qpCanFit(name) {
  return bagItems.some(function(i) { return i.name === name; }) || bagItems.length < bagSlots;
}

function qpToast(msg) {
  if (typeof showShopToast === 'function') showShopToast(msg);
  else if (typeof showBagToast === 'function') showBagToast(msg);
}

function qpClose() {
  const o = document.getElementById('qp-overlay');
  if (o) o.remove();
}

// cfg: { mode:'buy'|'sell', emoji, name, unit, max, onConfirm(n) }
function qpOpen(cfg) {
  qpClose();
  const max = Math.min(QP_MAX, cfg.max);
  if (max < 1) {
    if (typeof showBagToast === 'function') showBagToast(cfg.mode === 'buy' ? '코인이 부족해요!' : '팔 수 있는 게 없어요!');
    return;
  }
  const isBuy = cfg.mode === 'buy';
  let n = 1;

  const ov = document.createElement('div');
  ov.id = 'qp-overlay';
  ov.style.cssText = 'position:fixed;inset:0;z-index:2000;background:rgba(0,0,0,0.75);display:flex;align-items:center;justify-content:center;padding:20px;';
  ov.onclick = function(e) { if (e.target === ov) qpClose(); };

  const btn = 'border:none;border-radius:10px;font-family:\'Noto Sans KR\',sans-serif;font-weight:900;cursor:pointer;';
  ov.innerHTML =
    '<div style="width:100%;max-width:320px;background:linear-gradient(135deg,#1a1a2e,#2d1b4e);border:2px solid #C084FC;border-radius:20px;padding:22px 20px;text-align:center;">' +
      '<div style="font-size:44px;margin-bottom:4px;">' + (window.matIcon ? window.matIcon(cfg.name, 60, qpEsc(cfg.emoji)) : qpEsc(cfg.emoji)) + '</div>' +
      '<div style="font-size:16px;font-weight:900;color:#fff;margin-bottom:2px;">' + qpEsc(cfg.name) + '</div>' +
      '<div style="font-size:12px;color:#aaa;margin-bottom:14px;">' + (cfg.sub ? qpEsc(cfg.sub) : '개당 🍔 ' + cfg.unit.toLocaleString() + '코인 · ') + (cfg.sub ? ' · ' : '') + (isBuy ? '최대 ' + max + '개' : '보유 ' + cfg.max + '개') + (cfg.max > QP_MAX ? ' · 한 번에 ' + QP_MAX + '개까지' : '') + '</div>' +
      '<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;">' +
        '<button id="qp-minus" style="' + btn + 'width:40px;height:40px;background:rgba(255,255,255,0.1);color:#fff;font-size:20px;">−</button>' +
        '<input id="qp-range" type="range" min="1" max="' + max + '" value="1" step="1" style="flex:1;accent-color:#FF6B9D;height:28px;">' +
        '<button id="qp-plus" style="' + btn + 'width:40px;height:40px;background:rgba(255,255,255,0.1);color:#fff;font-size:20px;">+</button>' +
      '</div>' +
      '<div style="display:flex;align-items:center;justify-content:center;gap:10px;margin-bottom:6px;">' +
        '<input id="qp-num" type="number" inputmode="numeric" min="1" max="' + max + '" value="1" style="width:84px;text-align:center;font-size:22px;font-weight:900;color:#FFD700;background:rgba(255,255,255,0.08);border:1.5px solid rgba(255,255,255,0.2);border-radius:10px;padding:6px 0;font-family:\'Noto Sans KR\',sans-serif;">' +
        '<span style="color:#aaa;font-size:14px;">개</span>' +
        '<button id="qp-max" style="' + btn + 'padding:9px 14px;background:rgba(192,132,252,0.25);color:#e9d5ff;font-size:12px;">최대</button>' +
      '</div>' +
      '<div id="qp-total" style="font-size:14px;font-weight:700;color:#fff;margin:10px 0 16px;"></div>' +
      '<button id="qp-ok" style="' + btn + 'width:100%;padding:13px;background:linear-gradient(135deg,#FF6B9D,#C084FC);color:#fff;font-size:15px;margin-bottom:8px;"></button>' +
      '<button id="qp-cancel" style="' + btn + 'width:100%;padding:11px;background:rgba(255,255,255,0.08);color:#aaa;font-size:13px;">취소</button>' +
    '</div>';
  document.body.appendChild(ov);

  const range = ov.querySelector('#qp-range');
  const num = ov.querySelector('#qp-num');
  const total = ov.querySelector('#qp-total');
  const ok = ov.querySelector('#qp-ok');

  function setN(v) {
    v = parseInt(v, 10);
    if (isNaN(v)) v = 1;
    n = Math.max(1, Math.min(max, v));
    range.value = n;
    num.value = n;
    const sum = n * cfg.unit;
    if (cfg.totalText) { total.textContent = cfg.totalText(n); ok.textContent = n + '개 ' + (cfg.okLabel || '사용'); return; }
    total.textContent = isBuy ? ('합계 🍔 ' + sum.toLocaleString() + '코인 (남는 코인 ' + (coins - sum).toLocaleString() + ')')
                              : ('합계 🍔 +' + sum.toLocaleString() + '코인');
    ok.textContent = n + '개 ' + (isBuy ? '구매' : '판매');
  }
  setN(1);

  range.oninput = function() { setN(range.value); };
  num.oninput = function() { if (num.value !== '') setN(num.value); };
  num.onchange = function() { setN(num.value); };
  ov.querySelector('#qp-minus').onclick = function() { setN(n - 1); };
  ov.querySelector('#qp-plus').onclick = function() { setN(n + 1); };
  ov.querySelector('#qp-max').onclick = function() { setN(max); };
  ov.querySelector('#qp-cancel').onclick = qpClose;
  ok.onclick = function() {
    const count = n;
    qpClose();
    cfg.onConfirm(count);
  };
}

function qpAfterShopBuy() {
  const el = document.getElementById('shop-coin-display');
  if (el) el.textContent = coins;
  if (typeof updateCoinsDisplay === 'function') { try { updateCoinsDisplay(); } catch (e) {} }
}

(function applyQtyPickerPatch() {
  const need = ['useDrinkFromBag', 'renderBag', 'saveStamina', 'buyGift', 'buyDrink', 'renderMaterialShop', 'sellMaterial', 'buySpecialFood', 'buyCaptureTool', 'addToBag', 'saveAll'];
  for (let i = 0; i < need.length; i++) {
    if (typeof window[need[i]] !== 'function') { setTimeout(applyQtyPickerPatch, 50); return; }
  }
  if (window.__qtyPickerApplied) return;
  window.__qtyPickerApplied = true;

  // ── 선물 구매 ──
  window.buyGift = function(itemName, price) {
    const emoji = itemName.match(/[\u{1F300}-\u{1FFFF}]|[☀-⛿]/gu)?.[0] || '🎁';
    const cleanName = (itemName.replace(/[\u{1F300}-\u{1FFFF}]|[☀-⛿]/gu, '').trim()) || itemName;
    qpOpen({
      mode: 'buy', emoji: emoji, name: cleanName, unit: price, max: Math.floor(coins / price),
      onConfirm: function(n) {
        if (coins < price * n) { showBagToast('코인이 부족해요!'); return; }
        if (!qpCanFit(cleanName)) { showBagToast('가방이 꽉 찼어요! 🎒 슬롯을 확장해주세요'); return; }
        const affExp = getGiftAffExp(itemName);
        if (!addToBag(emoji, cleanName, 'gift', n, '호감도 경험치 +' + affExp + ' 선물 아이템', affExp)) return;
        coins -= price * n;
        if (!inventory[itemName]) inventory[itemName] = 0;
        inventory[itemName] += n;
        saveAll();
        qpAfterShopBuy();
        renderInventoryDisplay();
        if (typeof spawnCoinFloat === 'function') spawnCoinFloat(-price * n);
        qpToast(itemName + ' ' + n + '개 구매 완료! 🎁');
      }
    });
  };

  // ── 음료 구매 ──
  window.buyDrink = function(itemName, price, staminaUp) {
    const emoji = itemName.match(/[\u{1F300}-\u{1FFFF}]|[☀-⛿]/gu)?.[0] || '🥤';
    const cleanName = (itemName.replace(/[\u{1F300}-\u{1FFFF}]|[☀-⛿]/gu, '').trim()) || itemName;
    qpOpen({
      mode: 'buy', emoji: emoji, name: cleanName, unit: price, max: Math.floor(coins / price),
      onConfirm: function(n) {
        if (coins < price * n) { showBagToast('코인이 부족해요!'); return; }
        if (!qpCanFit(cleanName)) { showBagToast('가방이 꽉 찼어요! 🎒 슬롯을 확장해주세요'); return; }
        if (!addToBag(emoji, cleanName, 'drink', n, '스태미나 +' + staminaUp + ' 회복 음료')) return;
        coins -= price * n;
        saveAll();
        qpAfterShopBuy();
        if (typeof spawnCoinFloat === 'function') spawnCoinFloat(-price * n);
        qpToast(itemName + ' ' + n + '개 구매 완료! 🎒 가방에서 마실 수 있어요');
      }
    });
  };

  // ── 재료 판매: 목록은 원본이 그리고, 버튼만 수량 선택으로 바꾼다 ──
  const originalRenderMaterialShop = window.renderMaterialShop;
  window.renderMaterialShop = function() {
    const r = originalRenderMaterialShop.apply(this, arguments);
    const el = document.getElementById('material-shop-list');
    if (el) {
      el.querySelectorAll('button[onclick^="sellMaterial("]').forEach(function(b) {
        const m = b.getAttribute('onclick').match(/^sellMaterial\('(.*)',1\)$/);
        if (!m) return;
        const name = m[1];
        b.removeAttribute('onclick');
        b.textContent = '판매';
        b.onclick = function() { qpSell(name); };
      });
    }
    return r;
  };

  window.qpSell = function(name) {
    const item = bagItems.find(function(i) { return i.name === name && i.type === 'material'; });
    if (!item) { showBagToast('재료가 부족해요!'); return; }
    const price = (typeof MATERIAL_SELL_PRICES !== 'undefined' && MATERIAL_SELL_PRICES[name]) || 0;
    qpOpen({
      mode: 'sell', emoji: item.emoji, name: name, unit: price, max: item.qty,
      onConfirm: function(n) { window.sellMaterial(name, n); }
    });
  };

  // ── 가방에서 음료 마시기 ──
  window.useDrinkFromBag = function(idx) {
    const item = bagItems[idx];
    if (!item) return;
    const staminaMap = { '사과주스': 100, '딸기스무디': 130, '에너지드링크': 160 };   // stamina-balance.js 와 같은 값
    const up = (window.__drinkUp ? window.__drinkUp(item.name) : (staminaMap[item.name] || 100));
    const need = Math.ceil((STAMINA_MAX - stamina) / up);
    if (need < 1) { showBagToast('스태미나가 이미 가득 찼어요!'); try { window.dispatchEvent(new Event('ph-drink-tried')); } catch (e) {} return; }   // 가득 차서 못 마셔도 '드링크 사용' 퀘스트는 인정
    const name = item.name;
    qpOpen({
      mode: 'use', emoji: item.emoji, name: name, unit: 0, max: Math.min(item.qty, need),
      sub: '보유 ' + item.qty + '개 · 1개당 ⚡ +' + up,
      totalText: function(n) { return '⚡ 스태미나 ' + stamina + ' → ' + Math.min(STAMINA_MAX, stamina + up * n) + ' / ' + STAMINA_MAX; },
      okLabel: '마시기',
      onConfirm: function(n) {
        const cur = bagItems.find(function(i) { return i.name === name; });
        if (!cur || cur.qty < n) { showBagToast('음료가 부족해요!'); return; }
        useFromBag(name, n);
        stamina = Math.min(STAMINA_MAX, stamina + up * n);
        saveStamina();
        saveAll();
        renderBag();
        showBagToast(item.emoji + ' ' + name + ' ' + n + '개 사용! ⚡ 스태미나 +' + (up * n));
      }
    });
  };

  // ── 특별탐험 먹이 구매 ──
  window.buySpecialFood = function(food) {
    qpOpen({
      mode: 'buy', emoji: '🍓', name: food, unit: SPECIAL_FOOD_PRICE, max: Math.floor(coins / SPECIAL_FOOD_PRICE),
      onConfirm: function(n) {
        if (coins < SPECIAL_FOOD_PRICE * n) { showBagToast('코인이 부족해요!'); return; }
        if (!qpCanFit(food)) { showBagToast('가방이 꽉 찼어요! 🎒 슬롯을 확장해주세요'); return; }
        if (!addToBag('🍓', food, 'food', n, '특별탐험 먹이')) return;
        coins -= SPECIAL_FOOD_PRICE * n;
        saveAll();
        qpAfterShopBuy();
        openFoodShop();
        renderSpecialFeedScreen();
        showBagToast(food + ' ' + n + '개 구매!');
      }
    });
  };

  // ── 특별탐험 촬영도구 구매 ──
  window.buyCaptureTool = function(toolId) {
    const tool = CAPTURE_TOOLS.find(function(t) { return t.id === toolId; });
    if (!tool) return;
    qpOpen({
      mode: 'buy', emoji: tool.emoji, name: tool.name, unit: tool.price, max: Math.floor(coins / tool.price),
      onConfirm: function(n) {
        if (coins < tool.price * n) { showBagToast('코인이 부족해요!'); return; }
        if (!qpCanFit(tool.name)) { showBagToast('가방이 꽉 찼어요! 🎒 슬롯을 확장해주세요'); return; }
        if (!addToBag(tool.emoji, tool.name, 'tool', n, '레어 변종 촬영 마무리용')) return;
        coins -= tool.price * n;
        saveAll();
        qpAfterShopBuy();
        openToolShop();
        renderCaptureToolScreen();
        showBagToast(tool.name + ' ' + n + '개 구매!');
      }
    });
  };
})();

// ════════════════════════════════
// 🌲 동쪽숲 나무 흔들기 탐험 (forest-explore.js)
// 숲의 "🌿 탐험하기" 버튼(startExplore('forest'))만 새 방식으로 바꾼다. 다른 지역 탐험은 그대로.
//
// 흐름: 스태미나 10 소모 → 35초 동안
//   나무(줄기)를 연타해서 흔들기 → 게이지가 차면 재료가 우수수 떨어짐 → 떨어지는 재료를 탭해서 줍기
//   🐝 벌이 같이 떨어질 때가 있음 (누르면 시간 -3초, 그냥 두면 사라짐)
//   ✨ 반짝이는 나무 1그루: 거기서는 희귀 재료가 확정으로 나옴
//   화면을 좌우로 밀거나 양쪽 화살표(◀ ▶)로 다른 나무로 이동
// 나무를 전부 털고 재료를 다 주우면 일찍 끝남. 재조합석 15% 판정은 기존 탐험과 동일.
//
// 값을 바꾸고 싶으면 아래 설정만 고치면 됨.
// ════════════════════════════════
(function () {
  'use strict';

  // ── 설정 ──
  var SESSION_SEC = 35;       // 탐험 시간
  var STAMINA_COST = 10;      // 기존 탐험과 동일
  var STONE_DROP = 0.25;      // 끝났을 때 재조합석 확률 (기존 탐험과 동일)
  var SHAKE_NEED = 8;         // 나무 한 그루를 흔들어 재료가 떨어지게 하는 데 필요한 탭 수
  var SHAKE_DECAY = 1.0;      // 가만히 있으면 게이지가 초당 이만큼 줄어듦
  var EXTRA_DROP = 0.25;      // 나무 한 그루에서 재료가 2개 떨어질 확률 (기본은 1개)
  var BEE_CHANCE = 0.25;      // 나무 한 그루에서 🐝가 같이 떨어질 확률
  var BEE_PENALTY = 3;        // 🐝를 누르면 줄어드는 시간(초)
  var GROUND_LIFE = 3.0;      // 땅에 떨어진 재료가 사라지기까지 (초)
  var BG_FILE = 'map-forest.png';
  var FRAC = 0.62;            // 화면에 한 번에 보이는 숲 가로 비율 (작을수록 확대)

  // 이미지 좌표(1536x1024) 기준 나무 위치 (대략값. 어색하면 숫자만 조절)
  // x: 줄기 중심, w: 탭 반폭, y0~y1: 탭 가능한 높이 범위
  var IMG_W = 1536, IMG_H = 1024;
  var TREES = [
    { x: 0.11, w: 0.085, y0: 0.00, y1: 0.80 },
    { x: 0.295, w: 0.050, y0: 0.00, y1: 0.50 },
    { x: 0.49, w: 0.055, y0: 0.00, y1: 0.45 },
    { x: 0.685, w: 0.060, y0: 0.00, y1: 0.45 },
    { x: 0.92, w: 0.070, y0: 0.00, y1: 0.40 }
  ];

  // ════════ 순수 로직 (화면 없이도 테스트 가능) ════════
  var POOLS = {
    normal: ['별빛나무', '고급원목', '신비버섯', '새의깃털'],
    rare: ['행운의잎', '천사의깃털']
  };
  function pools() {
    if (typeof EXPLORE_MATERIALS !== 'undefined' && EXPLORE_MATERIALS.forest) return EXPLORE_MATERIALS.forest;
    return POOLS;
  }

  // 기존 탐험과 같은 방식으로 재료 하나 뽑기. forceRare면 희귀 확정
  function rollDrop(luck, rng, forceRare) {
    rng = rng || Math.random;
    var p = pools();
    var rareChance = Math.min(0.80, 0.30 + (luck || 0) / 100);
    var isRare = forceRare || rng() < rareChance;
    var pool = isRare ? p.rare : p.normal;
    var mat = pool[Math.floor(rng() * pool.length)];
    var isWish = rng() < 0.005;
    return { name: isWish ? null : mat, isWish: isWish, isRare: isRare };
  }

  // 한 번 흔들었을 때 떨어지는 것들: [{...재료}, ..., {bee:true}]
  function planDrops(luck, rng, golden) {
    rng = rng || Math.random;
    var n = 1 + (rng() < EXTRA_DROP ? 1 : 0);
    var out = [];
    for (var i = 0; i < n; i++) out.push(rollDrop(luck, rng, golden && i === 0));
    if (rng() < BEE_CHANCE) out.splice(Math.floor(rng() * (out.length + 1)), 0, { bee: true });
    return out;
  }

  var S = null;

  // ════════ 화면 ════════
  function startForest() {
    if (document.getElementById('forest-overlay')) return;
    if (typeof stamina !== 'undefined' && stamina < STAMINA_COST) { showBagToast('스태미나가 부족해요! ⚡ 음료를 마셔봐요'); return; }
    stamina -= STAMINA_COST;
    saveStamina();
    exploreCollected = [];

    var overlay = document.createElement('div');
    overlay.id = 'forest-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:700;background:#0d2214;touch-action:none;user-select:none;-webkit-user-select:none;';
    var canvas = document.createElement('canvas');
    canvas.style.cssText = 'width:100%;height:100%;display:block;touch-action:none;';
    overlay.appendChild(canvas);
    document.body.appendChild(overlay);

    var bg = new Image();
    bg.src = (typeof B !== 'undefined' ? B : '') + BG_FILE;

    var goldenIdx = Math.floor(Math.random() * TREES.length);
    S = {
      overlay: overlay, canvas: canvas, ctx: canvas.getContext('2d'), bg: bg, bgOk: false,
      W: 0, H: 0, dpr: 1, s: 1, ox: 0, oy: 0, camX: 0.3 * IMG_W, camTarget: 0.3 * IMG_W,
      trees: TREES.map(function (t, i) {
        return { x: t.x * IMG_W, hw: t.w * IMG_W, y0: t.y0 * IMG_H, y1: t.y1 * IMG_H, shake: 0, anim: 0, done: false, golden: i === goldenIdx };
      }),
      items: [], leaves: [], pops: [], collected: [], timeLeft: SESSION_SEC, flash: 0,
      msg: '', msgT: 0, pointer: null, last: performance.now(), raf: 0, t: 0, ended: false, endDelay: -1
    };
    bg.onload = function () { if (S) S.bgOk = true; };
    resize();
    say('나무를 연타해서 흔들어봐요! 🌲 (밀어서 이동)', 4);

    window.addEventListener('resize', resize);
    canvas.addEventListener('pointerdown', onDown);
    canvas.addEventListener('pointermove', onMove);
    canvas.addEventListener('pointerup', onUp);
    canvas.addEventListener('pointercancel', onCancel);
    S.raf = requestAnimationFrame(loop);
  }

  function say(text, sec) { S.msg = text; S.msgT = sec || 2; }

  function resize() {
    if (!S) return;
    S.dpr = Math.min(window.devicePixelRatio || 1, 2);
    S.W = window.innerWidth; S.H = window.innerHeight;
    S.canvas.width = Math.round(S.W * S.dpr); S.canvas.height = Math.round(S.H * S.dpr);
    S.s = Math.max(S.W / (FRAC * IMG_W), 0.68 * S.H / IMG_H);
    clampCam();
  }
  function visW() { return S.W / S.s; }
  function clampCam() {
    var half = Math.min(visW(), IMG_W) / 2;
    S.camX = Math.max(half, Math.min(IMG_W - half, S.camX));
    S.camTarget = Math.max(half, Math.min(IMG_W - half, S.camTarget));
  }
  function layout() {
    var dw = IMG_W * S.s, dh = IMG_H * S.s;
    S.ox = S.W / 2 - S.camX * S.s;
    S.oy = dh <= S.H ? (S.H - dh) / 2 : Math.min(0, Math.max(S.H - dh, S.H / 2 - 0.5 * dh));
  }
  function toScreen(x, y) { return [x * S.s + S.ox, y * S.s + S.oy]; }
  function toImage(x, y) { return [(x - S.ox) / S.s, (y - S.oy) / S.s]; }

  // ── 입력 ──
  function pos(e) {
    var r = S.canvas.getBoundingClientRect();
    return [e.clientX - r.left, e.clientY - r.top];
  }
  function onDown(e) {
    if (!S || S.ended) return;
    e.preventDefault();
    var p = pos(e);
    try { S.canvas.setPointerCapture(e.pointerId); } catch (err) {}
    S.pointer = { id: e.pointerId, x0: p[0], y0: p[1], cam0: S.camTarget, moved: false };
  }
  function onMove(e) {
    if (!S || S.ended || !S.pointer || S.pointer.id !== e.pointerId) return;
    var p = pos(e), dx = p[0] - S.pointer.x0;
    if (!S.pointer.moved && Math.abs(dx) > 12) S.pointer.moved = true;
    if (S.pointer.moved) {
      S.camTarget = S.pointer.cam0 - dx / S.s;
      S.camX = S.camTarget;
      clampCam();
    }
  }
  function onUp(e) {
    if (!S || S.ended || !S.pointer || S.pointer.id !== e.pointerId) return;
    var ptr = S.pointer; S.pointer = null;
    if (ptr.moved) return;
    tap(ptr.x0, ptr.y0);
  }
  function onCancel() { if (S) S.pointer = null; }

  function tap(x, y) {
    if (x < 110 && y < 56) { finish(); return; }                          // 나가기
    var arrowY = S.H / 2;
    if (Math.abs(y - arrowY) < 60) {
      if (x < 48) { S.camTarget -= visW() * 0.45; clampCam(); return; }
      if (x > S.W - 48) { S.camTarget += visW() * 0.45; clampCam(); return; }
    }
    // 1) 떨어진 재료 / 벌
    var best = null, bd = 1e9;
    S.items.forEach(function (it) {
      if (it.gone) return;
      var sp = toScreen(it.x, it.y), d = Math.hypot(sp[0] - x, sp[1] - (y + 4));
      if (d < 36 && d < bd) { bd = d; best = it; }
    });
    if (best) { pickItem(best); return; }
    // 2) 나무 흔들기
    var im = toImage(x, y);
    var hit = null;
    S.trees.forEach(function (t) {
      var hw = Math.max(t.hw, 30 / S.s);
      if (Math.abs(im[0] - t.x) <= hw && im[1] >= t.y0 && im[1] <= t.y1 + 20) hit = t;
    });
    if (hit) shakeTree(hit);
  }

  function shakeTree(t) {
    if (t.done) { say('이 나무는 이미 다 털었어요 🍂', 1.2); return; }
    t.shake += 1;
    t.anim = 0.25;
    if (window.pocaSfx) window.pocaSfx.play('shake'); 
    for (var i = 0; i < 3; i++) addLeaf(t.x + (Math.random() - 0.5) * 220, 40 + Math.random() * 260);
    if (navigator.vibrate) { try { navigator.vibrate(12); } catch (e) {} }
    if (t.shake >= SHAKE_NEED) dropFromTree(t);
  }

  function addLeaf(x, y) {
    var cols = ['#86cf6a', '#b7e060', '#d9e86c', '#6bbf5e'];
    S.leaves.push({ x: x, y: y, vx: (Math.random() - 0.5) * 60, vy: 40 + Math.random() * 60, rot: Math.random() * 6, vr: (Math.random() - 0.5) * 6, life: 1.2 + Math.random() * 0.8, col: cols[Math.floor(Math.random() * cols.length)] });
  }

  function dropFromTree(t) {
    if (window.pocaSfx) window.pocaSfx.play('treeDrop'); 
    t.done = true; t.shake = SHAKE_NEED;
    var luck = typeof getEquippedStat === 'function' ? getEquippedStat('luck') : 0;
    var drops = planDrops(luck, Math.random, t.golden);
    drops.forEach(function (d, i) {
      var lx = Math.max(70, Math.min(IMG_W - 70, t.x + (Math.random() - 0.5) * 260));
      S.items.push({
        d: d, bee: !!d.bee, x: t.x + (Math.random() - 0.5) * 60, y: 0.10 * IMG_H, x1: lx,
        ly: (0.72 + Math.random() * 0.16) * IMG_H, vy: 0, delay: i * 0.18, state: 'wait', life: GROUND_LIFE, bounced: false, gone: false, t0: 0
      });
    });
    for (var k = 0; k < 14; k++) addLeaf(t.x + (Math.random() - 0.5) * 300, 20 + Math.random() * 300);
    if (t.golden) S.pops.push({ x: t.x, y: 0.30 * IMG_H, text: '✨ 반짝이는 나무!', t: 0 });
    var left = S.trees.filter(function (q) { return !q.done; }).length;
    say(left ? '재료를 탭해서 주워요! (남은 나무 ' + left + ')' : '마지막 재료를 주워요!', 2);
  }

  function pickItem(it) {
    it.gone = true;
    if (it.bee) {
      S.timeLeft = Math.max(0, S.timeLeft - BEE_PENALTY);
      S.flash = 0.35;
      S.pops.push({ x: it.x, y: it.y - 30, text: '🐝 앗 벌이다! -' + BEE_PENALTY + '초', t: 0, bad: true });
      if (navigator.vibrate) { try { navigator.vibrate([80, 40, 80]); } catch (e) {} }
      return;
    }
    var d = it.d, label = null, emoji = '✨';
    var before = exploreCollected.length;
    var el = { style: {}, parentNode: { removeChild: function () {} } };
    collectExploreItem(0, { name: d.name, isWish: d.isWish, isRare: d.isRare }, el);   // 기존 탐험 보상 로직 그대로 (가방, 경험치, 소원의 조각, 퀘스트)
    if (d.isWish) { label = '🧩 소원의 조각'; emoji = '🧩'; }
    else {
      label = exploreCollected.length > before ? exploreCollected[exploreCollected.length - 1] : d.name;
      emoji = typeof getMaterialEmoji === 'function' ? getMaterialEmoji(d.name) : '✨';
    }
    S.collected.push(label);
    S.pops.push({ x: it.x, y: it.y - 30, text: emoji + ' ' + label + (d.isRare ? ' ✨' : ''), t: 0 });
    if (navigator.vibrate) { try { navigator.vibrate(25); } catch (e) {} }
  }

  // ── 매 프레임 ──
  function loop(now) {
    if (!S || S.ended) return;
    var dt = Math.min(0.05, (now - S.last) / 1000); S.last = now; S.t += dt;
    S.timeLeft -= dt;
    if (S.msgT > 0) S.msgT -= dt;
    if (S.flash > 0) S.flash -= dt;

    // 카메라 부드럽게
    if (!(S.pointer && S.pointer.moved)) S.camX += (S.camTarget - S.camX) * Math.min(1, dt * 8);

    S.trees.forEach(function (t) {
      if (t.anim > 0) t.anim -= dt;
      if (!t.done && t.shake > 0) t.shake = Math.max(0, t.shake - SHAKE_DECAY * dt);
    });

    S.items.forEach(function (it) {
      if (it.gone) return;
      if (it.state === 'wait') { it.delay -= dt; if (it.delay <= 0) { it.state = 'fall'; it.t0 = 0; it.xs = it.x; } return; }
      if (it.state === 'fall') {
        it.t0 += dt;
        it.vy += 1500 * dt;
        it.y += it.vy * dt;
        var span = Math.max(1, it.ly - 0.10 * IMG_H);
        var prog = Math.min(1, (it.y - 0.10 * IMG_H) / span);
        it.x = it.xs + (it.x1 - it.xs) * prog;
        if (it.y >= it.ly) {
          it.y = it.ly;
          if (!it.bounced) { it.bounced = true; it.vy = -it.vy * 0.3; }
          else { it.state = 'ground'; it.vy = 0; }
        }
      } else if (it.state === 'ground') {
        it.life -= dt;
        if (it.life <= 0) {
          it.gone = true;
          S.pops.push({ x: it.x, y: it.y - 30, text: it.bee ? '🐝 날아갔어요' : '😢 놓쳤어요', t: 0, dim: true });
        }
      }
    });
    S.items = S.items.filter(function (it) { return !it.gone; });

    S.leaves.forEach(function (l) { l.life -= dt; l.x += l.vx * dt; l.y += l.vy * dt; l.rot += l.vr * dt; });
    S.leaves = S.leaves.filter(function (l) { return l.life > 0; });
    S.pops.forEach(function (p) { p.t += dt; });
    S.pops = S.pops.filter(function (p) { return p.t < 1.4; });

    // 끝났는지
    var allDone = S.trees.every(function (t) { return t.done; }) && S.items.length === 0;
    if (S.timeLeft <= 0) { finish(); return; }
    if (allDone) {
      if (S.endDelay < 0) S.endDelay = 0.7;
      S.endDelay -= dt;
      if (S.endDelay <= 0) { finish(); return; }
    }

    draw();
    S.raf = requestAnimationFrame(loop);
  }

  function draw() {
    if (!S || S.ended) return;
    var c = S.ctx, W = S.W, H = S.H;
    c.setTransform(S.dpr, 0, 0, S.dpr, 0, 0);
    c.clearRect(0, 0, W, H);
    layout();

    if (S.bgOk) {
      // 위아래 빈 곳: 같은 그림을 크게 깔고 어둡게
      var cs = Math.max(W / IMG_W, H / IMG_H), cw = IMG_W * cs, ch = IMG_H * cs;
      try { c.filter = 'blur(10px)'; } catch (e) {}
      c.drawImage(S.bg, (W - cw) / 2, (H - ch) / 2, cw, ch);
      try { c.filter = 'none'; } catch (e) {}
      c.fillStyle = 'rgba(5,20,10,0.55)'; c.fillRect(0, 0, W, H);

      c.drawImage(S.bg, S.ox, S.oy, IMG_W * S.s, IMG_H * S.s);

      // 흔들리는 나무: 그 나무 줄기 주변만 살짝 옆으로 밀어서 한 번 더 그림
      S.trees.forEach(function (t) {
        if (t.anim <= 0) return;
        var amp = Math.sin(S.t * 60) * 9 * (t.anim / 0.25);
        var sx = Math.max(0, t.x - IMG_W * 0.085), sw = Math.min(IMG_W - sx, IMG_W * 0.17), sh = IMG_H * 0.55;
        var d = toScreen(sx + amp, 0);
        c.drawImage(S.bg, sx, 0, sw, sh, d[0], d[1], sw * S.s, sh * S.s);
      });
    } else {
      c.fillStyle = '#1d3a22'; c.fillRect(0, 0, W, H);
    }

    // 나무 표시 + 게이지
    S.trees.forEach(function (t) {
      var p = toScreen(t.x, 0.33 * IMG_H);
      if (p[0] < -60 || p[0] > W + 60) return;
      if (t.done) return;
      var bounce = Math.sin(S.t * 5 + t.x) * 5;
      c.font = '28px sans-serif'; c.textAlign = 'center'; c.textBaseline = 'middle';
      c.fillText(t.golden ? '✨' : '👆', p[0], p[1] - 34 + bounce);
      var bw = 64, bx = p[0] - bw / 2, by = p[1] + 4;
      c.fillStyle = 'rgba(0,0,0,0.55)'; roundRect(c, bx - 2, by - 2, bw + 4, 12, 6); c.fill();
      c.fillStyle = t.golden ? '#FFD700' : '#8be07a';
      var w = bw * Math.min(1, t.shake / SHAKE_NEED);
      if (w > 1) { roundRect(c, bx, by, w, 8, 4); c.fill(); }
    });

    // 나뭇잎
    S.leaves.forEach(function (l) {
      var p = toScreen(l.x, l.y);
      c.save(); c.translate(p[0], p[1]); c.rotate(l.rot);
      c.globalAlpha = Math.min(1, l.life * 1.5);
      c.fillStyle = l.col; c.beginPath(); c.ellipse(0, 0, 7, 3.5, 0, 0, 6.3); c.fill();
      c.restore();
    });
    c.globalAlpha = 1;

    // 재료 / 벌
    S.items.forEach(function (it) {
      if (it.state === 'wait') return;
      var p = toScreen(it.x, it.y);
      var blink = it.state === 'ground' && it.life < 1.0 && Math.floor(S.t * 10) % 2 === 0;
      if (blink) return;
      var emoji = it.bee ? '🐝' : (it.d.isWish ? '🧩' : (typeof getMaterialEmoji === 'function' ? getMaterialEmoji(it.d.name) : '✨'));
      var bob = it.state === 'ground' ? Math.sin(S.t * 6 + it.x) * 3 : 0;
      if (!it.bee) {
        c.fillStyle = it.d.isRare ? 'rgba(255,215,0,0.35)' : 'rgba(255,255,255,0.25)';
        c.beginPath(); c.arc(p[0], p[1] + bob, 24, 0, 6.3); c.fill();
      }
      c.font = '34px sans-serif'; c.textAlign = 'center'; c.textBaseline = 'middle';
      c.fillText(emoji, p[0], p[1] + bob);
    });

    // 말풍선 팝업
    S.pops.forEach(function (p) {
      var sp = toScreen(p.x, p.y);
      c.globalAlpha = Math.max(0, 1 - p.t / 1.4);
      c.font = '900 14px "Noto Sans KR",sans-serif'; c.textAlign = 'center'; c.textBaseline = 'middle';
      c.lineWidth = 4; c.strokeStyle = 'rgba(0,0,0,0.7)';
      var tx = Math.max(70, Math.min(W - 70, sp[0])), ty = sp[1] - p.t * 40;
      c.strokeText(p.text, tx, ty);
      c.fillStyle = p.bad ? '#ff8a8a' : (p.dim ? '#bbb' : '#fff');
      c.fillText(p.text, tx, ty);
    });
    c.globalAlpha = 1;

    // 벌에 쏘이면 붉게
    if (S.flash > 0) { c.fillStyle = 'rgba(255,60,60,' + (S.flash * 0.9) + ')'; c.fillRect(0, 0, W, H); }

    // 좌우 이동 화살표
    var half = Math.min(visW(), IMG_W) / 2;
    c.font = '900 22px sans-serif'; c.textAlign = 'center'; c.textBaseline = 'middle';
    if (S.camX > half + 4) { c.fillStyle = 'rgba(0,0,0,0.45)'; roundRect(c, 4, H / 2 - 28, 40, 56, 14); c.fill(); c.fillStyle = '#fff'; c.fillText('◀', 24, H / 2); }
    if (S.camX < IMG_W - half - 4) { c.fillStyle = 'rgba(0,0,0,0.45)'; roundRect(c, W - 44, H / 2 - 28, 40, 56, 14); c.fill(); c.fillStyle = '#fff'; c.fillText('▶', W - 24, H / 2); }

    // 상단 HUD
    c.fillStyle = 'rgba(0,0,0,0.5)'; roundRect(c, 10, 10, 92, 36, 18); c.fill();
    c.fillStyle = '#fff'; c.font = '700 13px "Noto Sans KR",sans-serif'; c.textAlign = 'center';
    c.fillText('← 나가기', 56, 28);
    var tw = Math.max(0, S.timeLeft / SESSION_SEC);
    c.fillStyle = 'rgba(0,0,0,0.5)'; roundRect(c, 112, 20, W - 112 - 90, 16, 8); c.fill();
    c.fillStyle = tw < 0.25 ? '#ff6b6b' : '#8be07a';
    if (tw > 0.01) { roundRect(c, 114, 22, (W - 112 - 90 - 4) * tw, 12, 6); c.fill(); }
    c.fillStyle = 'rgba(0,0,0,0.5)'; roundRect(c, W - 76, 10, 66, 36, 18); c.fill();
    c.fillStyle = '#fff'; c.font = '700 13px "Noto Sans KR",sans-serif';
    c.fillText('🍃 ' + S.collected.length, W - 43, 28);

    // 하단 안내
    if (S.msgT > 0 && S.msg) {
      c.font = '700 14px "Noto Sans KR",sans-serif';
      var mw = c.measureText(S.msg).width + 28;
      c.fillStyle = 'rgba(0,0,0,0.6)'; roundRect(c, (W - mw) / 2, H - 70, mw, 34, 17); c.fill();
      c.fillStyle = '#fff'; c.textAlign = 'center'; c.textBaseline = 'middle';
      c.fillText(S.msg, W / 2, H - 53);
    }
  }

  function roundRect(c, x, y, w, h, r) {
    r = Math.min(r, w / 2, h / 2);
    c.beginPath(); c.moveTo(x + r, y); c.arcTo(x + w, y, x + w, y + h, r); c.arcTo(x + w, y + h, x, y + h, r);
    c.arcTo(x, y + h, x, y, r); c.arcTo(x, y, x + w, y, r); c.closePath();
  }

  // ── 종료 / 결과 ──
  function finish() {
    if (!S || S.ended) return;
    S.ended = true;
    cancelAnimationFrame(S.raf);
    window.removeEventListener('resize', resize);
    var got = S.collected.slice(), ov = S.overlay;

    if (Math.random() < STONE_DROP) {
      if (addToBag('🔹', '재조합석', 'material', 1, '카드 재조합에 필요한 재료')) { got.push('🔹 재조합석'); exploreCollected.push('🔹 재조합석'); }
    }
    var counts = {}, order = [];
    got.forEach(function (n) { if (!(n in counts)) { counts[n] = 0; order.push(n); } counts[n]++; });
    var list = order.length ? order.map(function (n) { return n + (counts[n] > 1 ? ' ×' + counts[n] : ''); }).join('<br>') : '아무것도 못 주웠어요 😢';
    var left = (typeof stamina !== 'undefined') ? stamina : '?';

    S = null;
    ov.innerHTML = '<div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.78);">' +
      '<div style="background:linear-gradient(135deg,#1a1a2e,#2d1b4e);border:2px solid #4ade80;border-radius:20px;padding:26px 22px;text-align:center;width:85%;max-width:300px;">' +
      '<div style="font-size:36px;margin-bottom:6px;">🌲</div>' +
      '<div style="font-size:18px;font-weight:900;color:#fff;margin-bottom:8px;">숲 탐험 끝!</div>' +
      '<div style="font-size:12px;color:#aaa;margin-bottom:8px;">스태미나 -' + STAMINA_COST + ' (잔여: ' + left + ')</div>' +
      '<div style="font-size:14px;color:#FFD700;line-height:1.7;margin-bottom:16px;">' + list + '</div>' +
      '<button id="forest-again" style="width:100%;padding:13px;margin-bottom:8px;background:linear-gradient(135deg,#4ade80,#C084FC);border:none;border-radius:12px;color:#fff;font-size:15px;font-weight:700;cursor:pointer;font-family:\'Noto Sans KR\',sans-serif;">🌲 한 번 더 (⚡' + STAMINA_COST + ')</button>' +
      '<button id="forest-close" style="width:100%;padding:12px;background:rgba(255,255,255,0.1);border:none;border-radius:12px;color:#ccc;font-size:14px;cursor:pointer;font-family:\'Noto Sans KR\',sans-serif;">확인</button>' +
      '</div></div>';
    document.getElementById('forest-close').onclick = function () { ov.remove(); };
    document.getElementById('forest-again').onclick = function () { ov.remove(); startForest(); };
  }

  window.startForest = startForest;
  window.__forestTest = { rollDrop: rollDrop, planDrops: planDrops, get S() { return S; }, TREES: TREES, SHAKE_NEED: SHAKE_NEED };

  // ── 숲 "탐험하기" 버튼만 새 탐험으로 연결 (game.js는 건드리지 않음) ──
  (function hookStartExplore() {
    if (typeof window.startExplore !== 'function' || typeof window.collectExploreItem !== 'function') { setTimeout(hookStartExplore, 50); return; }
    if (window.__forestHooked) return;
    window.__forestHooked = true;
    var original = window.startExplore;
    window.startExplore = function (placeId) {
      if (placeId === 'forest') { startForest(); return; }
      return original.apply(this, arguments);
    };
  })();
})();

// ════════════════════════════════
// 💪 연습생 숙소촌 헬스장 탐험 (housing-explore.js)
// 숙소촌의 "🎤 연습실 가기" 버튼(startExplore('housing'))만 새 방식으로 연결한다. 다른 지역 탐험은 그대로.
//
// 흐름: 스태미나 10 소모 → 35초 동안
//   운동기구를 연타해서 열심히 연습하기 → 게이지가 차면 ✨별빛 재료가 우수수 떨어짐 → 떨어지는 재료를 탭해서 줍기
//   😴 지친 연습생이 같이 떨어질 때가 있음 (누르면 시간 -3초, 그냥 두면 사라짐)
//   ✨ 반짝이는 기구 1개: 거기서는 희귀 재료가 확정으로 나옴
//   화면을 좌우로 밀거나 양쪽 화살표(◀ ▶)로 다른 기구로 이동
//   게이지가 차는 순간: 기구마다 다른 성공 글자(쾅!/질주!/번쩍! 등) + 충격파 링 + 흔들림 + 성공 소리 (화면은 안 멈춤)
// 기구를 전부 쓰고 재료를 다 주우면 일찍 끝남. 재조합석 18% 판정은 기존 탐험과 동일.
//
// 재료는 기존 재료 이름만 사용한다 (새 재료 없음). 값을 바꾸고 싶으면 아래 설정만 고치면 됨.
// 만든 방식은 forest-explore.js 와 같다. game.js 는 건드리지 않는다.
// ════════════════════════════════
(function () {
  'use strict';

  // ── 설정 ──
  var SESSION_SEC = 35;       // 탐험 시간
  var STAMINA_COST = 10;      // 기존 탐험과 동일
  var STONE_DROP = 0.25;      // 끝났을 때 재조합석 확률 (기존 탐험과 동일)
  var HIT_NEED = 8;           // 기구 하나를 연타해서 재료가 떨어지게 하는 데 필요한 탭 수
  var HIT_DECAY = 1.0;        // 가만히 있으면 게이지가 초당 이만큼 줄어듦
  var EXTRA_DROP = 0.25;      // 기구 하나에서 재료가 2개 떨어질 확률 (기본은 1개)
  var TIRED_CHANCE = 0.25;    // 기구 하나에서 😴가 같이 떨어질 확률
  var TIRED_PENALTY = 3;      // 😴를 누르면 줄어드는 시간(초)
  var GROUND_LIFE = 3.0;      // 바닥에 떨어진 재료가 사라지기까지 (초)
  var BG_FILE = 'map-gym.png';
  var FRAC = 0.62;            // 화면에 한 번에 보이는 헬스장 가로 비율 (작을수록 확대)

  // 이미지 좌표(1536x1024) 기준 기구 위치 (대략값. 어색하면 숫자만 조절)
  // x: 기구 중심, w: 탭 반폭, y0~y1: 탭 가능한 높이 범위
  var IMG_W = 1536, IMG_H = 1024;
  // word: 게이지가 찼을 때 화면에 뜨는 성공 글자 / sfx: sfx.js 의 성공 소리 이름 (gymPunch, gymRun, gymLift)
  var GEARS = [
    { name: '샌드백',     x: 0.105, w: 0.060, y0: 0.14, y1: 0.55, word: '💥 쾅!',    sfx: 'gymPunch' },
    { name: '덤벨랙',     x: 0.250, w: 0.088, y0: 0.36, y1: 0.56, word: '✨ 번쩍!',  sfx: 'gymLift' },
    { name: '러닝머신 1', x: 0.450, w: 0.068, y0: 0.32, y1: 0.58, word: '💨 질주!',  sfx: 'gymRun' },
    { name: '러닝머신 2', x: 0.573, w: 0.077, y0: 0.32, y1: 0.58, word: '💨 질주!',  sfx: 'gymRun' },
    { name: '랫풀다운',   x: 0.710, w: 0.100, y0: 0.20, y1: 0.57, word: '🔥 으랏차!', sfx: 'gymLift' },
    { name: '벤치',       x: 0.910, w: 0.068, y0: 0.46, y1: 0.64, word: '💪 파워!',  sfx: 'gymLift' }
  ];
  var BURST_SEC = 0.7;        // 성공 글자가 떠 있는 시간 (게임은 멈추지 않음)

  // ════════ 순수 로직 (화면 없이도 테스트 가능) ════════
  // 기존 재료 이름만 사용. 숙소촌 전용 목록이라 game.js의 EXPLORE_MATERIALS는 건드리지 않는다.
  var POOLS = {
    normal: ['빛나는돌', '별빛모래', '네잎클로버', '고급원목'],
    rare: ['행운의잎', '달의눈물']
  };
  function pools() {
    if (typeof EXPLORE_MATERIALS !== 'undefined' && EXPLORE_MATERIALS.housing) return EXPLORE_MATERIALS.housing;
    return POOLS;
  }

  // 기존 탐험과 같은 방식으로 재료 하나 뽑기. forceRare면 희귀 확정
  function rollDrop(luck, rng, forceRare) {
    rng = rng || Math.random;
    var p = pools();
    var rareChance = Math.min(0.80, 0.30 + (luck || 0) / 100);
    var isRare = forceRare || rng() < rareChance;
    var pool = isRare ? p.rare : p.normal;
    var mat = pool[Math.floor(rng() * pool.length)];
    var isWish = rng() < 0.005;
    return { name: isWish ? null : mat, isWish: isWish, isRare: isRare };
  }

  // 한 번 채웠을 때 떨어지는 것들: [{...재료}, ..., {tired:true}]
  function planDrops(luck, rng, golden) {
    rng = rng || Math.random;
    var n = 1 + (rng() < EXTRA_DROP ? 1 : 0);
    var out = [];
    for (var i = 0; i < n; i++) out.push(rollDrop(luck, rng, golden && i === 0));
    if (rng() < TIRED_CHANCE) out.splice(Math.floor(rng() * (out.length + 1)), 0, { tired: true });
