          tmsg = '샘이 반짝이다 잠잠해졌어요…<br><span style="font-size:12px;color:#aaa;">행운이 쌓이고 있어요 (' + Math.min(fails + 1, SPRING_PITY) + '/' + SPRING_PITY + ')</span>';
