  function onClick(e) {
    var t = e.target && e.target.closest ? e.target.closest('[data-act]') : null;
    if (!t) return;
    var act = t.getAttribute('data-act'), id = t.getAttribute('data-id'), tone = t.getAttribute('data-tone');
    var cid = ui.cid, now = Date.now();
    if (act === 'close') { var ov = document.getElementById('fancafe-overlay'); if (ov) ov.remove(); return; }
    if (act === 'tab') { ui.tab = t.getAttribute('data-tab'); ui.replyOpen = null; render(); return; }
    if (act === 'replytoggle') { ui.replyOpen = ui.replyOpen === id ? null : id; render(); return; }
    if (act === 'card') { var cd0 = cardDef(cid, id); if (cd0) showFanCardPopup(cd0, false); return; }
    var claimed = null;
    var s = loadAll(), ic = getIdol(s, cid, now);
    if (act === 'heart') { heartPost(ic, id, now); }
    else if (act === 'reply') {
      var r = replyPost(ic, id, tone, now);
      ui.replyOpen = null;
      if (r) toast(r.hit ? '✨ 취향 저격! 애착도가 크게 올랐어요' : '💬 답글을 남겼어요');
    } else if (act === 'quit') {
      var q = resolveQuit(ic, cid, id, tone, now);
      if (q) toast(q.stayed ? '🥹 마음을 돌렸어요!' : '💔 결국 떠났어요…');
    } else if (act === 'claim') {
      claimed = claimGift(ic, cid, id, now);
    }
    checkGifts(ic, cid, now);
    saveAllState(s);
    render();
    if (claimed) { toast('🃏 팬 포카를 받았어요!'); showFanCardPopup(claimed, true); }
  }

  // ════════ 살아 있는 카페: CF 결과 · 첫 팬 가입을 실시간으로 반영 ════════
  function live() {
    if (typeof document !== 'undefined' && document.hidden) return;
    var s = loadAll(), now = Date.now(), changedAny = false, toastMsg = null;
    Object.keys(s.idols).forEach(function (cid) {
      if (!s.idols[cid] || typeof CHARS === 'undefined' || !CHARS[cid]) return;
      var ic = normalize(s.idols[cid], now), sig = signature(ic), hadFans = Object.keys(ic.fans).length > 0, g0 = giftCount(ic);
      sync(ic, cid, now);
      var cf = processCF(ic, cid);
      if (signature(ic) !== sig) {
        changedAny = true;
        if (cf.handled) toastMsg = cf.viral ? '📱 커뮤니티에서 화제! 팬카페 ' + cf.from + '명 → ' + cf.to + '명' : '☕ 팬카페에 CF 반응 글이 올라왔어요';
        else if (!hadFans && Object.keys(ic.fans).length > 0) toastMsg = '☕ 팬카페에 첫 회원이 찾아왔어요!';
        if (giftCount(ic) > g0) toastMsg = (toastMsg ? toastMsg + ' · ' : '') + '🎁 팬 포카 선물이 도착했어요!';
      }
    });
    if (changedAny) {
      saveAllState(s);
      if (toastMsg && !document.getElementById('fancafe-overlay')) toast(toastMsg);
      render();
    }
  }
  setInterval(live, 5000);

  // ── 🚀 숏폼 떡상 (viral-hit.js 가 부름): 팬 폭증 + 신규 회원 도배 글 + 대표 팬 감격 글 + 72시간 탈덕 방지 ──
  var BOOM_NICKS = [['알고리즘의노예', '📱'], ['릴스보고왔어요', '🎞️'], ['틱포카입덕러', '🔥'], ['새벽의입덕', '🌙'], ['오늘부터1일', '🍀']];
  var BOOM_POSTS = [
    ['릴스 보고 들어왔는데 여기 {idol} 팬카페 맞음??', '추천에 계속 뜨길래 눌렀다가 그대로 입덕했어요. 맞게 찾아온 거 맞죠?'],
    ['방금 틱포카 500만 뷰 찍은 걔 누구냐... 입덕 좌표 좀', '이름이 {idol}이래서 바로 찾아왔어요. 좌표 줘서 고마워요.'],
    ['알고리즘 미쳤다 ㅋㅋㅋㅋ 오늘부터 1일 차 팬임', '선배님들 잘 부탁드립니다. 뭐부터 정주행하면 되나요?'],
    ['3초 나오는 거 보고 입덕 완료했습니다', '진짜 3초였는데 그걸로 끝났어요. 소속사 열일하네요.'],
    ['숏폼 알고리즘이 나를 여기로 이끌었다', '자려고 누웠다가 영상 보고 잠 다 깼어요. {idol} 어디서 볼 수 있어요?']
  ];
  function viralBoom(cid) {
    var s = loadAll(), now = Date.now(), rng = Math.random;
    if (!s.idols[cid]) return null;
    var ic = normalize(s.idols[cid], now), before = members(ic), idol = idolName(cid);
    var gain = Math.round(40 + before * (2 + rng() * 3) + rng() * 80);
    ic.anon += gain;
    var joined = 0;
    for (var k = 0; k < 2; k++) { var nd = nextDef(ic); if (nd && rng() < 0.8) { joinFan(ic, cid, nd, now, rng); joined++; } }
    var pool = BOOM_POSTS.slice(), nick = BOOM_NICKS.slice(), n = 3 + Math.floor(rng() * 3);
    for (var i = 0; i < n && pool.length; i++) {
      var po = pool.splice(Math.floor(rng() * pool.length), 1)[0], ni = nick.splice(Math.floor(rng() * nick.length), 1)[0];
      addPost(ic, { ts: now + i * 700, fanId: null, nick: ni[0], emoji: ni[1], kind: 'viral',
                    title: '💣 ' + po[0].replace(/\{idol\}/g, idol), body: po[1].replace(/\{idol\}/g, idol), hearts: smallHearts(ic, rng) + 3 });
    }
    var vet = ROSTER.filter(function (d) { var f = ic.fans[d.id]; return f && f.status === 'active'; });
    var pick = null;
    for (var j = 0; j < vet.length; j++) if (vet[j].id === 'veteran') pick = vet[j];
    if (!pick && vet.length) pick = vet[Math.floor(rng() * vet.length)];
    if (pick) addPost(ic, { ts: now + 4000, fanId: pick.id, kind: 'viral', title: '[공지/잡담] 얘들아... 우리 ' + idol + ' 드디어 알고리즘 탔다 ㅠㅠㅠ',
                            body: '나 울어... 조회수 500만 찍음!! 신규 회원분들 환영해요. 소속사 대표님 진짜 적게 일하고 많이 버세요 사랑합니다...', hearts: smallHearts(ic, rng) + 8 });
    ic.shieldUntil = now + 72 * HOUR;
    ic.lastCare = Math.max(ic.lastCare || 0, now);
    s.idols[cid] = ic; saveAllState(s);
    try { if (document.getElementById('fancafe-overlay')) render(); } catch (e) {}
    return { before: before, after: members(ic), gain: gain, joined: joined };
  }
  window.__fancafeViral = viralBoom;
  window.__fancafeHas = function (cid) { try { return !!loadAll().idols[cid]; } catch (e) { return false; } };

  window.openFanCafe = openFanCafe;
  window.__fancafeCurrentCid = function () { return ui.cid; };   // 지금 열려 있는 팬카페의 아이돌 (live.js 가 라이브 버튼을 붙일 때 씀)
  window.__fancafeTest = {
    ROSTER: ROSTER, TONES: TONES, STORAGE_KEY: STORAGE_KEY, loadAll: loadAll, saveAllState: saveAllState, getIdol: getIdol,
    addPost: addPost, sync: sync, processCF: processCF, handleCF: handleCF, members: members, heartPost: heartPost, replyPost: replyPost,
    resolveQuit: resolveQuit, quitChance: quitChance, claimGift: claimGift, checkGifts: checkGifts, FAN_CARDS: FAN_CARDS, GIFT_AFF: GIFT_AFF, showFanCardPopup: showFanCardPopup, live: live, open: openFanCafe, isDebuted: isDebuted, debutedIdols: debutedIdols,
    CONST: { TICK_MS: TICK_MS, MAX_TICKS: MAX_TICKS, FIRST_FAN_DELAY: FIRST_FAN_DELAY, QUIT_AFF: QUIT_AFF, QUIT_WAIT: QUIT_WAIT,
             QUIT_GRACE: QUIT_GRACE, DAY: DAY, HOUR: HOUR, POST_MAX: POST_MAX }
  };

  // ── 주택가 메뉴에 버튼 붙이기: 데뷔한 아이돌마다 "☕ ○○ 팬카페" ──
  // (첫 버튼의 id 는 예전과 같은 btn-fancafe-housing — kennel.js 가 이 버튼을 기준으로 분양소 버튼을 붙임)
  var madeBtn = {};
  function ensureCafeButtons() {
    var anchor = document.getElementById('btn-explore-housing');
    if (!anchor || typeof PLACE_BUTTONS === 'undefined' || typeof ALL_PLACE_BTNS === 'undefined' || typeof CHARS === 'undefined') return;
    debutedIdols().forEach(function (cid) {
      var b = madeBtn[cid];
      if (b && document.body.contains(b)) { b.textContent = '☕ ' + idolName(cid) + ' 팬카페'; return; }
      var first = !document.getElementById('btn-fancafe-housing');
      b = document.createElement('button');
      b.id = first ? 'btn-fancafe-housing' : 'btn-fancafe-housing-' + cid;
      b.textContent = '☕ ' + idolName(cid) + ' 팬카페';
      var shown = false;
      try { shown = window.getComputedStyle(anchor).display !== 'none'; } catch (e) {}
      b.style.cssText = 'display:' + (shown ? 'block' : 'none') + ';width:100%;padding:14px;margin-top:10px;background:rgba(255,179,128,0.18);border:1.5px solid #FFB380;border-radius:12px;color:#fff;font-size:15px;font-weight:700;cursor:pointer;' + FONT;
      b.onclick = function () { openFanCafe(cid); };
      var prev = null;
      Object.keys(madeBtn).forEach(function (k) { if (madeBtn[k] && document.body.contains(madeBtn[k])) prev = madeBtn[k]; });
      (prev || anchor).insertAdjacentElement('afterend', b);
      madeBtn[cid] = b;
      if (!PLACE_BUTTONS.housing) PLACE_BUTTONS.housing = [];
      if (PLACE_BUTTONS.housing.indexOf(b.id) === -1) PLACE_BUTTONS.housing.push(b.id);
      if (ALL_PLACE_BTNS.indexOf(b.id) === -1) ALL_PLACE_BTNS.push(b.id);
    });
  }
  setInterval(ensureCafeButtons, 1500);
  setTimeout(ensureCafeButtons, 300);
})();

