  // ── 질문 ──
  function askNow() {
    L.pending = true;
    var def = L.askers[L.asked];                    // null 이면 익명 시청자
    var a = def ? ASK[def.id] : ANON_ASK;
    var nick = def ? def.nick : pick(ANON_NICK), emoji = def ? def.emoji : '💬';
    addLine('📌', nick, fill(a.q, L.cid), 'ask');
