      for (var h = 0; h < 4; h++) floatHeart(rnd(5, 95));
      L.hearts += rnd(3, 8); setHearts();
      if (n % 2 === 0) addLine('💬', pick(ANON_NICK), fill(pick(VIRAL_LINES), L.cid), 'anon');
      if (n >= steps) clearInterval(iv);
    }, 600);
  }

  function tick() {
    if (!L || L.over || L.pending) return;
    L.tick += 1;
    if (L.asked < ASK_AT.length && L.tick === ASK_AT[L.asked]) { askNow(); return; }
    if (L.tick >= END_AT && L.asked >= ASK_AT.length) { finish(false); return; }
    chatOnce();
  }

  // ── 종료 / 보상 ──
  function finish(early) {
