  var MAX_LEVEL = 10;
  var RATE = [50, 45, 40, 37.5, 35, 30, 25, 20, 15, 10];                  // +1 ~ +10 성공 확률(%) — 1회차(초월 전) 기준
  var RATE_MULT = [1, 0.5, 0.25];                                             // 회차별 확률 배율 (초월 0/1/2단계일 때)
