          if (bagAdd(k, want - have)) s._bag[k] = want;
          else { extra = want - have; toastSafe('가방이 가득 차서 ' + MATS[k][1] + '이(가) 임시 보관돼요! 가방을 비워주세요'); }
        }
        out[k] = extra;
