    else if (out === 'protected') st.protect -= c.protect;
    else if (out === 'destroyed') {
      delete st.level[id]; delete st.stage[id];
      var i = ownedHiddenCards.indexOf(id);
      if (i !== -1) ownedHiddenCards.splice(i, 1);
