      [['🔨', '강화석', st.stone, ACC], ['🛡️', '방지권', st.protect, '#4ade80'], ['💎', '초월석', st.trans, '#60A5FA'], ['🍔', '코인', coinsNow(), '#FFD700']].map(function (m) {
