          '<span style="font-size:13px;color:#fff;font-weight:700;">' + (state.protectOn ? '🛡️ 방지권 ' + c.protect + '장 사용' : '⚠️ 방지권 안 씀') + ' <span style="font-size:11px;color:#aaa;">(보유 ' + st.protect + ')</span></span>' +
