          : '<div style="font-size:11px;color:#aaa;margin-top:6px;">+' + SAFE_UNTIL + '강까지는 실패해도 카드가 안 사라져요.</div>') +
        '</div>';
    } else if (S < TRANS_MAX) {
      var r = transReq(id);
