    F.cd[id] = now + (sk.aoe ? Math.max(1, COOLDOWN - 0.4 * mlv) : Math.max(0.5, 1 - 0.1 * mlv)) * 1000 * (1 - gs(F.cid, 'cd') / 100);   // 🎀 소품 쿨타임 감소
    //   // 단타 1초, 광역 3초 (숙련 Lv마다 단타 -0.1초 / 광역 -0.4초)   // 숙련 Lv마다 쿨타임 -0.4초 (최소 1초)
    // 대상 모으기: 가장 가까운 대상 + (광역이면) 범위 안의 다른 팬들
    var list = [fan.ev || fan];
