        '<button data-pbuy="' + po.id + '" style="padding:9px 12px;border:none;border-radius:12px;font-size:12px;font-weight:900;cursor:pointer;white-space:nowrap;color:' + (enough ? '#fff' : '#888') + ';background:' + (enough ? 'linear-gradient(135deg,#22c55e,#16a34a)' : 'rgba(255,255,255,.1)') + ';' + FONT + '">🍔 ' + fmt(po.price) + '</button></div>';
    }).join('');
    return '<div style="font-size:13px;font-weight:900;color:#fff;margin:4px 0 8px;">❤️ 회복약 <span style="font-size:11px;color:#aaa;font-weight:400;">(원정 중 HP 회복)</span></div>' + rows +
      '<div style="height:1px;background:rgba(255,255,255,.15);margin:12px 0;"></div>';
  }
  function openShop() {
    if (!$('fs-toast-fix')) { var tf = document.createElement('style'); tf.id = 'fs-toast-fix'; tf.textContent = '#bag-toast{z-index:3000 !important}'; document.head.appendChild(tf); }   // 상점(z955) 위에도 안내 메시지가 보이게
    var old = $('fs-shop'); if (old) old.remove();
    shopNote = '';
    var ov = document.createElement('div');
    ov.id = 'fs-shop';
    ov.style.cssText = 'position:fixed;inset:0;z-index:955;background:linear-gradient(180deg,#1a0a2e,#0a0515);overflow-y:auto;' + FONT;
    document.body.appendChild(ov);
    renderShop(ov);
  }
  var shopNote = '';
  function shopSay(ov, m) { shopNote = m; toast(m); renderShop(ov); }   // 상점 안에서도 결과를 눈에 띄게 보여줌 (토스트가 가려져도 보이게)
  function renderShop(ov) {
    ov = ov || $('fs-shop'); if (!ov) return;
    var ids = charIds();
    if (!shopChar || ids.indexOf(shopChar) === -1) shopChar = ids[0] || '';
    var chips = ids.map(function (id) {
      var on = id === shopChar;
      return '<button data-ch="' + id + '" style="padding:8px 14px;border:none;border-radius:999px;font-size:13px;font-weight:900;cursor:pointer;color:#fff;' + FONT +
        'background:' + (on ? 'linear-gradient(135deg,#FF6B9D,#C084FC)' : 'rgba(255,255,255,.1)') + ';">' + (charName(id) || id) + '</button>';
    }).join('');
    var rows = SKILLS.map(function (s) {
      var own = hasSkill(shopChar, s), enough = coinsNow() >= s.price;
      var btn = own
        ? '<div style="padding:8px 12px;border-radius:12px;font-size:12px;font-weight:900;color:#4ade80;border:1.5px solid #4ade80;">' + (s.price === 0 ? '기본' : '보유') + '</div>'
        : '<button data-buy="' + s.id + '" style="padding:9px 12px;border:none;border-radius:12px;font-size:12px;font-weight:900;cursor:pointer;white-space:nowrap;color:' + (enough ? '#fff' : '#888') + ';background:' + (enough ? 'linear-gradient(135deg,#FF6B9D,#C084FC)' : 'rgba(255,255,255,.1)') + ';' + FONT + '">🍔 ' + fmt(s.price) + '</button>';
      return '<div style="display:flex;align-items:center;gap:12px;background:rgba(255,255,255,.07);border:1.5px solid ' + (own ? 'rgba(74,222,128,.5)' : 'rgba(255,255,255,.18)') + ';border-radius:16px;padding:12px 14px;margin-bottom:10px;">' +
        '<div style="font-size:30px;">' + s.icon + '</div>' +
        '<div style="flex:1;min-width:0;"><div style="font-size:14px;font-weight:900;color:#fff;">' + s.name + (s.aoe ? ' <span style="font-size:10px;color:#ffd76a;">광역</span>' : '') + '</div><div style="font-size:11px;color:#aaa;line-height:1.5;">' + s.desc + ' · <b style="color:' + (levelOk(s) ? '#9fe8b0' : '#ff9a9a') + ';">사용 Lv.' + s.useLv + '</b></div></div>' + btn + '</div>';
    }).join('');
    ov.innerHTML =
      '<div style="position:sticky;top:0;z-index:2;background:rgba(10,5,20,.94);padding:14px 16px;display:flex;align-items:center;justify-content:space-between;">' +
        '<div style="color:#fff;font-size:17px;font-weight:900;">💖 팬 스킬 상점</div>' +
        '<button id="fs-shop-close" style="border:none;border-radius:12px;background:rgba(255,255,255,.12);color:#fff;padding:7px 12px;font-weight:900;cursor:pointer;' + FONT + '">닫기</button></div>' +
      '<div style="padding:0 16px 40px;">' +
        (shopNote ? '<div style="background:rgba(255,215,0,.16);border:1.5px solid #FFD700;border-radius:12px;padding:10px 12px;margin-bottom:10px;font-size:13px;font-weight:900;color:#fff;text-align:center;">' + shopNote + '</div>' : '') +
        '<div style="background:rgba(255,255,255,.07);border:1px solid #FFD70066;border-radius:12px;padding:8px 12px;margin-bottom:12px;display:flex;justify-content:space-between;font-size:13px;color:#fff;"><span>🍔 보유 코인</span><b style="color:#FFD700;">' + fmt(coinsNow()) + '</b></div>' +
        potionHtml() +
        '<button id="fs-open-ed" style="width:100%;margin-bottom:12px;padding:12px;border:none;border-radius:13px;background:linear-gradient(135deg,#C084FC,#7c3aed);color:#fff;font-size:14px;font-weight:900;cursor:pointer;' + FONT + '">⚔️ 스킬 장착하기 (' + loadLoadout().filter(Boolean).length + '/' + SLOTS + ')</button>' +
        '<div style="font-size:11px;color:#aaa;line-height:1.6;margin-bottom:10px;">팬 응대 스킬은 멤버마다 따로 배워요. 팬은 아직 못 배운 스킬도 원하니까, 많이 배울수록 😍 대만족이 자주 나와요.</div>' +
        '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px;">' + chips + '</div>' +
        rows + '</div>';
    Array.prototype.forEach.call(ov.querySelectorAll('[data-pbuy]'), function (b) {
      b.onclick = function () {
        var hk = bcHook(); if (!hk || !hk.potions) { shopSay(ov, '⚠️ 회복약 상점을 아직 못 불러왔어요. 잠깐 뒤에 다시 눌러봐요'); return; }
        var pid = b.getAttribute('data-pbuy');
        var po = hk.potions.list().filter(function (x) { return x.id === pid; })[0];
        if (!po) return;
        function doBuy(n) {
          var r;
          try { r = hk.potions.buy(pid, n); } catch (e) { shopSay(ov, '⚠️ 구매 중 오류가 났어요: ' + (e && e.message || e)); return; }
          if (!r.ok) { shopSay(ov, r.why === 'coins' ? '🍔 코인이 부족해요!' : r.why === 'bag' ? '🎒 가방이 가득 찼어요! 가방을 비우거나 넓혀봐요' : '살 수 없어요'); return; }
          shopSay(ov, po.emoji + ' ' + po.name + ' ' + n + '개를 샀어요!');
        }
        if (typeof qpOpen === 'function') {                 // 일반 상점처럼 수량 고르는 팝업 (슬라이더 / 직접 입력 / 최대)
          qpOpen({ mode: 'buy', emoji: po.emoji, name: po.name, unit: po.price, max: Math.floor(coinsNow() / po.price), onConfirm: doBuy });
        } else doBuy(1);
      };
    });
    ov.querySelector('#fs-shop-close').onclick = function () { ov.remove(); };
    var edb = ov.querySelector('#fs-open-ed'); if (edb) edb.onclick = function () { openEditor(shopChar); var e2 = $('fs-editor'); if (e2) { var cl = e2.querySelector('#fs-ed-close'); var o = cl.onclick; cl.onclick = function () { o(); renderShop(ov); }; } };
    Array.prototype.forEach.call(ov.querySelectorAll('[data-ch]'), function (b) { b.onclick = function () { shopChar = b.getAttribute('data-ch'); renderShop(ov); }; });
    Array.prototype.forEach.call(ov.querySelectorAll('[data-buy]'), function (b) {
      b.onclick = function () {
        var sk = skillById(b.getAttribute('data-buy'));
        var r = buySkill(shopChar, sk.id);
        if (!r.ok) { shopSay(ov, r.why === 'coins' ? '🍔 코인이 부족해요!' : '이미 배운 스킬이에요'); return; }
        shopSay(ov, '🎉 ' + (charName(shopChar) || '멤버') + '이(가) ' + sk.icon + ' ' + sk.name + ' 스킬을 배웠어요!');
      };
    });
  }
  window.openFanSkillShop = openShop;

  // 더보기 메뉴에 타일 붙이기 (함수가 아직 로드 안 됐으면 잠깐 기다렸다가 시도)
  (function whenReady() {
    var tries = 0;
    (function attempt() {
      var ok = false;
      try { ok = typeof window.openMoreMenu === 'function' && typeof window.moreMenuTileHtml === 'function'; } catch (e) {}
      if (!ok) { if (++tries < 200) setTimeout(attempt, 100); return; }
      var original = window.openMoreMenu;
      if (original.__fanShopWrapped) return;
      var wrapped = function () {
        var r = original.apply(this, arguments);
        var grid = document.getElementById('more-menu-grid');
        if (grid && !document.getElementById('more-fanshop-tile')) {
          grid.insertAdjacentHTML('beforeend', window.moreMenuTileHtml('💖', '팬 스킬 상점', '#FF6B9D', 'openFanSkillShop()'));
          if (grid.lastElementChild) grid.lastElementChild.id = 'more-fanshop-tile';
        }
        return r;
      };
      wrapped.__fanShopWrapped = true;
      window.openMoreMenu = wrapped;
    })();
  })();

  setInterval(tick, 200);

  (function hookBagBook() {
    if (typeof window.showBagItemDetail !== 'function') { setTimeout(hookBagBook, 100); return; }
    if (window.__fsBookHooked) return;
    window.__fsBookHooked = true;
    var orig = window.showBagItemDetail;
    window.showBagItemDetail = function (idx) {
      var r = orig.apply(this, arguments);
      try {
        var item = bagItems[idx], ov = $('bag-detail-overlay'), sk = item && item.type === 'skillbook' ? bookSkill(item.name) : null;
        if (sk && ov && !ov.querySelector('#fs-book-use')) {
          var b = document.createElement('button');
          b.id = 'fs-book-use'; b.textContent = '📘 숙련도 올리기';
          b.style.cssText = 'width:100%;padding:12px;margin-bottom:8px;background:linear-gradient(135deg,#C084FC,#7c3aed);border:none;border-radius:12px;color:#fff;font-size:14px;font-weight:900;cursor:pointer;font-family:inherit;';
          b.onclick = function () { openBookPicker(sk); };
          var close = ov.querySelector('button');
          if (close) close.parentNode.insertBefore(b, close); else ov.firstChild.appendChild(b);
        }
      } catch (e) {}
      return r;
    };
  })();
  window.__fsCutIn = cutIn;
  window.__fanSkillsAPI = { masteryLv: function (cid, id) { return masteryLv(cid, id); }, tut: tutModal, giveBook: giveBook, bookName: function (id) { var k = skillById(id); return k ? bookName(k) : ''; }, feedBook: feedBook, SKILLS: SKILLS, SLOTS: SLOTS, loadout: loadLoadout, equip: equip, levelOk: levelOk, hasSkill: function (cid, id) { var sk = skillById(id); return !!sk && hasSkill(cid, sk); }, openEditor: openEditor, openShop: openShop };

  window.__fanSkillsTest = {
    spawnFan: spawnFan, useSkill: useSkill, serves: serves, masteryLv: masteryLv, useCount: useCount, unlockedSkills: unlockedSkills,
    buySkill: buySkill, nearestTarget: nearestTarget, hasSkill: hasSkill, openShop: openShop, openBuyModal: openBuyModal, skillById: skillById,
    state: function () { return F; }, store: loadStore, playerPos: playerPos, evTarget: evTarget
  };
})();

// ════════════════════════════════
// 📖 스킬 습득서 (skill-tome.js)
//
// 팬 광역 스킬을 상점에서 사지 않고 '습득서' 아이템으로 배울 수 있게 한다.
//  - VIP 게이트 선물상자에서 아주 낮은 확률로 나옴 (vip-rush.js 가 window.__giveSkillTome 을 부름)
//  - 가방에서 습득서를 누르면 '📖 멤버에게 가르치기' → 멤버를 고르면 그 멤버가 그 스킬을 배움 (이미 배운 멤버는 못 고름)
//  - 거래소에 등록 가능 (trade.js 의 품목 키는 'bk_tome_<스킬id>' → 기존 'bk_.*' 규칙 그대로 적용, 가격 한도 500만)
// ════════════════════════════════
(function () {
  'use strict';
  var STORE_KEY = 'ph_fanskills';
  var TYPE = 'skilltome';
  var FONT = "font-family:'Noto Sans KR',sans-serif;";
  function API() { return window.__fanSkillsAPI || null; }
  function aoeSkills() { var a = API(); return a ? a.SKILLS.filter(function (s) { return s.aoe; }) : []; }
  function tomeName(sk) { return sk.short + ' 습득서'; }
  function tomeSkill(name) { return aoeSkills().filter(function (k) { return tomeName(k) === name; })[0] || null; }
  function desc(sk) { return sk.icon + ' ' + sk.name + ' 배우기 · 가방에서 열어 멤버를 골라 가르쳐요 (멤버 1명 · 거래소 등록 가능)'; }
  function toast(m) { if (typeof showBagToast === 'function') showBagToast(m); }
  function charIds() {
    try { if (typeof CHARS === 'undefined') return []; return Array.isArray(CHARS) ? CHARS.map(function (c) { return c.id; }) : Object.keys(CHARS); } catch (e) { return []; }
  }
  function charName(cid) { try { return (CHARS[cid] && CHARS[cid].name) || cid; } catch (e) { return cid; } }

  function give(id) {
    var a = API(); if (!a || typeof addToBag !== 'function') return false;
    var sk = a.SKILLS.filter(function (k) { return k.id === id; })[0]; if (!sk) return false;
    var ok = false;
    try { ok = !!addToBag('📖', tomeName(sk), TYPE, 1, desc(sk)); } catch (e) {}
    if (ok) { try { if (typeof saveAll === 'function') saveAll(); } catch (e) {} toast('📖 ' + tomeName(sk) + '을(를) 얻었어요!'); }
    return ok;
  }
  function learn(cid, sk) {
    var a = API();
    if (a && a.hasSkill(cid, sk.id)) return { ok: false, why: '이미 배운 스킬이에요' };
    if (typeof useFromBag !== 'function' || !useFromBag(tomeName(sk), 1)) return { ok: false, why: '습득서가 없어요' };
    var s = {}; try { s = JSON.parse(localStorage.getItem(STORE_KEY) || '{}') || {}; } catch (e) {}
    if (!s[cid] || typeof s[cid] !== 'object') s[cid] = { serves: 0 };
    if (!s[cid].owned || typeof s[cid].owned !== 'object') s[cid].owned = {};
    s[cid].owned[sk.id] = true;
    try { localStorage.setItem(STORE_KEY, JSON.stringify(s)); } catch (e) {}
    try { if (typeof saveAll === 'function') saveAll(); } catch (e) {}
    return { ok: true };
  }
  function qty(sk) { try { var it = bagItems.find(function (i) { return i.name === tomeName(sk); }); return it ? it.qty : 0; } catch (e) { return 0; } }
  function picker(sk) {
    var old = document.getElementById('st-pick'); if (old) old.remove();
    var ov = document.createElement('div'); ov.id = 'st-pick';
    ov.style.cssText = 'position:fixed;inset:0;z-index:2100;background:rgba(0,0,0,.78);display:flex;align-items:center;justify-content:center;padding:18px;' + FONT;
    ov.onclick = function (e) { if (e.target === ov) ov.remove(); };
    function draw(msg) {
      var a = API(), q = qty(sk);
      var rows = charIds().map(function (cid) {
        var has = a && a.hasSkill(cid, sk.id);
        return '<button data-c="' + cid + '" ' + (has ? 'disabled' : '') + ' style="width:100%;display:flex;align-items:center;justify-content:space-between;padding:10px 12px;margin-bottom:7px;border:1.5px solid rgba(255,255,255,' + (has ? '.08' : '.25') + ');border-radius:12px;background:rgba(255,255,255,' + (has ? '.03' : '.09') + ');color:' + (has ? '#777' : '#fff') + ';font-size:14px;font-weight:700;cursor:' + (has ? 'default' : 'pointer') + ';' + FONT + '"><span>' + charName(cid) + '</span><span style="font-size:11px;color:' + (has ? '#7ee8a5' : '#ffd76a') + ';">' + (has ? '✅ 이미 배움' : '가르치기') + '</span></button>';
      }).join('');
      ov.innerHTML = '<div style="width:100%;max-width:330px;max-height:86vh;overflow-y:auto;background:linear-gradient(135deg,#1a1a2e,#2d1b4e);border:2px solid #ffd76a;border-radius:20px;padding:20px 16px;text-align:center;">' +
        '<div style="font-size:40px;">📖</div><div style="font-size:16px;font-weight:900;color:#fff;">' + tomeName(sk) + ' <span style="font-size:12px;color:#aaa;">×' + q + '</span></div>' +
        '<div style="font-size:12px;color:#c9d6ff;margin:4px 0 12px;">누가 ' + sk.icon + ' ' + sk.name + '을(를) 배울까요?</div>' +
        (msg ? '<div style="background:rgba(255,215,0,.16);border:1.5px solid #FFD700;border-radius:10px;padding:8px;margin-bottom:10px;font-size:12px;font-weight:900;color:#fff;">' + msg + '</div>' : '') + rows +
        '<button id="st-x" style="width:100%;margin-top:4px;padding:10px;border:none;border-radius:10px;background:rgba(255,255,255,.1);color:#ccc;font-size:13px;cursor:pointer;' + FONT + '">닫기</button></div>';
      ov.querySelector('#st-x').onclick = function () { ov.remove(); };
      Array.prototype.forEach.call(ov.querySelectorAll('[data-c]:not([disabled])'), function (b) {
        b.onclick = function () {
          var cid = b.getAttribute('data-c');
          if (!window.confirm(charName(cid) + '에게 ' + sk.name + '을(를) 가르칠까요? (습득서 1장 사용)')) return;
          var r = learn(cid, sk);
          if (!r.ok) { draw('⚠️ ' + r.why); return; }
          try { if (typeof renderBag === 'function') renderBag(); } catch (e) {}
          if (qty(sk) <= 0) { ov.remove(); toast('🎉 ' + charName(cid) + '이(가) ' + sk.name + '을(를) 배웠어요!'); var d = document.getElementById('bag-detail-overlay'); if (d) d.remove(); }
          else {
            draw('🎉 ' + charName(cid) + '이(가) ' + sk.name + '을(를) 배웠어요!');
            try { var bd = document.getElementById('bag-detail-overlay'); if (bd) Array.prototype.forEach.call(bd.querySelectorAll('div'), function (dv) { if (!dv.children.length && /^보유:/.test(dv.textContent)) dv.textContent = '보유: ' + qty(sk) + '개'; }); } catch (e) {}
          }
        };
      });
    }
    document.body.appendChild(ov); draw('');
  }

  // 가방 상세에 버튼
  (function hook() {
    if (typeof window.showBagItemDetail !== 'function') { setTimeout(hook, 150); return; }
    if (window.__stHooked) return; window.__stHooked = true;
    var orig = window.showBagItemDetail;
    window.showBagItemDetail = function (idx) {
      var r = orig.apply(this, arguments);
      try {
        var item = bagItems[idx], ov = document.getElementById('bag-detail-overlay'), sk = item && item.type === TYPE ? tomeSkill(item.name) : null;
        if (sk && ov && !ov.querySelector('#st-use')) {
          var b = document.createElement('button'); b.id = 'st-use'; b.textContent = '📖 멤버에게 가르치기';
          b.style.cssText = 'width:100%;padding:12px;margin-bottom:8px;background:linear-gradient(135deg,#F5B942,#FB7185);border:none;border-radius:12px;color:#fff;font-size:14px;font-weight:900;cursor:pointer;font-family:inherit;';
          b.onclick = function () { picker(sk); };
          var close = ov.querySelector('button');
          if (close) close.parentNode.insertBefore(b, close); else ov.firstChild.appendChild(b);
        }
      } catch (e) {}
      return r;
    };
  })();

  // 거래소 품목 등록 (trade.js 가 먼저 불러와졌을 때를 위해 약간 기다림)
  window.__skillTomeItems = function () {
    var out = {};
    aoeSkills().forEach(function (sk) { out['bk_tome_' + sk.id] = { name: tomeName(sk), emoji: '📖', kind: 'bag', type: TYPE, desc: sk.icon + ' ' + sk.name + ' 배우기 (멤버 1명)', min: 2000, max: sk.id === 'finale' ? 10000000 : 5000000 }; });   // 불꽃쇼 습득서만 상한 1000만 (※ 서버 규칙의 가격 한도도 같이 올려야 함)
    return out;
  };
  window.__giveSkillTome = function (id) { return give(id); };
  window.__skillTomeTest = { give: give, learn: learn, tomeName: tomeName };
})();

// ════════════════════════════════
// ☁️ 서버 저장 확장 (cloud-extra.js)
// game.js / auth.js는 건드리지 않고, 지금까지 서버에 안 올라가던 데이터를 같이 올린다.
//
// - 기존에 서버에 올라가던 것(코인, 카드, 가방, 레벨 등)은 그대로 두고,
//   그 밖의 'ph_' 로 시작하는 저장값 전부(히든카드, 기획사, 팬카페, CF, 강화, 화보집, 칭호, 퀘스트 …)를
//   서버 문서의 extraStorage 칸에 한 묶음으로 같이 저장한다.
//   → 앞으로 새로 만드는 기능도 'ph_' 로 시작하는 이름으로 저장하면 자동으로 같이 올라감.
// - 로그인해서 서버 데이터를 불러올 때(원래 있던 동작) 이 묶음도 같이 되돌린다. (불러온 뒤 새로고침되는 건 그대로)
// - 로그인한 상태에서만 서버에 올라간다 (원래 규칙 그대로. 게스트는 이 기기에만 저장)
// - 저장 시점: 기존처럼 saveAll()이 불릴 때 + 'ph_' 저장값이 바뀐 뒤 몇 초 안에 (saveAll을 안 부르는 기능도 빠지지 않게)
//
// 주의: 한 번에 한 기기에서만 플레이한다고 가정함. 두 기기에서 번갈아 하면 나중에 저장한 쪽이 이김.
// ════════════════════════════════
(function () {
  'use strict';

  // ── 설정 ──
  var PREFIX = 'ph_';
  // 이미 game.js의 서버 저장 목록에 있는 것 (여기서 또 올리지 않음)
  var ALREADY = ['ph_nickname', 'ph_coins', 'ph_owned', 'ph_cardCounts', 'ph_bagSlots', 'ph_bagItems', 'ph_inventory',
    'ph_wish', 'ph_stamina', 'ph_currentRoom', 'ph_affection', 'ph_ownedRooms', 'ph_hints', 'ph_learnedSkills',
    'ph_alba', 'ph_playerLevel', 'ph_playerExp', 'ph_cardLevels', 'ph_cardExp', 'ph_storyProgress'];
  // 기기마다 달라야 하는 것 (서버로 옮기면 안 됨)
  var DEVICE_ONLY = ['ph_server_uid', 'ph_lastStaminaRegen', 'ph_bgm_enabled', 'ph_sfx_volume'];
  var MAX_VALUE = 300000;        // 값 하나가 이 글자 수를 넘으면 올리지 않음 (서버 문서 크기 제한 보호)
  var MAX_TOTAL = 700000;        // 전체 합이 이 글자 수를 넘으면 나머지는 올리지 않음
  var SAVE_THROTTLE_MS = 4000;   // 저장값이 바뀐 뒤 서버 저장을 부르는 간격(최대 이 간격에 한 번)

  // ════════ 순수 로직 ════════
  function isExtraKey(k) {
    return typeof k === 'string' && k.indexOf(PREFIX) === 0 && ALREADY.indexOf(k) === -1 && DEVICE_ONLY.indexOf(k) === -1;
  }

  function collect() {                                       // 지금 기기의 'ph_' 저장값 중 올릴 것들
    var out = {}, total = 0, skipped = [];
    try {
      for (var i = 0; i < localStorage.length; i++) {
        var k = localStorage.key(i);
        if (!isExtraKey(k)) continue;
        var v = localStorage.getItem(k);
        if (v === null) continue;
        if (v.length > MAX_VALUE || total + v.length > MAX_TOTAL) { skipped.push(k); continue; }
        out[k] = v; total += v.length;
      }
    } catch (e) {}
    if (skipped.length) { try { console.warn('☁️ 너무 커서 서버에 못 올린 저장값:', skipped.join(', ')); } catch (e) {} }
    return out;
  }

  function applyExtra(data) {                                // 서버에서 받은 묶음을 이 기기에 되돌림
    var n = 0;
    if (!data || typeof data.extraStorage !== 'object' || !data.extraStorage) return n;
    Object.keys(data.extraStorage).forEach(function (k) {
      var v = data.extraStorage[k];
      if (!isExtraKey(k) || typeof v !== 'string') return;
      try { localStorage.setItem(k, v); n++; } catch (e) {}
    });
    return n;
  }

  // ════════ 기존 함수에 연결 ════════
  // (함수가 아직 로드 안 됐으면 잠깐 기다렸다가 시도 — 로더가 파일을 순서 없이 불러오기 때문)
  function whenReady(test, fn) {
    var tries = 0;
    (function attempt() {
      var ok = false;
      try { ok = test(); } catch (e) {}
      if (ok) { fn(); return; }
      if (++tries < 200) setTimeout(attempt, 100);
    })();
  }

  var restoring = false;   // 서버에서 불러오는 중에는 저장을 부르지 않음 (불러오다 말고 덮어쓰는 사고 방지)

  // 1) 서버에 올리는 데이터에 extraStorage 추가
  whenReady(function () { return typeof window.getPocaServerPayload === 'function'; }, function () {
    var original = window.getPocaServerPayload;
    if (original.__cloudExtraWrapped) return;
    var wrapped = function () {
      var payload = original.apply(this, arguments);
      try {
        payload.extraStorage = collect();
        payload.extraSavedAt = new Date().toISOString();
      } catch (e) {}
      return payload;
    };
    wrapped.__cloudExtraWrapped = true;
    window.getPocaServerPayload = wrapped;
  });

  // 2) 서버 데이터를 불러올 때 extraStorage도 되돌림
  whenReady(function () { return typeof window.restorePocaDataFromServer === 'function'; }, function () {
    var original = window.restorePocaDataFromServer;
    if (original.__cloudExtraWrapped) return;
    var wrapped = function (data) {
      restoring = true;
      setTimeout(function () { restoring = false; }, 8000);
      var r = original.apply(this, arguments);
      try { applyExtra(data); } catch (e) {}
      return r;
    };
    wrapped.__cloudExtraWrapped = true;
    window.restorePocaDataFromServer = wrapped;
  });

  // 3) 'ph_' 저장값이 바뀌면 (saveAll을 안 부르는 기능도) 서버 저장을 부름
  var saveTimer = null;
  function queueSave() {
    if (saveTimer || restoring) return;
    saveTimer = setTimeout(function () {
      saveTimer = null;
      if (restoring) return;
      if (typeof window.schedulePocaServerSave === 'function') window.schedulePocaServerSave('extra');
    }, SAVE_THROTTLE_MS);
  }
  try {
    var proto = (typeof Storage !== 'undefined') ? Storage.prototype : null;
    if (proto && typeof proto.setItem === 'function' && !proto.setItem.__cloudExtraWrapped) {
      var originalSetItem = proto.setItem;
      var wrappedSetItem = function (k) {
        var r = originalSetItem.apply(this, arguments);
        try { if (this === window.localStorage && isExtraKey(String(k))) queueSave(); } catch (e) {}
        return r;
      };
      wrappedSetItem.__cloudExtraWrapped = true;
      proto.setItem = wrappedSetItem;
    }
  } catch (e) {}

  window.__cloudExtraTest = { isExtraKey: isExtraKey, collect: collect, applyExtra: applyExtra, SAVE_THROTTLE_MS: SAVE_THROTTLE_MS };
})();

// ════════════════════════════════
// ⚖️ 스태미나 밸런스 패치 (stamina-balance.js)
//
// 1) 에너지 드링크 전 종류 회복량 ×3 (가격은 그대로)
//      사과주스 10→30 / 딸기스무디 20→60 / 에너지드링크 30→90
//      + 거기에 전부 DRINK_BONUS(+70) 추가 → 사과주스 100 / 딸기스무디 130 / 에너지드링크 160
// 2) 일반 맵(숲·해변·공원·호수·광장) 탐험의 소원의 조각 드랍률 ÷3
//      (원래 아이템 1개당 0.5% → 약 0.17%)
//
// game.js는 건드리지 않고, 로더에 이 파일만 game.js / mystery-explore.js 뒤에 등록하면 된다.
// 신비의 섬 소원의 샘 확률은 mystery-explore.js 안의 SPRING_COST 값으로 조절한다.
// ════════════════════════════════
(function () {
  'use strict';

  var DRINK_MULT = 3;   // 드링크 회복량 배수
  var DRINK_BONUS = 70; // ×배수 한 다음 전 종류에 더하는 회복량 (스태미나 최대치 3000 기준)
  var WISH_DIV = 3;     // 일반 맵 소원의 조각 드랍률을 나누는 값

  var DRINK_BASE = { '사과주스': 10, '딸기스무디': 20, '에너지드링크': 30 };
  function drinkUp(name) { return (DRINK_BASE[name] || 10) * DRINK_MULT + DRINK_BONUS; }
  window.__drinkUp = drinkUp;   // drink-bulk.js 가 같은 값을 쓰도록

  // 가방에 이미 있는 드링크 설명 글씨를 바뀐 회복량으로 맞춤 (여러 번 실행해도 값이 안 변함)
  function fixDrinkDescs() {
    var changed = false;
    bagItems.forEach(function (it) {
      if (it.type !== 'drink' || !(it.name in DRINK_BASE)) return;
      var d = '스태미나 +' + drinkUp(it.name) + ' 회복 음료';
      if (it.desc !== d) { it.desc = d; changed = true; }
    });
    if (changed) saveBag();
  }

  // 일반 맵 탐험이 시작된 직후, 소원의 조각 칸 중 2/3를 일반 재료로 되돌림 → 드랍률 ÷3
  function thinWish(placeId) {
    if (placeId === 'mystery') return;                         // 신비의 섬은 mystery-explore.js가 담당
    if (!document.getElementById('explore-overlay')) return;   // 스태미나 부족 등으로 탐험이 안 열렸으면 무시
    var mats = EXPLORE_MATERIALS[placeId];
    if (!mats) return;
    var luck = typeof getEquippedStat === 'function' ? getEquippedStat('luck') : 0;
    var rareChance = Math.min(0.80, 0.30 + luck / 100);
    exploreItems.forEach(function (item, idx) {
      if (!item || !item.isWish) return;
      if (Math.random() < 1 / WISH_DIV) return;                // 1/3은 그대로 소원의 조각
      var isRare = Math.random() < rareChance;
      var pool = isRare ? mats.rare : mats.normal;
      item.name = pool[Math.floor(Math.random() * pool.length)];
      item.isWish = false;
      item.isRare = isRare;
      var el = document.getElementById('explore-item-' + idx);
      if (el) el.textContent = '✨';
    });
  }

  function ready() {
    try {
      return typeof window.useDrinkFromBag === 'function' &&
        typeof window.buyDrink === 'function' &&
        typeof window.showBagItemDetail === 'function' &&
        typeof window.startExplore === 'function' &&
        typeof bagItems !== 'undefined' &&
        typeof exploreItems !== 'undefined' &&
        typeof EXPLORE_MATERIALS !== 'undefined';
    } catch (e) { return false; }
  }

  function init() {
    if (!ready()) { setTimeout(init, 50); return; }
    if (window.__staminaBalancePatched) return;   // 두 번 로드돼도 배수가 겹치지 않게
    window.__staminaBalancePatched = true;

    // ── 1) 드링크 사용: 회복량 ×3 ──
    window.useDrinkFromBag = function (idx) {
      var item = bagItems[idx];
      if (!item) return;
      var up = drinkUp(item.name);
      useFromBag(item.name, 1);
      stamina = Math.min(STAMINA_MAX, stamina + up);
      saveStamina();
      saveAll();
      renderBag();
      showBagToast(item.emoji + ' ' + item.name + ' 사용! ⚡ 스태미나 +' + up);
    };

    // 드링크 구매 시 가방 설명 글씨도 ×3 값으로
    var origBuy = window.buyDrink;
    window.buyDrink = function (itemName, price, staminaUp) {
      var r = origBuy.call(this, itemName, price, (staminaUp || 0) * DRINK_MULT);
      fixDrinkDescs();
      return r;
    };

    // 아이템 상세를 열 때마다 설명 글씨 보정 (출석 보상 등으로 들어온 옛 설명 포함)
    var origDetail = window.showBagItemDetail;
    window.showBagItemDetail = function () {
      fixDrinkDescs();
      return origDetail.apply(this, arguments);
    };

    fixDrinkDescs();

    // ── 2) 일반 맵 소원의 조각 ÷3 ──
    var origExplore = window.startExplore;
    window.startExplore = function (placeId) {
      var r = origExplore.apply(this, arguments);
      try { thinWish(placeId); } catch (e) {}
      return r;
    };
  }

  init();
})();

// 🥤 가방에서 드링크 여러 개 한번에 사용 (1개 / 5개 / 10개 / 가득 채우기)
(function () {
  'use strict';
  // stamina-balance.js 의 회복량(기본 ×3)과 똑같이 맞춤
  var MULT = 3;
  var BONUS = 70;      // stamina-balance.js 의 DRINK_BONUS 와 같은 값
  var UP = { '사과주스': 10 * MULT + BONUS, '딸기스무디': 20 * MULT + BONUS, '에너지드링크': 30 * MULT + BONUS };
  function useDrinks(name, n) {
    var item = bagItems.find(function (i) { return i.name === name; });
    if (!item) return;
    var up = (window.__drinkUp ? window.__drinkUp(name) : (UP[name] || 10 * MULT + BONUS));
    var room = STAMINA_MAX - stamina;
    if (room <= 0) { showBagToast('⚡ 스태미나가 이미 가득 찼어요!'); return; }
    var need = Math.ceil(room / up);               // 가득 채우는 데 필요한 개수
    var cnt = Math.max(1, Math.min(n === 'max' ? need : n, item.qty, need));
    var emoji = item.emoji;
    useFromBag(name, cnt);
    stamina = Math.min(STAMINA_MAX, stamina + up * cnt);
    saveStamina(); saveAll(); renderBag();
    showBagToast(emoji + ' ' + name + ' ' + cnt + '개 사용! ⚡ 스태미나 +' + (up * cnt));
  }
  window.__useDrinks = function (name, n) {
    useDrinks(name, n);
    var o = document.getElementById('bag-detail-overlay'); if (o) o.remove();
  };
  function install() {
    if (typeof showBagItemDetail !== 'function' || !window.__staminaBalancePatched) return false;
    if (window.__drinkBulk) return true;
    window.__drinkBulk = true;
    var orig = showBagItemDetail;
    window.showBagItemDetail = function (idx) {
      orig.apply(this, arguments);
      try {
        var item = bagItems[idx];
        var ov = document.getElementById('bag-detail-overlay');
        if (!item || item.type !== 'drink' || !ov) return;
        var btn = Array.prototype.find.call(ov.querySelectorAll('button'), function (b) { return b.textContent.indexOf('사용하기') >= 0; });
        if (!btn) return;
        var nm = JSON.stringify(item.name).replace(/"/g, '&quot;');
        var st = 'flex:1;padding:11px 0;border:none;border-radius:10px;color:#fff;font-size:13px;font-weight:700;cursor:pointer;font-family:\'Noto Sans KR\',sans-serif;background:linear-gradient(135deg,#60a5fa,#C084FC);';
        var row = document.createElement('div');
        row.style.cssText = 'display:flex;gap:6px;margin-bottom:8px;';
        row.innerHTML = [[1, '1개'], [5, '5개'], [10, '10개'], ['max', '가득']].map(function (a) {
          var v = a[0] === 'max' ? "'max'" : a[0];
          return '<button onclick="__useDrinks(' + nm + ',' + v + ')" style="' + st + '">' + a[1] + '</button>';
        }).join('');
        btn.parentNode.replaceChild(row, btn);
      } catch (e) { /* 실패하면 기존 버튼 그대로 */ }
    };
    return true;
  }
  var n = 0;
  (function t() { if (!install() && n++ < 300) setTimeout(t, 200); })();
})();

// ════════════════════════════════
// 🎬 방송국 앞 원정 (broadcast-expedition.js)
//
// 특별탐험 장소 목록에 '방송국 앞'을 하나 더 넣는다.
// 이 장소만 생물/먹이 대신 새 방식으로 진행하고, 천공성 유적·달빛 회랑·공방 지하는 그대로다.
//
// 방식
//  - 지도 아무 데나 누르면 캐릭터(얼굴 + 얼굴에 붙은 카드)가 그쪽으로 걸어간다.
//  - 지도 곳곳에 ❗가 떠 있고, 걸어가서 닿으면 이벤트가 시작된다 (뭐가 나올지는 닿아봐야 안다).
//      📸 셔터 찬스(타이밍 게이지) / 💌 팬레터(3번 탭) / 🎁 굿즈 상자(3개 중 고르기)
//  - 이벤트가 끝날 때마다 가끔 특별 이벤트가 뜬다 (제한시간 있음, 놓치면 사라짐)
//      🌟 황금 셔터(레어 목격정보) / 🔥 레전드 순간(5초 연타)
//  - 이벤트 1번 = 스태미나 30 (맵에서 걷는 건 공짜)
//  - 보상: 코인 / 카드 경험치 / 특별탐험 재료 / 촬영 소품 / 🖼️ 프리미엄 조각
//    프리미엄 조각은 가방에 쌓인다 (100개 = 프리미엄 카드 1장, 교환은 다음 단계에서 만든다)
//
// ▶ 공연장(3번째 맵): 우등생별 1개로 입장 → 이벤트 20번 → 앵콜 스테이지 → 시크릿 포토랩(photolab.js)
//    필름(🎞️)은 여기서 파밍. 현상 효과(photolab.js의 getEngraveBonus)는 아래 engB() 로 전부 연결돼 있음.
//
// 값을 바꾸고 싶으면 아래 [설정]만 고치면 된다. game.js / special-explore.js는 건드리지 않는다.
// ════════════════════════════════
(function () {
  'use strict';

  // ── 설정 ──
  var LOC_ID = 'broadcast_front';
  var BG_URL = 'https://raw.githubusercontent.com/chaei7775/Poca-house/main/special-broadcast_front.png';
  var IMG_W = 941, IMG_H = 1672;      // 배경 이미지 크기 (불러오면 실제 크기로 갱신)
  var STAMINA_COST = 30;              // 이벤트 1번당 스태미나
  var ENCORE_N = 20;                  // 공연장: 이벤트 몇 번 하면 앵콜 스테이지(포토랩)가 열리는지
  var RUN_KEY = 'ph_concertRun';      // 공연장 진행 저장 (중간에 나가도 별 안 날리고 이어서 함)
  var FILM_NAME = '필름', FILM_EMOJI = '🎞️';
  var DEV_NAME = '현상액', DEV_EMOJI = '🧪';   // 포토랩 옵션 강화 재료 (공연장에서만 나옴)
  var SPEED = 200;                    // 걷는 속도 (px/초)
  var HIT_R = 36;                     // 이 거리 안으로 들어가면 이벤트 시작 (px)
  var NORMAL_MAX = 2;                 // 지도에 동시에 떠 있는 ❗ 수
  var RARE_CHANCE = 0.08;             // 이벤트 끝날 때 황금 셔터가 뜰 확률
  var LEGEND_CHANCE = 0.02;           // 이벤트 끝날 때 레전드 순간이 뜰 확률
  var RARE_TTL = 30, LEGEND_TTL = 25; // 특별 이벤트 제한시간 (초)
  var LEGEND_NEED = 22, LEGEND_SEC = 5; // 레전드: 5초 안에 22번 탭
