  function finish(ev, type, grade, love) {
    var r = rewardFor(type, grade);
    if (S && S.bonus > 1) { r.coins = Math.round(r.coins * S.bonus); r.exp = Math.round(r.exp * S.bonus); }   // 🏅 스킬 숙련도 보너스 (fan-skills.js)
