    }
    if (MAP.pieces && success && r.pieces > 0 && Math.random() < engB('pieceExtra')) { r.pieces += 1; notes.push({ icon: '✨', text: '현상 효과! 조각 +1', color: '#7dd3fc' }); }
    if (MAP.pieces) boxAdd(r.pieces);   // 이벤트 1번 = 상자 진행 +1 (프리미엄 카드 효과로 나온 조각은 상자에 덤으로 쌓임)
    r.pieces = 0;
