      '<button id="bc-shot" style="' + BTN + '">📸 찰칵!</button>');

    function loop(ts) {
      var m = $('bc-mark');
      if (!m || locked) return;
      var dt = last ? Math.min(0.05, (ts - last) / 1000) : 0;
      last = ts;
      pos += dir * spd * dt;
