      burstAt(G.px + Math.cos(a) * d, G.py + Math.sin(a) * d, id === 'finale' ? 32 : 30, C.cols, id === 'finale' ? 240 : 200, i * (id === 'finale' ? 0.12 : 0.1), id === 'finale' || id === 'encore');
    }
