  // ── 퀘스트 탭에 등록 (QUESTS 는 game.js 의 const 객체 — 안에 항목만 추가) ──
  var DETECT = {};
  function register() {
    if (typeof QUESTS === 'undefined') return false;
    Object.keys(NEW).forEach(function (id) {
      var q = NEW[id];
      DETECT[id] = q.detect;
      if (!QUESTS[id]) {
        QUESTS[id] = { title: q.title, desc: q.desc, condition: q.condition, rewardCoins: q.rewardCoins, rewardExp: q.rewardExp, type: q.type };
      }
    });
    return true;
  }

  // ── 한 번에 하나씩 확인 (한꺼번에 완료 팝업이 쌓이지 않게) ──
  function check() {
    try {
      if (typeof questProgress === 'undefined' || typeof checkQuestProgress !== 'function') return;
      var ids = Object.keys(DETECT);
      for (var i = 0; i < ids.length; i++) {
        var id = ids[i];
        if (questProgress[id] === 'done') continue;
        var ok = false;
        try { ok = !!DETECT[id](); } catch (e) {}
        if (ok) { checkQuestProgress(NEW[id].condition); return; }
      }
    } catch (e) {}
  }
  // 강화 단계는 카드가 깨져도 '달성 기록'은 남기기
  function recordMilestones() {
    var m = maxEnhLevel();
    if (m >= 1) flag('enh1'); if (m >= 5) flag('enh5'); if (m >= 10) flag('enh10');
    if (anyTrans()) flag('trans');
  }

  // ── 첫 사용 감지 후킹 (원래 함수는 그대로 실행) ──
  function hookLater(name, mark) {
    (function tryHook() {
      if (typeof window[name] !== 'function') { setTimeout(tryHook, 100); return; }
      var orig = window[name];
      if (orig.__q2Hooked) return;
      var wrapped = function () {
        var r = orig.apply(this, arguments);
        try { mark.apply(null, arguments); } catch (e) {}
        return r;
      };
      wrapped.__q2Hooked = true;
      window[name] = wrapped;
    })();
  }
  hookLater('startExplore', function () { flag('explore'); });
  hookLater('startFishing', function () { flag('fishing'); flag('explore'); });
  hookLater('giveGift', function () { flag('gift'); });
  hookLater('doRecombine', function () { flag('recombine'); });
  hookLater('useDrinkFromBag', function () { flag('drink'); });
  // 어떤 경로로 가방 음료를 눌러도 '이미 가득 찼어요' 안내가 뜨면 드링크 사용으로 인정 (다른 파일이 useDrinkFromBag 을 덮어써도 동작)
  hookLater('showBagToast', function (msg) { if (/스태미나가 이미 가득/.test(String(msg || ''))) { try { window.dispatchEvent(new Event('ph-drink-tried')); } catch (e) {} } });
  try { window.addEventListener('ph-drink-tried', function () { flag('drink'); }); } catch (e) {}   // 스태미나가 가득 차서 못 마신 경우도 완료
  hookLater('expandBag', function () { flag('bag'); });
  hookLater('startSpecialExplore', function () { flag('expedition'); });
  hookLater('showWishCrystalEarned', function () { flag('crystal'); });

  (function boot() {
    if (!register()) { setTimeout(boot, 200); return; }
    setInterval(function () { recordMilestones(); check(); }, 900);
    // 퀘스트 탭을 열 때 목록이 새 항목을 바로 보여주도록 한 번 더 그림
    var tries = 0;
    (function hookList() {
      if (typeof window.renderQuestList !== 'function') { if (tries++ < 50) setTimeout(hookList, 100); return; }
      var cur = document.getElementById('screen-quest');
      if (cur && cur.classList.contains('active')) { try { window.renderQuestList(); } catch (e) {} }
    })();
  })();
})();

// shop-coin-sync.js
// 코인 숫자가 바로 안 바뀌는 문제 보정
// - 상점 위 '🍔 보유: N코인' 숫자 (재료를 팔거나 살 때)
// - 포카마을(지도) 화면 맨 위 오른쪽 🍔 코인 숫자 (탐험 갔다 와서 잡화점에서 팔 때 안 바뀌던 것)
// - 알바/퀘스트 화면 위쪽 코인 숫자
// 코인이 바뀌면 0.4초 안에 모든 숫자를 맞춘다 (어떤 경로로 코인이 바뀌어도 동일)
(function applyShopCoinSync() {
  if (typeof window.sellMaterial !== 'function') { setTimeout(applyShopCoinSync, 100); return; }
  if (window.__shopCoinSyncApplied) return;
  window.__shopCoinSyncApplied = true;

  // game.js의 updateCoinsDisplay가 챙기지 않는 숫자 칸들
  var EXTRA_IDS = ['shop-coin-display', 'coin-map', 'coin-quest', 'coin-alba-burger', 'coin-alba-cafe'];

  function syncShopCoin() {
    try {
      if (typeof coins === 'undefined') return;
      var want = String(coins);
      for (var i = 0; i < EXTRA_IDS.length; i++) {
        var el = document.getElementById(EXTRA_IDS[i]);
        if (el && el.textContent !== want) el.textContent = want;
      }
      if (typeof updateCoinsDisplay === 'function') updateCoinsDisplay();
    } catch (e) {}
  }

  // 판매 직후 즉시 갱신
  var origSell = window.sellMaterial;
  window.sellMaterial = function () {
    var r = origSell.apply(this, arguments);
    syncShopCoin();
    return r;
  };

  setInterval(syncShopCoin, 400);
  syncShopCoin();
})();

// bond-gift.js
// 💞 인연 상세 화면(호감도/스토리)에 '💝 선물하기' 버튼 추가
// - 기존 선물 메뉴(showGiftMenu / giveGift)를 그대로 재사용
// - 선물 후 호감도 표시 자동 갱신
// - 호감도 조건이 안 되는 아이돌(예: 아라)은 잠금 표시
(function applyBondGift() {
  var need = ['openBondDetail', 'showGiftMenu', 'giveGift'];
  for (var i = 0; i < need.length; i++) {
    if (typeof window[need[i]] !== 'function') { setTimeout(applyBondGift, 100); return; }
  }
  if (window.__bondGiftApplied) return;
  window.__bondGiftApplied = true;

  function reqAffOf(charId) {
    try { return (CHAR_MEET[charId] && CHAR_MEET[charId].reqAff) || 0; } catch (e) { return 0; }
  }
  function gateOf(charId) {
    try { return getAffectionGateLevel(charId); } catch (e) { return 99; }
  }

  // 선물 선택창 열기 (기존 meet-overlay + showGiftMenu 재사용)
  window.openBondGift = function (charId) {
    var old = document.getElementById('meet-overlay');
    if (old) old.remove();
    var overlay = document.createElement('div');
    overlay.id = 'meet-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:500;background:rgba(0,0,0,0.85);display:flex;flex-direction:column;justify-content:flex-end;';
    overlay.innerHTML = '<div style="padding:24px;background:rgba(20,10,30,0.98);border-radius:20px 20px 0 0;">' +
      '<button onclick="document.getElementById(\'meet-overlay\').remove()" style="width:100%;padding:12px;background:rgba(255,255,255,0.08);border:none;border-radius:12px;color:#aaa;font-size:14px;cursor:pointer;font-family:\'Noto Sans KR\',sans-serif;">돌아가기</button></div>';
    document.body.appendChild(overlay);
    try { showGiftMenu(charId); } catch (e) { console.error('[bond-gift] showGiftMenu error:', e); }
    // (선물창을 여는 것만으로는 '처음 만나는 인연'을 깨지 않음 — 만나기/대화 버튼을 눌러야 함)
  };

  function addButton(charId) {
    var box = document.querySelector('#bond-detail-overlay .bond-affection');
    if (!box) return;
    var old = document.getElementById('bond-gift-btn');
    if (old) old.remove();
    var btn = document.createElement('button');
    btn.id = 'bond-gift-btn';
    var locked = gateOf(charId) < reqAffOf(charId);
    if (locked) {
      btn.textContent = '🔒 호감도 ' + reqAffOf(charId) + ' 이상이면 선물할 수 있어요';
      btn.disabled = true;
      btn.style.cssText = 'width:100%;margin-top:14px;padding:13px;background:rgba(255,255,255,0.08);border:none;border-radius:12px;color:#888;font-size:13px;font-weight:700;font-family:"Noto Sans KR",sans-serif;';
    } else {
      btn.textContent = '💝 선물하기';
      btn.style.cssText = 'width:100%;margin-top:14px;padding:13px;background:linear-gradient(135deg,#FF6B9D,#C084FC);border:none;border-radius:12px;color:#fff;font-size:14px;font-weight:700;cursor:pointer;font-family:"Noto Sans KR",sans-serif;';
      btn.onclick = function () { window.openBondGift(charId); };
    }
    box.appendChild(btn);
  }

  // 상세 화면이 열릴 때 버튼 추가
  var origOpen = window.openBondDetail;
  window.openBondDetail = function (charId) {
    var r = origOpen.apply(this, arguments);
    try { addButton(charId); } catch (e) { console.error('[bond-gift] addButton error:', e); }
    return r;
  };

  // 선물 후 호감도 표시 갱신
  var origGive = window.giveGift;
  window.giveGift = function () {
    var r = origGive.apply(this, arguments);
    try {
      var o = document.getElementById('bond-detail-overlay');
      if (o && o.classList.contains('show') && typeof currentCharId !== 'undefined' && currentCharId) {
        window.openBondDetail(currentCharId);
      }
    } catch (e) {}
    return r;
  };

  // 인연 화면에서 아이돌 카드를 눌러 상세를 여는 것 = '처음 만나는 인연' (선물 전에 먼저 완료)
  // (giveGift 가 상세를 다시 그릴 때도 불리므로, 처음 한 번만 판정)
  var _origDetail = window.openBondDetail;
  if (typeof _origDetail === 'function' && !_origDetail.__metHooked) {
    window.openBondDetail = function () {
      var r = _origDetail.apply(this, arguments);
      try { if (typeof checkQuestProgress === 'function') checkQuestProgress('first_meet'); } catch (e) {}
      return r;
    };
    window.openBondDetail.__metHooked = true;
  }
})();

// starter-boost.js
// 초반 스태미나 부담 완화 (새 계정 전용)
//  1) 새 계정은 스태미나 100 대신 STARTER_STAMINA로 시작
//  2) 초반 퀘스트(첫 알바/뽑기/만남/등교/탐험/음료 사용)를 깰 때마다 사과주스 지급
// 기존 계정(이미 카드·알바 기록이 있는 계정)은 아무 영향 없음
(function starterBoost() {
  // ── 여기 숫자만 바꾸면 됨 ──
  var STARTER_STAMINA = 300;                 // 새 계정 시작 스태미나
  var DRINK_EMOJI = '🧃', DRINK_NAME = '사과주스';
  var REWARDS = {                            // 퀘스트 조건 → 사과주스 개수 (1개 = 스태미나 +100)
    first_alba: 2,      // 첫 알바
    first_gacha: 3,     // 첫 카드 뽑기
    first_meet: 3,      // 첫 아이돌 만남/선물
    first_school: 4,    // 첫 등교
    first_explore: 4,   // 첫 탐험
    q2_drink: 4         // 첫 음료 사용
  };
  var FLAG = 'ph_starter_v1';                // '1' = 새 계정(혜택 대상), 'no' = 해당 없음
  var GIVEN = 'ph_starter_given';            // 이미 받은 보상 기록

  function ready() {
    try {
      return typeof addToBag === 'function' && typeof saveStamina === 'function' &&
             typeof window.checkQuestProgress === 'function' && typeof window.checkStoryCondition === 'function' &&
             typeof owned !== 'undefined' && typeof albaDone !== 'undefined' &&
             typeof bagItems !== 'undefined' && typeof stamina !== 'undefined';
    } catch (e) { return false; }
  }

  function isFreshAccount() {
    try {
      return owned.length === 0 && albaDone === 0 && bagItems.length === 0 &&
             Object.keys(questProgress || {}).length === 0;
    } catch (e) { return false; }
  }

  function grant(cond) {
    try {
      var n = REWARDS[cond];
      if (!n) return;
      if (localStorage.getItem(FLAG) !== '1') return;
      var given = JSON.parse(localStorage.getItem(GIVEN) || '{}');
      if (given[cond]) return;
      if (!addToBag(DRINK_EMOJI, DRINK_NAME, 'drink', n, '스태미나 +100 회복 음료')) return; // 가방이 꽉 차면 다음 기회에
      given[cond] = 1;
      localStorage.setItem(GIVEN, JSON.stringify(given));
      setTimeout(function () {
        if (typeof showBagToast === 'function') showBagToast(DRINK_EMOJI + ' ' + DRINK_NAME + ' ' + n + '개 받았어요! 🎒 가방에서 마실 수 있어요');
      }, 700);
    } catch (e) { console.error('[starter-boost] grant error:', e); }
  }

  function init() {
    if (!ready()) { setTimeout(init, 100); return; }
    if (window.__starterBoostApplied) return;
    window.__starterBoostApplied = true;

    // 1) 처음 접속한 새 계정이면 시작 스태미나 올리기 (한 번만 판정)
    if (localStorage.getItem(FLAG) === null) {
      if (isFreshAccount()) {
        localStorage.setItem(FLAG, '1');
        if (stamina < STARTER_STAMINA) { stamina = STARTER_STAMINA; saveStamina(); }
      } else {
        localStorage.setItem(FLAG, 'no');
      }
    }

    // 2) 퀘스트 조건이 발생할 때 보상 지급 (한 조건당 한 번)
    var origCheck = window.checkQuestProgress;
    window.checkQuestProgress = function (condition) {
      var r = origCheck.apply(this, arguments);
      grant(condition);
      return r;
    };
    var origStory = window.checkStoryCondition;
    window.checkStoryCondition = function (condition) {
      var r = origStory.apply(this, arguments);
      grant(condition);
      return r;
    };

    // 3) 로그인으로 서버 데이터를 불러오는 계정은 새 계정이 아님 → 혜택 대상에서 제외
    (function hookRestore() {
      if (typeof window.restorePocaDataFromServer !== 'function') { setTimeout(hookRestore, 200); return; }
      var origRestore = window.restorePocaDataFromServer;
      window.restorePocaDataFromServer = function (data) {
        if (data) { try { localStorage.setItem(FLAG, 'no'); } catch (e) {} }
        return origRestore.apply(this, arguments);
      };
    })();
  }
  init();
})();

// ════════════════════════════════════════════════════════════
// 🎟️ 신규 유저 뽑기권 (newbie-tickets.js) — 처음엔 아이돌부터 만나게 하고, 뽑기권을 단계별로 나눠 준다
// · 새 계정(starter-boost.js 가 'ph_starter_v1'='1' 로 표시한 계정)에만 적용. 기존 계정은 아무 영향 없음.
// · 뽑기권이 있으면 코인 대신 뽑기권이 먼저 쓰인다 (1회=1장, 3회=3장).
// · 첫 뽑기는 SR 이상 아이돌 카드가 보장된다.
// ✏️ 고치는 법: 아래 GRANTS 숫자만 바꾸면 됨
// ════════════════════════════════════════════════════════════
(function () {
  'use strict';
  var KEY = 'ph_gachaTickets', GIVEN = 'ph_ticket_given', FIRST = 'ph_firstpull_done';
  var GRANTS = {                // 조건 → 지급 장수
    start: 5,                   // 처음 접속
    first_meet: 5,              // 아이돌 첫 만남(선물/대화)
    first_alba: 5,              // 첫 알바
    first_school: 5,            // 첫 등교
    attend_3: 5,                // 출석 3일차
    attend_7: 5                 // 출석 7일차
  };

  function J(k, d) { try { var v = JSON.parse(localStorage.getItem(k) || 'null'); return v === null ? d : v; } catch (e) { return d; } }
  function tickets() { return parseInt(localStorage.getItem(KEY) || '0') || 0; }
  function setTickets(n) { try { localStorage.setItem(KEY, String(Math.max(0, n))); } catch (e) {} }
  function isNew() { return localStorage.getItem('ph_starter_v1') === '1'; }

  function toast(msg) { try { if (typeof showBagToast === 'function') showBagToast(msg); } catch (e) {} }
  function grant(cond) {
    try {
      var n = GRANTS[cond]; if (!n || !isNew()) return;
      var g = J(GIVEN, {}); if (g[cond]) return;
      g[cond] = 1; localStorage.setItem(GIVEN, JSON.stringify(g));
      setTickets(tickets() + n);
      setTimeout(function () { toast('🎟️ 뽑기권 ' + n + '장을 받았어요! ✨ 뽑기에서 쓸 수 있어요'); refreshUI(); }, 900);
    } catch (e) {}
  }

  // ── 뽑기: 뽑기권 먼저 사용 + 첫 뽑기 SR 보장 ──
  function hookDraw() {
    if (typeof window.doDraw !== 'function' || typeof window.drawOne !== 'function') { setTimeout(hookDraw, 100); return; }
    if (window.doDraw.__tk) return;
    var orig = window.doDraw;
    var w = function (count) {
      var paid = false, cost = 0;
      try {
        var t = tickets();
        if (t >= count) {
          cost = count === 1 ? CONFIG.gacha.one : CONFIG.gacha.three;
          coins += cost; paid = true;              // 원래 함수가 코인을 빼 가므로 미리 채워 두면 결과적으로 0
          setTickets(t - count);
        }
        if (!localStorage.getItem(FIRST) && isNew() && owned.length === 0) {
          localStorage.setItem(FIRST, '1');
          var real = Math.random, first = true;     // 첫 번째 난수만 0.15 → SR 구간, 이후는 정상
          Math.random = function () { if (first) { first = false; Math.random = real; return 0.15; } return real(); };
        }
      } catch (e) {}
      var r = orig.apply(this, arguments);
      try { if (paid) { saveAll(); if (typeof updateCoinsDisplay === 'function') updateCoinsDisplay(); } } catch (e) {}
      setTimeout(refreshUI, 200);
      return r;
    };
    w.__tk = true; window.doDraw = w;
  }

  // ── 화면: 뽑기 버튼에 뽑기권 표시 ──
  function refreshUI() {
    try {
      var scr = document.getElementById('screen-gacha'); if (!scr) return;
      var t = tickets();
      var b1 = scr.querySelector('.gacha-btn-1'), b3 = scr.querySelector('.gacha-btn-3');
      function lab(btn, n, base) {
        if (!btn) return; var sp = btn.querySelector('span'); if (!sp) return;
        if (!sp.dataset.base) sp.dataset.base = sp.textContent;
        sp.textContent = t >= n ? '🎟️ ' + n + '장' : sp.dataset.base;
      }
      lab(b1, 1); lab(b3, 3);
      var bar = document.getElementById('ticket-bar');
      if (t > 0 && b1) {
        if (!bar) { bar = document.createElement('div'); bar.id = 'ticket-bar';
          bar.style.cssText = 'margin-top:30px;margin-bottom:-18px;padding:7px 16px;border-radius:20px;background:rgba(255,215,0,.15);border:1.5px solid #FFD700;color:#FFD700;font-size:13px;font-weight:900;';
          b1.parentNode.parentNode.insertBefore(bar, b1.parentNode); }
        bar.textContent = '🎟️ 뽑기권 ' + t + '장';
      } else if (bar) bar.remove();
    } catch (e) {}
  }
  setInterval(refreshUI, 600);

  // ── 지급 시점 감시 ──
  function hookCheck(name) {
    (function t() {
      if (typeof window[name] !== 'function') { setTimeout(t, 100); return; }
      if (window[name].__tk) return;
      var o = window[name];
      var w = function (c) { var r = o.apply(this, arguments); grant(c); return r; };
      w.__tk = true; window[name] = w;
    })();
  }
  hookCheck('checkQuestProgress'); hookCheck('checkStoryCondition');
  (function hookAttend() {
    if (typeof window.closeAttend !== 'function') { setTimeout(hookAttend, 100); return; }
    var o = window.closeAttend;
    window.closeAttend = function () { var d = window._attendDay; var r = o.apply(this, arguments); if (d === 3) grant('attend_3'); if (d === 7) grant('attend_7'); return r; };
  })();

  // ── 처음 접속 지급 (starter-boost 가 새 계정 표시를 해 둔 뒤) ──
  (function initStart() {
    if (localStorage.getItem('ph_starter_v1') === null) { setTimeout(initStart, 200); return; }
    grant('start');
  })();
  hookDraw();
  window.__ticketTest = { tickets: tickets, setTickets: setTickets, grant: grant, GRANTS: GRANTS };
})();

// ════════════════════════════════════════════════════════════
// 🔄 앱 복귀 시 자동 새로고침 (app-resume.js)
// 설치형 앱(PWA)은 껐다 켜도 예전 화면이 메모리에 그대로 남아 있어서, 새로고침해야 고쳐지는 문제가 생김.
// → 앱을 5분 넘게 떠나 있다가 돌아오면 자동으로 새로고침해서 "새로 켠 것"과 똑같게 만든다.
//   (떠나는 순간 saveAll() 로 저장해 두므로 진행 상황은 안 날아감)
// ✏️ 고치는 법: AWAY_MIN 숫자만 바꾸면 됨 (분 단위)
// ════════════════════════════════════════════════════════════
(function () {
  'use strict';
  var AWAY_MIN = 5;
  var hiddenAt = 0;
  function save() { try { if (typeof saveAll === 'function') saveAll(); } catch (e) {} }
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') { hiddenAt = Date.now(); save(); return; }
    if (hiddenAt && Date.now() - hiddenAt > AWAY_MIN * 60000) { hiddenAt = 0; location.reload(); }
  });
  window.addEventListener('pageshow', function (e) { if (e.persisted) location.reload(); });
})();

