  var RC_DIV = 1;            // 재조합 코인 비용을 이 숫자로 나눔 (5 = 1/5로 감소, 1 = 안 줄임)
  var RC_COIN = {            // 재조합 코인 기준 비용 (나누기 전 값). 적지 않은 단계는 원래 값 유지
