    });
    if (JSON.stringify(out) !== JSON.stringify(raw)) saveEq(out);
  }

  // 프리미엄 카드가 지금 어느 (갖고 있는) 히든카드에 끼워져 있는지
  function whereIs(pid, eq) {
    var hit = null;
    Object.keys(eq).forEach(function (h) {
