// 🎤 첫 공연 튜토리얼 연결 (concert-tutorial.js)
// 플레이어 레벨 5 이상 + 첫 데뷔를 하고 나면 "선배의 무대" 초대 팝업이 뜨고, 홈에 [첫 공연] 버튼이 생긴다.
// 공연을 끝까지 하면 체험용 히든카드(7일)가 지급된다 (concert-farm.js + trial-card.js).
// 체험 카드를 이미 받은 계정은 아무것도 안 뜬다.
// ✏️ 고치는 법: NEED_LEVEL(몇 레벨에 열리나), COOLDOWN_H(팝업이 다시 뜨는 간격, 시간)
// ════════════════════════════════════════════════════════════
(function () {
  'use strict';
  var NEED_LEVEL = 5, COOLDOWN_H = 6, FREE_DRINKS = 5;
  var SHOWN = 'ph_concert_tut_shown';          // 팝업을 마지막으로 보여준 시각
  var FONT = "font-family:'Noto Sans KR',sans-serif;";

  function plv() { try { return Number(playerLevel) || 1; } catch (e) { return 1; } }
  function hasTrial() { try { return !!localStorage.getItem('ph_trialCard'); } catch (e) { return false; } }
  // 첫 데뷔(기획사)를 한 번이라도 시킨 뒤에만 열린다
  function debuted() { try { var d = (JSON.parse(localStorage.getItem('ph_agency') || '{}') || {}).done || {}; return Object.keys(d).some(function (k) { return d[k]; }); } catch (e) { return false; } }
  function eligible() { return plv() >= NEED_LEVEL && debuted() && !hasTrial() && typeof window.startConcertFarm === 'function'; }
  function homeActive() { var h = document.getElementById('screen-home'); return !!(h && h.classList.contains('active')); }
  function busy() { return !!(document.getElementById('concert-overlay') || document.getElementById('concert-tut-pop') || document.querySelector('[id$="-overlay"][style*="position:fixed"]:not(#place-overlay)')); }

  function go() {
    var p = document.getElementById('concert-tut-pop'); if (p) p.remove();
    try { window.startConcertFarm({ grantCard: true, freeDrinks: FREE_DRINKS }); } catch (e) { console.error('[concert-tut]', e); }
  }
  // 퀘스트 목록의 [가기]로도 들어오므로, 조건(레벨·첫 데뷔)을 여기서도 확인한다
  window.startConcertTutorial = function () {
    if (plv() < NEED_LEVEL) { try { showBagToast('🔒 첫 공연은 플레이어 Lv.' + NEED_LEVEL + '부터 열려요'); } catch (e) {} return; }
    if (!debuted()) { try { showBagToast('🔒 첫 공연은 첫 데뷔를 시키고 나면 열려요!'); } catch (e) {} return; }
    go();
  };

  function popup() {
    if (document.getElementById('concert-tut-pop')) return;
    try { localStorage.setItem(SHOWN, String(Date.now())); } catch (e) {}
    var ov = document.createElement('div');
    ov.id = 'concert-tut-pop';
    ov.style.cssText = 'position:fixed;inset:0;z-index:960;background:rgba(0,0,0,.78);display:flex;align-items:center;justify-content:center;padding:20px;' + FONT;
    ov.innerHTML = '<div style="background:linear-gradient(135deg,#1a1a2e,#4a1b6e);border:2px solid #f59e0b;border-radius:22px;padding:26px 22px;text-align:center;width:88%;max-width:310px;">' +
      '<div style="font-size:44px;margin-bottom:6px;">🎤</div>' +
      '<div style="font-size:19px;font-weight:900;color:#fff;margin-bottom:8px;">선배가 무대에 초대했어요!</div>' +
      '<div style="font-size:13px;color:#e9d5ff;line-height:1.7;margin-bottom:6px;">탑스타 <b style="color:#FFD700;">세연</b> 선배의 공연장!<br>팬들의 하트를 가득 채우면<br>🎁 <b style="color:#FFD700;">7일 체험 히든카드</b>를 선물로 줘요.</div>' +
      '<div style="font-size:12px;color:#fde7b0;line-height:1.7;margin:8px 0;background:rgba(245,158,11,.12);border-radius:10px;padding:8px 10px;"><span style="color:#fff;">히든카드 = 갖고만 있어도 <b>효과가 켜지는 카드</b><br>(스태미나 절약, 알바 코인↑ 등)</span><br>“써 보고 마음에 들면<br>7일 안에 <b>소원의 조각 50개</b>로<br>진짜 내 카드로 바꿔 둬!”</div>' +
      '<div style="font-size:11px;color:#c4b5fd;margin-bottom:16px;">(피로회복 드링크 ' + FREE_DRINKS + '개도 챙겨 가요)</div>' +
      '<button id="ct-go" style="width:100%;padding:14px;background:linear-gradient(135deg,#f59e0b,#ec4899);border:none;border-radius:12px;color:#fff;font-size:15px;font-weight:900;cursor:pointer;' + FONT + '">✨ 무대 올라가기</button>' +
      '<button id="ct-later" style="width:100%;margin-top:8px;padding:11px;background:rgba(255,255,255,.1);border:none;border-radius:12px;color:#ddd;font-size:13px;cursor:pointer;' + FONT + '">나중에 할래요</button></div>';
    document.body.appendChild(ov);
    document.getElementById('ct-go').onclick = go;
    document.getElementById('ct-later').onclick = function () { ov.remove(); };
  }

  function homeButton() {
    var b = document.getElementById('concert-tut-btn');
    if (!eligible()) { if (b) b.remove(); return; }
    var box = document.querySelector('#screen-home .home-actions');
    if (!box) return;
    if (!b) {
      b = document.createElement('button'); b.id = 'concert-tut-btn';
      b.textContent = '🎤 첫 공연 · 선배의 무대 (체험 카드 증정!)';
      b.style.cssText = 'width:100%;padding:14px;background:linear-gradient(135deg,#f59e0b,#ec4899);border:none;border-radius:14px;color:#fff;font-size:14px;font-weight:900;cursor:pointer;box-shadow:0 4px 16px rgba(245,158,11,.4);' + FONT;
      b.onclick = go;
      box.insertBefore(b, box.firstChild);
    }
  }

  setInterval(function () {
    try {
      homeButton();
      if (!eligible() || !homeActive() || busy()) return;
      var last = parseInt(localStorage.getItem(SHOWN) || '0') || 0;
      if (Date.now() - last > COOLDOWN_H * 3600000) popup();
    } catch (e) {}
  }, 1500);

  window.__concertTutTest = { eligible: eligible, popup: popup, go: go, NEED_LEVEL: NEED_LEVEL };
})();

// ════════════════════════════════
// 🎹 작곡 스튜디오 탐험 (studio-explore.js)
// 새 탐험 맵. 처음부터 바로 들어갈 수 있고, 포카마을 지도에 "🎹 작곡 스튜디오" 버튼이 생긴다.
// game.js / index.html 은 건드리지 않고 이 파일이 장소 목록·버튼을 스스로 등록한다.
//
// 흐름: 스태미나 15 소모 → 20초 동안 스튜디오 곳곳(건반·기타·모니터·녹음 부스·소파…)에서 빛나는 구슬이 켜졌다 꺼진다.
//       구슬은 1.8초 안에 눌러야 줍는다. 구슬 안 그림을 보면 뭐가 나올지 알 수 있다.
//   🎵 음표조각 / 🎼 악보용지 / 📝 가사조각 / 💡 영감의불꽃(희귀, 행운 스탯이 높을수록 잘 나옴)
// 재료는 💿 앨범 제작(album-studio.js)에서 쓴다. 재조합석 18% 판정은 기존 탐험과 동일.
// 값을 바꾸고 싶으면 아래 설정만 고치면 됨.
// ════════════════════════════════
(function () {
  'use strict';

  // ── 설정 ──
  var PLACE_ID = 'studio';
  var STAMINA_COST = 15;       // 신비의 섬과 동일
  var SESSION_SEC = 20;        // 탐험 시간
  var SPAWN_GAP = 1.5;         // 새 구슬이 켜지는 간격(초)
  var ORB_LIFE = 1.8;          // 구슬이 켜져 있는 시간(초)
  var ORB_MAX = 3;             // 동시에 켜져 있는 최대 수
  var STONE_DROP = 0.25;       // 끝났을 때 재조합석 확률 (기존 탐험과 동일)
  var BG_FILE = 'map-studio.png';
  var IMG_W = 1536, IMG_H = 1024;

  // 재료 20종 (이름은 album-studio.js 와 같아야 함). weight = 구슬로 나올 비중, cat = 분류
  var KINDS = [
    { id: 'n1',  cat: 'note',  emoji: '⚪', name: '온음표',   weight: 5 },
    { id: 'n2',  cat: 'note',  emoji: '♩',  name: '2분음표',  weight: 7 },
    { id: 'n4',  cat: 'note',  emoji: '♪',  name: '4분음표',  weight: 9 },
    { id: 'n8',  cat: 'note',  emoji: '♫',  name: '8분음표',  weight: 8 },
    { id: 'n16', cat: 'note',  emoji: '♬',  name: '16분음표', weight: 6 },
    { id: 'gtr', cat: 'inst',  emoji: '🎸', name: '기타',     weight: 7 },
    { id: 'bas', cat: 'inst',  emoji: '🪕', name: '베이스',   weight: 6 },
    { id: 'drm', cat: 'inst',  emoji: '🥁', name: '드럼',     weight: 7 },
    { id: 'pno', cat: 'inst',  emoji: '🎹', name: '피아노',   weight: 7 },
    { id: 'syn', cat: 'inst',  emoji: '🎛️', name: '신스',     weight: 5 },
    { id: 'str', cat: 'inst',  emoji: '🎻', name: '스트링',   weight: 5 },
    { id: 'scr', cat: 'score', emoji: '🎼', name: '악보용지', weight: 14 },
    { id: 'lyr', cat: 'lyric', emoji: '📝', name: '가사조각', weight: 10 },
    { id: 'spk', cat: 'spark', emoji: '💡', name: '영감의불꽃', weight: 4, rare: true },
    // ── 새 재료 6종 (새 장르 R&B·스윙·시티팝·펑크·트로트 전용. 처음엔 잘 안 나와서 모으는 맛이 있음)
    { id: 'mic', cat: 'inst',  emoji: '🎤', name: '마이크',     weight: 4 },
    { id: 'sax', cat: 'inst',  emoji: '🎷', name: '색소폰',     weight: 4 },
    { id: 'tpt', cat: 'inst',  emoji: '🎺', name: '트럼펫',     weight: 4 },
    { id: 'trp', cat: 'note',  emoji: '🎶', name: '셋잇단음표', weight: 5 },
    { id: 'cho', cat: 'lyric', emoji: '🗣️', name: '코러스',     weight: 4 },
    { id: 'mix', cat: 'gear',  emoji: '🎚️', name: '믹싱콘솔',   weight: 3 }
  ];
  var MATS = {};
  KINDS.forEach(function (k) { k.desc = '앨범 제작 재료 · 🎼 작곡 테이블에서 곡을 만들어요'; MATS[k.id] = k; });
  window.STUDIO_KINDS = KINDS;

  // 구슬이 켜지는 자리 (이미지 비율 0~1)
  var SPOTS = [
    { x: 0.27, y: 0.40 },   // 왼쪽 신시사이저
    { x: 0.45, y: 0.36 },   // 메인 키보드
    { x: 0.52, y: 0.27 },   // 모니터
    { x: 0.80, y: 0.33 },   // 녹음 부스 마이크
    { x: 0.69, y: 0.46 },   // 어쿠스틱 기타
    { x: 0.92, y: 0.60 },   // 오른쪽 피아노·악보
    { x: 0.13, y: 0.64 },   // 소파
    { x: 0.37, y: 0.68 },   // 테이블 위 노트
    { x: 0.08, y: 0.24 }    // 창가 야경
  ];

  // ════════ 순수 로직 (화면 없이도 테스트 가능) ════════
  function rollMaterial(luck, rng) {
    rng = rng || Math.random;
    var total = 0, w = KINDS.map(function (k) { var x = k.weight * (k.rare ? 1 + (luck || 0) / 100 : 1); total += x; return x; });
    var r = rng() * total;
    for (var i = 0; i < KINDS.length; i++) { if (r < w[i]) return KINDS[i].id; r -= w[i]; }
    return 'n4';
  }
  // 아직 안 쓰인 자리 중에서 하나 고르기
  function pickSpot(orbs, rng) {
    rng = rng || Math.random;
    var free = [];
    // 이미 켜진 구슬과 너무 가까운 자리(구슬끼리 겹침)는 피한다
    SPOTS.forEach(function (s, i) {
      if (orbs.some(function (o) { return o.spot === i || Math.hypot((SPOTS[o.spot].x - s.x) * 1.5, SPOTS[o.spot].y - s.y) < 0.2; })) return;
      free.push(i);
    });
    return free.length ? free[Math.floor(rng() * free.length)] : -1;
  }

  var S = null;

  function sfx(n) { try { if (window.pocaSfx) window.pocaSfx.play(n); } catch (e) {} }
  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
  function rnd(a, b) { return a + Math.random() * (b - a); }

  // ════════ 화면 ════════
  function startStudio() {
    if (document.getElementById('studio-overlay') || document.getElementById('explore-overlay')) return;
    if (typeof stamina !== 'undefined' && stamina < STAMINA_COST) { showBagToast('스태미나가 부족해요! ⚡ 음료를 마셔봐요 (작곡 스튜디오 ' + STAMINA_COST + ')'); return; }
    stamina -= STAMINA_COST;
    saveStamina();
    try { localStorage.setItem('ph_studio_visited', '1'); } catch (e) {}   // 길잡이 퀘스트 완료 표시용
    exploreCollected = [];

    var overlay = document.createElement('div');
    overlay.id = 'studio-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:700;background:#140c08;touch-action:none;user-select:none;-webkit-user-select:none;';
    var canvas = document.createElement('canvas');
    canvas.style.cssText = 'width:100%;height:100%;display:block;touch-action:none;';
    overlay.appendChild(canvas);
    document.body.appendChild(overlay);

    var bg = new Image(); bg.src = (typeof B !== 'undefined' ? B : '') + BG_FILE;
    S = {
      overlay: overlay, canvas: canvas, ctx: canvas.getContext('2d'), bg: bg, bgOk: false,
      W: 0, H: 0, dpr: 1, orbs: [], bursts: [], fly: [], misses: [], collected: [], t: 0, left: SESSION_SEC, spawnT: 0.4,
      bump: 0, combo: 0, last: performance.now(), raf: 0, ended: false
    };
    bg.onload = function () { if (S) S.bgOk = true; };
    resize();
    window.addEventListener('resize', resize);
    canvas.addEventListener('pointerdown', onDown);
    S.raf = requestAnimationFrame(loop);
  }
  function resize() {
    if (!S) return;
    S.dpr = Math.min(window.devicePixelRatio || 1, 2);
    S.W = window.innerWidth; S.H = window.innerHeight;
    S.canvas.width = Math.round(S.W * S.dpr); S.canvas.height = Math.round(S.H * S.dpr);
  }
  // 스튜디오 전체가 한눈에 보이게 화면 너비에 맞춰(contain) 가운데에 그린다. 위아래 남는 곳은 어둡게 확대한 배경으로 채움
  function view() {
    var sc = Math.min(S.W / IMG_W, S.H / IMG_H), w = IMG_W * sc, h = IMG_H * sc;
    return { sc: sc, x: (S.W - w) / 2, y: (S.H - h) / 2, w: w, h: h };
  }
  function orbR() { return clamp(view().w * 0.075, 24, 42); }
  function spotPos(i) { var v = view(); return [v.x + SPOTS[i].x * v.w, v.y + SPOTS[i].y * v.h]; }

  function onDown(e) {
    if (!S || S.ended) return;
    e.preventDefault();
    var r = S.canvas.getBoundingClientRect(), px = e.clientX - r.left, py = e.clientY - r.top, hit = null, best = 1e9;
    S.orbs.forEach(function (o) {
      var p = spotPos(o.spot), d = Math.hypot(px - p[0], py - p[1]);
      if (d < orbR() + 16 && d < best) { best = d; hit = o; }
    });
    if (hit) catchOrb(hit);
    else { S.combo = 0; S.bursts.push({ x: px, y: py, t: 0, dur: 0.35, rgb: '255,255,255', ring: true }); }
  }

  function catchOrb(o) {
    S.orbs.splice(S.orbs.indexOf(o), 1);
    var m = MATS[o.kind], p = spotPos(o.spot);
    var ok = true;
    if (typeof addToBag === 'function') ok = addToBag(m.emoji, m.name, 'material', 1, m.desc);
    if (!ok) { S.misses.push({ x: p[0], y: p[1], t: 0, text: '가방이 가득!' }); return; }
    exploreCollected.push(m.emoji + ' ' + m.name);
