  var IMG_BASE = 'https://raw.githubusercontent.com/chaei7775/Poca-house/main/';
  var BUST = '?v=' + Date.now();
  var PRICE = { stage: 30000, luxury: 80000, vintage: 150000 };   // 코인
  var NEW_THEMES = {
    stage:   { name: '💜 마이스테이지룸',  img: IMG_BASE + 'room_stage.png',   emoji: '💜' },
    luxury:  { name: '👑 럭셔리 스위트',   img: IMG_BASE + 'room_luxury.png',  emoji: '👑' },
    vintage: { name: '📻 빈티지 덕질방',   img: IMG_BASE + 'room_vintage.png', emoji: '📻' }
  };
  var NEW_IDS = ['stage', 'luxury', 'vintage'];
  var OLD_IDS = ['pink', 'plant', 'doll'];

  // 방 목록은 원본(2~3MB)이 아니라 작은 미리보기(roomthumb/)를 쓴다 (아이폰 메모리·로딩 부담)
  function roomThumb(img) {
    var m = /^(.*\/)(room_[a-z]+)\.png/.exec(String(img || ''));
    return m ? m[1] + 'roomthumb/' + m[2] + '.jpg' : img;
  }

  function install() {
    if (typeof ROOM_THEMES === 'undefined' || typeof window.renderRoomShop !== 'function') { setTimeout(install, 80); return; }
    if (window.__roomThemesInstalled) return;
    window.__roomThemesInstalled = true;

    NEW_IDS.forEach(function (id) {
      ROOM_THEMES[id] = { name: NEW_THEMES[id].name, price: PRICE[id], img: NEW_THEMES[id].img + BUST };
    });

    window.renderRoomShop = function () {
      var sec = document.getElementById('section-room');
      if (!sec) return;
      var owned = (typeof ownedRooms !== 'undefined' && Array.isArray(ownedRooms)) ? ownedRooms : [];
      var oldOwned = OLD_IDS.filter(function (id) { return owned.indexOf(id) !== -1 && ROOM_THEMES[id]; });
      var ids = NEW_IDS.concat(oldOwned);
      var html = '<div style="font-size:11px;color:#888;margin-bottom:12px;">방 테마를 구매하고 내 방을 꾸며봐!</div>';
      ids.forEach(function (id) {
        var t = ROOM_THEMES[id];
        var fallback = (NEW_THEMES[id] && NEW_THEMES[id].emoji) || '🏠';
        var isOld = OLD_IDS.indexOf(id) !== -1;
        var isOwned = owned.indexOf(id) !== -1;
        var isCurrent = (typeof currentRoom !== 'undefined') && currentRoom === id;
        var badge = isCurrent ? '<div class="room-current-badge">현재 적용 중</div>' : '';
        var price = isCurrent ? '' : (isOwned ? (isOld ? '보유 중 (이전 테마)' : '보유 중') : '🍔 ' + t.price.toLocaleString() + '코인');
        var btns = isCurrent ? '<span style="font-size:12px;color:#4ade80;font-weight:700;">✓ 적용됨</span>'
          : isOwned ? '<button class="shop-btn shop-btn-apply" onclick="applyRoom(\'' + id + '\')">적용</button>'
          : '<button class="shop-btn shop-btn-buy" onclick="buyRoom(\'' + id + '\')">구매</button>';
        html += '<div class="room-card' + (isCurrent ? ' current' : '') + '" id="roomcard-' + id + '">' +
          '<div class="room-card-img"><img loading="lazy" decoding="async" src="' + roomThumb(t.img) + '" onerror="if(!this.dataset.f){this.dataset.f=1;this.src=\'' + t.img + '\';}else{this.parentElement.innerHTML=\'' + fallback + '\'}"></div>' +
          '<div id="badge-' + id + '">' + badge + '</div>' +
          '<div class="room-card-body"><div><div class="room-card-name">' + t.name + '</div><div class="room-card-price" id="price-' + id + '">' + price + '</div></div>' +
          '<div id="btns-' + id + '">' + btns + '</div></div></div>';
      });
      sec.innerHTML = html;
    };
    window.renderRoomShop();
  }

  // 🛋️ 내 집의 '방 꾸미기' 버튼: 포카 레벨 3부터 열리고, 누르면 잡화점 '방' 탭(테마 판매)으로 간다.
  //    (가구샵 Lv10 잠금은 이 버튼 경로에서는 건너뜀 — 테마 사기만 Lv3부터 가능)
  function openThemeShop() {
    if (typeof closePlace === 'function') closePlace();
    var ov = document.getElementById('shop-overlay');
    if (ov) ov.classList.add('show');
    if (typeof switchShopTab === 'function') switchShopTab('room');
    var cd = document.getElementById('shop-coin-display');
    if (cd && typeof coins !== 'undefined') cd.textContent = coins;
    window.renderRoomShop();
  }
  function patchDecoButton() {
    var btn = document.getElementById('btn-room-deco');
    if (!btn || !btn.dataset.pocaPatched || btn.dataset.rtPatched) return;
    btn.dataset.rtPatched = '1';
    btn.onclick = function () {
      try {
        if (typeof isPocaHouseFeatureUnlocked === 'function' && !isPocaHouseFeatureUnlocked('roomDeco')) {
          if (typeof showPocaHouseLockedPopup === 'function') showPocaHouseLockedPopup(POCAHOUSE_UNLOCK.roomDeco, '방꾸미기');
          return;
        }
      } catch (e) {}
      openThemeShop();
    };
  }
  setInterval(patchDecoButton, 500);
  install();
})();

// ════════════════════════════════
// ✨ 신비의 섬 해금 낮추기 (mystery-unlock.js)
// 아무 포카나 호감도 경험치 UNLOCK_EXP 이상이면 신비의 섬이 열린다.
//  - 기존: 친절 Lv.3 (경험치 20)  →  지금: 친절 Lv.2 (경험치 10)
//  - game.js 의 해금 판정만 덮어쓰고, 화면/퀘스트에 적힌 '친절 Lv.3' 문구는 '친절 Lv.2'로 바꿔 보여준다.
// 값을 바꾸고 싶으면 UNLOCK_EXP 만 고치면 된다. (친절 Lv.2 = 10, Lv.3 = 20, Lv.4 = 35)
// ════════════════════════════════
(function () {
  'use strict';
  var UNLOCK_EXP = 10;
  var OLD_TEXT = '친절 Lv.3', NEW_TEXT = '친절 Lv.2';

  function unlocked() {
    try {
      return Object.keys(CHARS).some(function (id) { return getAffectionTotalExp(id) >= UNLOCK_EXP; });
    } catch (e) { return false; }
  }

  function questPing() {
    try {
      if (typeof checkQuestProgress === 'function' && unlocked()) {
        checkQuestProgress('affection_level_2');   // (신비의 섬 퀘스트는 '열렸을 때'가 아니라 실제로 들어갔을 때 완료)
      }
    } catch (e) {}
  }

  // 화면 문구 보정
  function fixNode(n) {
    if (n.nodeType === 3) {
      if (n.nodeValue.indexOf(OLD_TEXT) !== -1) n.nodeValue = n.nodeValue.split(OLD_TEXT).join(NEW_TEXT);
    } else if (n.nodeType === 1) {
      var w = document.createTreeWalker(n, NodeFilter.SHOW_TEXT, null), t;
      while ((t = w.nextNode())) { if (t.nodeValue.indexOf(OLD_TEXT) !== -1) t.nodeValue = t.nodeValue.split(OLD_TEXT).join(NEW_TEXT); }
    }
  }

  function install() {
    if (typeof window.isMysteryIslandUnlocked !== 'function' || typeof window.checkAffectionLevelUp !== 'function' || typeof window.showBagToast !== 'function') {
      setTimeout(install, 80); return;
    }
    if (window.__mysteryUnlockApplied) return;
    window.__mysteryUnlockApplied = true;

    window.isMysteryIslandUnlocked = unlocked;

    var origLevelUp = window.checkAffectionLevelUp;
    window.checkAffectionLevelUp = function () {
      var r = origLevelUp.apply(this, arguments);
      questPing();
      return r;
    };

    var origToast = window.showBagToast;
    window.showBagToast = function (msg) {
      if (typeof msg === 'string') msg = msg.split(OLD_TEXT).join(NEW_TEXT);
      return origToast.call(this, msg);
    };

    try {
      new MutationObserver(function (list) {
        list.forEach(function (m) {
          if (m.type === 'characterData') fixNode(m.target);
          else m.addedNodes.forEach(fixNode);
        });
      }).observe(document.body, { childList: true, subtree: true, characterData: true });
    } catch (e) {}
    fixNode(document.body);
    questPing();
  }
  install();
})();

// ════════════════════════════════
// 📜 공연장·포토랩 퀘스트 (quest-concert.js) — game.js / quest-extra.js 는 건드리지 않음
// 퀘스트 탭에 공연장 → 앵콜 스테이지 → 시크릿 포토랩 흐름 퀘스트를 넣는다. 조건은 3초마다 자동 확인.
// 또 '내 방 꾸미기' 튜토리얼 설명을 지금 방식(내 집 → 방 꾸미기)으로 고친다.
// 등록: loader.js NEW_CONTENT_FILES 에서 'quest-extra.js' 보다 뒤에 'quest-concert.js' 한 줄 추가
// 보상 코인을 바꾸고 싶으면 아래 rewardCoins 숫자만 고치면 된다.
// ════════════════════════════════
(function () {
  'use strict';
  var FKEY = 'ph_quest3';
  function loadF() { try { return JSON.parse(localStorage.getItem(FKEY) || '{}') || {}; } catch (e) { return {}; } }
  var F = loadF();
  function flag(n) { if (!F[n]) { F[n] = 1; try { localStorage.setItem(FKEY, JSON.stringify(F)); } catch (e) {} } }
  function J(key, def) {
    try { var v = JSON.parse(localStorage.getItem(key) || 'null'); return (v === null || v === undefined) ? def : v; } catch (e) { return def; }
  }
  function keys(o) { try { return Object.keys(o || {}); } catch (e) { return []; } }
  var ENCORE_N = 20;

  // 진행 기록 남기기 (공연장은 나가면 진행 저장이 지워지므로 '달성 기록'을 따로 남김)
  function record() {
    var run = J('ph_concertRun', null);
    if (run && typeof run.done === 'number') {
      flag('concert');
      if (run.done >= ENCORE_N) flag('encore');
    }
    var eng = J('ph_engrave', {}) || {};
    keys(eng).forEach(function (id) {
      var c = eng[id];
      if (!c) return;
      if ((c.rolls || 0) >= 1) flag('develop');
      (c.slots || []).forEach(function (s) { if (s && s.grade === 'center') flag('center'); });
    });
  }

  var NEW = {
    main_concert: { title: '공연장 입장', desc: '🎤 맵 → 팬덤 원정 → 공연장. 등교시키기로 모은 🌟우등생별 1개로 들어갈 수 있어.',
      condition: 'q3_concert', rewardCoins: 10000, rewardExp: 300, type: 'main', detect: function () { return !!F.concert; } },
    main_encore: { title: '앵콜 스테이지', desc: '🎤 공연장에서 이벤트를 20번 채우면 앵콜 스테이지가 열려. 필름🎞️도 같이 모아봐.',
      condition: 'q3_encore', rewardCoins: 15000, rewardExp: 400, type: 'main', detect: function () { return !!F.encore; } },
    main_develop: { title: '첫 프리미엄 현상', desc: '📷 앵콜 스테이지 → 시크릿 포토랩에서 프리미엄 카드를 현상해봐. 필름1개+코인이 들어가.',
      condition: 'q3_develop', rewardCoins: 15000, rewardExp: 400, type: 'main', detect: function () { return !!F.develop; } },
    main_center: { title: '센터 효과 현상', desc: '👑 포토랩 현상에서 슬롯에 [센터] 등급 효과가 뜨게 해봐. 마음에 드는 칸은 🔒로 잠가두면 지켜져.',
      condition: 'q3_center', rewardCoins: 25000, rewardExp: 600, type: 'main', detect: function () { return !!F.center; } }
  };

  var DETECT = {};
  function register() {
    if (typeof QUESTS === 'undefined') return false;
    Object.keys(NEW).forEach(function (id) {
      var q = NEW[id];
      DETECT[id] = q.detect;
      if (!QUESTS[id]) QUESTS[id] = { title: q.title, desc: q.desc, condition: q.condition, rewardCoins: q.rewardCoins, rewardExp: q.rewardExp, type: q.type };
    });
    // 방 꾸미기 튜토리얼: 이제 내 집의 방 꾸미기 버튼으로 산다 (포카 레벨 3부터)
    if (QUESTS.tut_room) QUESTS.tut_room.desc = '🏠 내 집 → 🛋️ 방 꾸미기(포카 Lv.3부터) → 방 테마를 사서 적용! 방을 바꾸면 기분이 달라져.';
    return true;
  }

  function check() {
    try {
      if (typeof questProgress === 'undefined' || typeof checkQuestProgress !== 'function') return;
      var ids = Object.keys(DETECT);
      for (var i = 0; i < ids.length; i++) {
        var id = ids[i];
        if (questProgress[id] === 'done') continue;
        var ok = false;
        try { ok = !!DETECT[id](); } catch (e) {}
        if (ok) { checkQuestProgress(NEW[id].condition); return; }
      }
    } catch (e) {}
  }

  (function boot() {
    if (!register()) { setTimeout(boot, 200); return; }
    // quest-extra.js 와 완료 팝업이 겹치지 않게 주기를 살짝 다르게
    setInterval(function () { record(); check(); }, 3100);
    var tries = 0;
    (function hookList() {
      if (typeof window.renderQuestList !== 'function') { if (tries++ < 50) setTimeout(hookList, 100); return; }
      var cur = document.getElementById('screen-quest');
      if (cur && cur.classList.contains('active')) { try { window.renderQuestList(); } catch (e) {} }
    })();
  })();
})();

// ════════════════════════════════════════════════════════════
// 🎁 퀘스트 보상 인상 (quest-boost.js)
// 튜토리얼/메인 퀘스트(game.js·quest-extra.js)와 스토리 퀘스트(pocalevel.js)의 보상을 올린다.
//  · 코인 ×COIN_MULT, 경험치 ×EXP_MULT
//  · 공연장 퀘스트(q3_*)는 이미 크게 올려서 제외
//  · 길잡이(quest-guide.js) / 연대기(story-quest.js) 보상은 각자 파일 안에서 따로 올림
// ✏️ 고치는 법: 아래 두 숫자만 바꾸면 됨
// ════════════════════════════════════════════════════════════
(function () {
  'use strict';
  var COIN_MULT = 5, EXP_MULT = 2;
  var SKIP = /^q3_/;
  var KEEP_COIN = { poca_level_5: 1 };   // 첫 뽑기만 해도 바로 깨지는 퀘스트(포카 Lv5)는 코인을 안 올림 (초반에 코인이 폭발하면 알바할 이유가 사라짐)
  function boost(q) {
    if (!q || q.__boosted || SKIP.test(q.condition || '')) return;
    q.__boosted = true;
    if (typeof q.rewardCoins === 'number') q.rewardCoins = Math.round(q.rewardCoins * (KEEP_COIN[q.condition] || COIN_MULT));
    if (typeof q.rewardExp === 'number') q.rewardExp = Math.round(q.rewardExp * EXP_MULT);
  }
  function run() {
    try { if (typeof QUESTS !== 'undefined') Object.keys(QUESTS).forEach(function (k) { boost(QUESTS[k]); }); } catch (e) {}
    try { if (typeof STORY_QUESTS !== 'undefined') STORY_QUESTS.forEach(boost); } catch (e) {}
  }
  run();
  var n = 0, iv = setInterval(function () { run(); if (++n > 60) clearInterval(iv); }, 500);   // 다른 파일이 늦게 등록하는 퀘스트도 잡기 (30초)
  window.__questBoostTest = { run: run, COIN_MULT: COIN_MULT, EXP_MULT: EXP_MULT };
})();

