      el.style.cssText = 'position:absolute;left:' + (f.spot[0] / IMG_W * 100) + '%;top:' + (f.spot[1] / IMG_H * 100) + '%;width:' + (sz * 1.5 / IMG_W * 100) + '%;transform:translate(-50%,-92%);cursor:pointer;touch-action:none;';
      el.innerHTML = fanSvg(f);
      f.el = el;
      S.fansEl.appendChild(el);
    });
    applyPan();
  }

  function renderPanel() {
    var p = $('sq-panel');
    var hearts = '';
    for (var i = 0; i < TRIES; i++) hearts += (i < S.tries ? '❤️' : '🖤');
    p.innerHTML =
      '<div style="font-size:11px;color:#FFB3CC;font-weight:700;margin-bottom:4px;">📋 팬 찾기 의뢰</div>' +
      '<div style="font-size:14px;font-weight:700;line-height:1.55;margin-bottom:10px;">' + S.rd.clue + '</div>' +
      '<div style="display:flex;align-items:center;gap:8px;">' +
        '<div style="font-size:15px;letter-spacing:2px;">' + hearts + '</div>' +
        '<div style="flex:1;font-size:10px;color:#aaa;">그림을 밀어서 움직여요 · 팬을 탭!</div>' +
        '<button id="sq-hint" style="background:' + (S.hinted ? 'rgba(255,255,255,.08)' : 'rgba(255,215,0,.18)') + ';border:1.5px solid ' + (S.hinted ? 'rgba(255,255,255,.2)' : '#FFD700') + ';border-radius:12px;color:#fff;padding:8px 12px;font-size:12px;font-weight:900;cursor:pointer;font-family:inherit;">' + (S.hinted ? '힌트 사용함' : '💡 힌트 🍔' + HINT_COST) + '</button></div>';
    $('sq-hint').onclick = useHint;
  }

  function useHint() {
    if (!S || S.busy || S.hinted) return;
    if (typeof coins === 'undefined' || coins < HINT_COST) { toast('코인이 부족해요! 🍔 ' + HINT_COST + ' 필요'); return; }
    coins -= HINT_COST;
    if (typeof saveAll === 'function') saveAll();
    if (typeof updateCoinsDisplay === 'function') updateCoinsDisplay();
    S.hinted = true;
    var wrong = S.rd.fans.filter(function (f) { return !f.answer && !f.dim; });
    shuffle(wrong, Math.random).slice(0, HINT_REMOVE).forEach(function (f) { f.dim = true; f.el.style.opacity = '.28'; f.el.style.pointerEvents = 'none'; });
    renderPanel();
    toast('💡 틀린 팬 ' + HINT_REMOVE + '명이 흐려졌어요!');
  }

  function ring(el, color) {
    var r = document.createElement('div');
    r.style.cssText = 'position:absolute;left:50%;top:50%;width:140%;aspect-ratio:1;border-radius:50%;border:3px solid ' + color + ';transform:translate(-50%,-50%);box-shadow:0 0 14px ' + color + ';pointer-events:none;';
    el.appendChild(r);
  }
  function say(text, color) {
    var m = document.createElement('div');
    m.style.cssText = 'position:absolute;left:50%;top:38%;transform:translate(-50%,-50%);z-index:8;background:rgba(0,0,0,.75);border:2px solid ' + color + ';border-radius:16px;padding:12px 18px;font-size:16px;font-weight:900;text-align:center;pointer-events:none;';
    m.innerHTML = text;
    S.view.appendChild(m);
    setTimeout(function () { if (m.parentNode) m.parentNode.removeChild(m); }, 1500);
  }

  function onPick(i, el) {
    if (!S || S.busy || S.ended) return;
    var f = S.rd.fans[i];
    if (!f || f.dim) return;
    if (judge(f)) {
      S.busy = true;
      ring(el, '#4ade80');
      S.okCount++;
      var lines = giveFanReward(S.okCount === ROUNDS && S.round === ROUNDS && S.okCount === ROUNDS);
      say('🎉 찾았어요!<br><span style="font-size:12px;color:#FFD700;">' + lines.join(' · ') + '</span>', '#4ade80');
      setTimeout(advance, 1600);
    } else {
      S.tries--;
      ring(el, '#f87171');
      el.style.opacity = '.4'; el.style.pointerEvents = 'none';
      if (S.tries <= 0) {
        S.busy = true;
        var ans = S.rd.fans.filter(function (x) { return x.answer; })[0];
        if (ans) ring(ans.el, '#facc15');
        say('😢 이 팬이 아니었어요…<br><span style="font-size:12px;color:#ddd;">정답은 노란 원 안의 팬!</span>', '#f87171');
        setTimeout(advance, 1900);
      } else {
        say('앗, 다른 팬이에요! 기회 ' + S.tries + '번 남음', '#f87171');
        renderPanel();
      }
    }
  }

  function advance() {
    if (!S || S.ended) return;
    if (S.round >= ROUNDS) finish(false); else nextRound();
  }

  // 보상: 재료 3개 (기존 탐험 보상 로직 그대로). 3건 다 맞히면 마지막 보상에 희귀 재료 보너스
  function giveFanReward(allClear) {
    var lines = [];
    var drops = [];
    for (var i = 0; i < DROPS_PER_FAN; i++) drops.push(rollDrop(S.luck, false));
    if (allClear) drops.push(rollDrop(S.luck, true));
    drops.forEach(function (d) {
      var dummy = document.createElement('div');
      S.ov.appendChild(dummy);
      var before = exploreCollected.length;
      collectExploreItem(0, { name: d.name, isWish: d.isWish, isRare: d.isRare }, dummy);
      var label = d.isWish ? '🧩 소원의 조각' : (exploreCollected.length > before ? exploreCollected[exploreCollected.length - 1] : d.name);
      S.collected.push(label);
      lines.push(label);
    });
    if (allClear) lines.push('✨보너스');
    return lines;
  }

  // ── 종료 / 결과 ──
  function finish(early) {
    if (!S || S.ended) return;
    S.ended = true;
    window.removeEventListener('resize', onResize);
    var got = S.collected.slice(), ov = S.ov, ok = S.okCount;

    if (Math.random() < STONE_DROP && typeof addToBag === 'function') {
      if (addToBag('🔹', '재조합석', 'material', 1, '카드 재조합에 필요한 재료')) { got.push('🔹 재조합석'); exploreCollected.push('🔹 재조합석'); }
    }
    if (typeof saveAll === 'function') saveAll();
    var counts = {}, order = [];
    got.forEach(function (n) { if (!(n in counts)) { counts[n] = 0; order.push(n); } counts[n]++; });
    var list = order.length ? order.map(function (n) { return n + (counts[n] > 1 ? ' ×' + counts[n] : ''); }).join('<br>') : '아무것도 못 얻었어요 😢';
    var left = (typeof stamina !== 'undefined') ? stamina : '?';
    S = null;
    ov.innerHTML = '<div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.78);">' +
      '<div style="background:linear-gradient(135deg,#1a1a2e,#2d1b4e);border:2px solid #FF6B9D;border-radius:20px;padding:26px 22px;text-align:center;width:85%;max-width:300px;">' +
      '<div style="font-size:36px;margin-bottom:6px;">🔍</div>' +
      '<div style="font-size:18px;font-weight:900;color:#fff;margin-bottom:6px;">팬 찾기 끝!</div>' +
      '<div style="font-size:13px;color:#FFB3CC;margin-bottom:6px;">찾은 팬 ' + ok + '/' + ROUNDS + (ok === ROUNDS ? ' · 전부 성공! 🎉' : '') + '</div>' +
      '<div style="font-size:12px;color:#aaa;margin-bottom:8px;">스태미나 -' + STAMINA_COST + ' (잔여: ' + left + ')</div>' +
      '<div style="font-size:14px;color:#FFD700;line-height:1.7;margin-bottom:16px;">' + list + '</div>' +
      '<button id="sq-again" style="width:100%;padding:13px;margin-bottom:8px;background:linear-gradient(135deg,#FF6B9D,#C084FC);border:none;border-radius:12px;color:#fff;font-size:15px;font-weight:700;cursor:pointer;font-family:\'Noto Sans KR\',sans-serif;">한 번 더! (⚡' + STAMINA_COST + ')</button>' +
      '<button id="sq-close" style="width:100%;padding:12px;background:rgba(255,255,255,0.1);border:none;border-radius:12px;color:#ccc;font-size:14px;cursor:pointer;font-family:\'Noto Sans KR\',sans-serif;">확인</button>' +
      '</div></div>';
    $('sq-close').onclick = function () { ov.remove(); };
    $('sq-again').onclick = function () { ov.remove(); startSquare(); };
  }

  window.startSquare = startSquare;
  window.__squareTest = { makeRound: makeRound, judge: judge, rollDrop: rollDrop, SPOTS: SPOTS, get S() { return S; } };

  // ── 광장 "탐험" 버튼만 새 탐험으로 연결 (game.js는 건드리지 않음) ──
  (function hookStartExplore() {
    if (typeof window.startExplore !== 'function' || typeof window.collectExploreItem !== 'function') { setTimeout(hookStartExplore, 50); return; }
    if (window.__squareHooked) return;
    window.__squareHooked = true;
    var original = window.startExplore;
    window.startExplore = function (placeId) {
      if (placeId === 'square') { startSquare(); return; }
      return original.apply(this, arguments);
    };
  })();
})();

// ════════════════════════════════
// 📅 일일퀘스트 (daily-quest.js) — game.js / index.html 건드리지 않는 별도 모듈
// 매일 자정(기기 시간 기준)에 초기화. 경험치 크게 + 코인 약간.
// - 홈 화면: 길잡이 카드 아래에 한 줄 카드 (받을 보상이 있으면 [받기] 버튼)
// - 퀘스트 탭: 맨 위에 일일퀘스트 목록
// 등록: loader.js NEW_CONTENT_FILES 맨 끝에 'daily-quest.js' 한 줄 추가
// 저장: localStorage 'ph_daily'  (기기 저장 — cloud-extra.js 서버 저장 목록에 넣으려면 같은 키 추가)
// ════════════════════════════════
(function () {
  var KEY = 'ph_daily';

  // ───────── ⚙️ 보상 설정 (여기 숫자만 고치면 밸런스 조절) ─────────
  // exp: 하루 총 경험치 = 현재 레벨 필요경험치 × 배율 (최소 MIN_TOTAL_EXP)
  //   → 초반엔 하루에 여러 레벨, 레벨이 높아질수록 배율이 줄어듦
  var MIN_TOTAL_EXP = 30;      // 초반(Lv1~4)엔 하루에 많아야 한 레벨 정도만 오르게
  function expMultiplier(lv) { return lv <= 4 ? 0.25 : (lv <= 10 ? 1.0 : (lv <= 20 ? 0.8 : 0.4)); }

  // 퀘스트 목록: need=목표 횟수, w=경험치 비중(합 1.0), coins=코인(고정, 약간)
  var ALLQ = [
    { id: 'login',   icon: '👋', title: '오늘도 출석!',      desc: '접속하면 자동 완료',          need: 1, w: 0.10, coins: 1000 },
    { id: 'alba',    icon: '🍔', title: '알바 2판 하기',      desc: '🍔 알바하기에서 2번 완료',     need: 2, w: 0.15, coins: 1500 },
    { id: 'explore', icon: '🚐', title: '스케줄 2번 나가기',  desc: '🚐 스케줄 가기 / 낚시 2번',    need: 2, w: 0.15, coins: 1000 },
    { id: 'gift',    icon: '💝', title: '선물 1번 하기',      desc: '🛍️ 잡화점에서 사서 💞 인연에서 선물',  need: 1, w: 0.15, coins: 1000 },
    { id: 'school',  icon: '🏫', title: '학교 1번 가기',      desc: '맵 → 연성고등학교 미니게임',   need: 1, w: 0.15, coins: 1000 },
    { id: 'drama',   icon: '🎥', title: '드라마 촬영 1번',    desc: '맵 → 광장 → 🎥 드라마 촬영 (데뷔한 아이돌이 있어야 해요)', need: 1, w: 0.10, coins: 1500, needDebut: true },
  ];
  // 데뷔한 아이돌이 있을 때만 드라마 퀘스트가 목록에 나옴 (없으면 올클리어가 막히니까)
  function debutN() { try { var d = (JSON.parse(localStorage.getItem('ph_agency') || '{}') || {}).done || {}; return Object.keys(d).filter(function (k) { return d[k]; }).length; } catch (e) { return 0; } }
  var QUESTS = ALLQ.slice();
  function refreshQ() { var dn = debutN(); QUESTS = ALLQ.filter(function (q) { return !q.needDebut || dn >= 1 || (D && D.claimed && D.claimed[q.id]); }); }
  var BONUS = { id: 'bonus', icon: '🎁', title: '올클리어 보너스', desc: '위 퀘스트를 모두 받으면 추가 보상', w: 0.20, coins: 1500 };

  // ───────── 날짜 / 저장 ─────────
  function todayKey() {
    var d = new Date();
    return d.getFullYear() + '-' + ('0' + (d.getMonth() + 1)).slice(-2) + '-' + ('0' + d.getDate()).slice(-2);
  }
  function load() { try { return JSON.parse(localStorage.getItem(KEY) || '{}') || {}; } catch (e) { return {}; } }
  function save() { try { localStorage.setItem(KEY, JSON.stringify(D)); } catch (e) {} }

  function sumCardCounts() {
    try { var n = 0; Object.keys(cardCounts).forEach(function (k) { n += cardCounts[k] || 0; }); return n; } catch (e) { return 0; }
  }
  function getAlba() { try { return typeof albaDone !== 'undefined' ? albaDone : 0; } catch (e) { return 0; } }
  function plv() { try { return typeof playerLevel !== 'undefined' ? playerLevel : 1; } catch (e) { return 1; } }
  function reqExp(lv) { try { return typeof getExpRequired === 'function' ? getExpRequired(lv) : 20 * lv * lv; } catch (e) { return 20 * lv * lv; } }

  var D = load();
  function freshDay() {
    D = { date: todayKey(), albaBase: getAlba(), prog: { login: 1 }, claimed: {} };
    save();
  }
  function ensureDay() {
    refreshQ();
    if (!D || D.date !== todayKey()) { freshDay(); return true; }
    D.prog = D.prog || {}; D.claimed = D.claimed || {};
    if (typeof D.albaBase !== 'number') D.albaBase = getAlba();
    if (!D.prog.login) D.prog.login = 1;
    return false;
  }

  // ───────── 진행도 ─────────
  function progOf(q) {
    if (q.id === 'alba') return Math.max(0, getAlba() - D.albaBase);
    return D.prog[q.id] || 0;
  }
  function isDone(q) { return progOf(q) >= q.need; }
  function allClaimed() { return QUESTS.every(function (q) { return !!D.claimed[q.id]; }); }
  function bonusReady() { return allClaimed() && !D.claimed.bonus; }

  function totalExp() {
    return Math.max(MIN_TOTAL_EXP, Math.round(reqExp(plv()) * expMultiplier(plv()) / 10) * 10);
  }
  function expOf(q) { return Math.round(totalExp() * q.w); }

  // ───────── 보상 지급 ─────────
  function toast(msg) {
    try { if (typeof showBagToast === 'function') showBagToast(msg); } catch (e) {}
  }
  function giveReward(def) {
    var exp = expOf(def);
    try {
      coins += def.coins;
      if (typeof saveAll === 'function') saveAll();
      if (typeof updateCoinsDisplay === 'function') updateCoinsDisplay();
    } catch (e) {}
    try { if (typeof addPlayerExp === 'function') addPlayerExp(exp); } catch (e) {}
    return exp;
  }
  function claim(id) {
    ensureDay();
    if (D.claimed[id]) return false;
    var def = null, i;
    if (id === 'bonus') { if (!bonusReady()) return false; def = BONUS; }
    else { for (i = 0; i < QUESTS.length; i++) if (QUESTS[i].id === id) def = QUESTS[i]; if (!def || !isDone(def)) return false; }
    D.claimed[id] = 1; save();            // 먼저 기록 → 중복 수령 방지
    var exp = giveReward(def);
    toast('📅 ' + def.title + ' 완료! 🍔+' + def.coins + ' ⭐+' + exp);
    render();
    return true;
  }
  function claimAll() {
    ensureDay();
    var got = 0, coinSum = 0, expSum = 0;
    QUESTS.forEach(function (q) {
      if (!D.claimed[q.id] && isDone(q)) {
        D.claimed[q.id] = 1; save();
        coinSum += q.coins; expSum += giveReward(q); got++;
      }
    });
    if (bonusReady()) { D.claimed.bonus = 1; save(); coinSum += BONUS.coins; expSum += giveReward(BONUS); got++; }
    if (got) toast('📅 일일퀘스트 ' + got + '개 완료! 🍔+' + coinSum + ' ⭐+' + expSum);
    render();
  }
  function claimableCount() {
    var n = QUESTS.filter(function (q) { return !D.claimed[q.id] && isDone(q); }).length;
    if (bonusReady()) n++;
    return n;
  }

  // ───────── 첫 사용 감지 후킹 (원래 함수는 그대로 실행) ─────────
  function hookLater(name, factory) {
    (function tryHook() {
      if (typeof window[name] !== 'function') { setTimeout(tryHook, 100); return; }
      var orig = window[name];
      if (orig.__dqHooked) return;
      var wrapped = factory(orig);
      wrapped.__dqHooked = true;
      window[name] = wrapped;
    })();
  }
  // 후킹(hook)과 상태 감시(watch) 두 방식으로 세는데, 같은 행동이 두 번 세지지 않게 4초 안엔 한 번만 인정
  var lastBump = {};
  function bump(id, n, src) {
    var now = Date.now();
    if (src === 'watch' && lastBump[id] && now - lastBump[id] < 4000) return;
    lastBump[id] = now;
    ensureDay();
    D.prog[id] = (D.prog[id] || 0) + (n || 1);
    save();
  }
  function giftQty() {
    var n = 0;
    try { bagItems.forEach(function (i) { n += i.qty || 0; }); } catch (e) {}
    try { Object.keys(inventory).forEach(function (k) { n += inventory[k] || 0; }); } catch (e) {}
    return n;
  }
  function staminaNow() { try { return typeof stamina !== 'undefined' ? stamina : 0; } catch (e) { return 0; } }

  // 탐험: 스태미나가 줄었거나 탐험 화면이 떴을 때만 1회로 인정 (스태미나 부족으로 막힌 경우 제외)
  hookLater('startExplore', function (orig) {
    return function () {
      var before = staminaNow();
      var r = orig.apply(this, arguments);
      try { if (staminaNow() < before || document.getElementById('explore-overlay')) bump('explore'); } catch (e) {}
      return r;
    };
  });
  hookLater('startFishing', function (orig) {
    return function () {
      var r = orig.apply(this, arguments);
      try { bump('explore'); } catch (e) {}
      return r;
    };
  });
  hookLater('startSpecialExplore', function (orig) {
    return function () {
      var before = staminaNow();
      var r = orig.apply(this, arguments);
      try { if (staminaNow() < before) bump('explore'); } catch (e) {}
      return r;
    };
  });
  // 선물: 가방/인벤토리 개수가 실제로 줄었을 때만 인정
  hookLater('giveGift', function (orig) {
    return function () {
      var before = giftQty();
      var r = orig.apply(this, arguments);
      try { if (giftQty() < before) bump('gift'); } catch (e) {}
      return r;
    };
  });
  // 드라마 촬영: 촬영이 끝나 결과가 나올 때 drama.js 가 보내는 신호
  try { window.addEventListener('ph-drama-shot', function () { bump('drama'); }); } catch (e) {}
  // 학교: 미니게임 결과 화면이 뜰 때 1회
  hookLater('showSchoolResult', function (orig) {
    return function () {
      var r = orig.apply(this, arguments);
      try { bump('school'); } catch (e) {}
      return r;
    };
  });

  // ───────── 상태 감시 (함수 이름이 바뀌거나 후킹이 덮어씌워져도 세어지게 하는 보조 장치) ─────────
  // 스태미나가 줄면 = 스케줄(탐험/낚시/팬덤 원정) 1번, 선물 개수가 줄면 = 선물 1번, 학교 재화/기록이 바뀌면 = 학교 1번
  function giftOnlyQty() {
    var n = 0;
    try { bagItems.forEach(function (i) { if (i.type === 'gift') n += i.qty || 0; }); } catch (e) {}
    try { Object.keys(inventory).forEach(function (k) { n += inventory[k] || 0; }); } catch (e) {}
    return n;
  }
  function schoolSig() {
    var s = '';
    try { s += String(honorFragments) + '|' + String(honorStars) + '|'; } catch (e) {}
    try { s += localStorage.getItem('ph_schoolDaily') || ''; } catch (e) {}
    return s;
  }
  var W = null;
  function watchTick() {
    var cur = { st: staminaNow(), gf: giftOnlyQty(), sc: schoolSig() };
    if (W) {
      if (cur.st < W.st) bump('explore', 1, 'watch');
      if (cur.gf < W.gf) bump('gift', 1, 'watch');
      if (cur.sc !== W.sc) bump('school', 1, 'watch');
    }
    W = cur;
  }
  setTimeout(function () { watchTick(); setInterval(watchTick, 1000); }, 3000);

