    try {
      FISH.forEach(function (f) {
        if (typeof MATERIAL_SELL_PRICES !== 'undefined') MATERIAL_SELL_PRICES[f.name] = f.price;
        if (typeof MATERIAL_EMOJI_MAP !== 'undefined') MATERIAL_EMOJI_MAP[f.name] = f.emoji;
