  }

  function addTrap(how) {                                          // how: 'craft' | 'buy'
    var s = load();
    if (s.traps.length >= MAX_TRAPS) { toast('통발은 최대 ' + MAX_TRAPS + '개까지 가질 수 있어요'); return false; }
    if (how === 'craft') {
      if (!craftReady()) { toast('재료나 코인이 부족해요!'); return false; }
