    if (newSlots > freeSlots()) { toast('가방이 꽉 찼어요! 🎒 슬롯을 확장하거나 재료를 팔아주세요'); return null; }

    registerItems();
    var got = {}, webs = 0;
    rolls.forEach(function (f) {
