    var orig = schoolSubjectCard;
    window.schoolSubjectCard = function (icon, title, desc, score, action) {
      normalizeSchoolDaily();
      var cd = getSchoolCardDaily();
      var html = orig(icon, title, desc, score, action);
      if (paid(cd)) {
        html = html.replace(' · 🎫1<', ' · 🎫0<');
