const POSE_OF={sob:'cry',tears:'cry',dead:'cry',smile:'smile',laugh:'smile',adlib:'smile',song:'smile',makeup:'smile',rage:'fist',chase:'fist',wire:'fist',act:'fist',stunt:'fist',one:'fist',close:'fist'};
