  const mastRows=Object.keys(G.mast).map(id=>{const m=G.mast[id],l=mastLv(id);return `<div><span>🎖️ ${SKILLS[id].n} 숙련</span><b>+${m.xp} ${m.up?`· Lv.${l} 달성!`:l>=MAST_MAX?'· MAX':`(Lv.${l} · ${mastXp(id)}/${MAST_XP[l]})`}</b></div>`}).join('');
