const R = document.createElement('div');
R.id = 'kn-root'; R.hidden = true;
R.innerHTML = '<style>' + CSS + '</style>' +
  '<div id="kn-top"><b>🐾 분양소</b><span id="kn-coin"></span><button class="x" id="kn-x">✕</button></div>' +
  '<div id="kn-wrap"><canvas id="kn-cv" width="720" height="960"></canvas><div id="kn-msg"></div>' +
  '<div id="kn-close" hidden></div><div id="kn-shop" hidden></div><div id="kn-dex" hidden></div></div>' +
  '<div id="kn-bar"><div id="kn-foods"></div><div id="kn-acts"><button id="kn-b-shop">🛒 먹이 가게</button><button id="kn-b-dex">📖 분양 도감</button></div></div>';
document.body.appendChild(R);
const $ = s => R.querySelector(s);
const cv = $('#kn-cv'), cx = cv.getContext('2d');
const VW = 360, VH = 480;   // 게임 좌표 (캔버스는 2배 해상도로 그림)
function fit() { const w = $('#kn-wrap'), k = Math.min(w.clientWidth / VW, w.clientHeight / VH); cv.style.width = VW * k + 'px'; cv.style.height = VH * k + 'px'; }
window.addEventListener('resize', () => { if (!R.hidden) fit(); });

// 이미지 로더 (없으면 null → 이모지로 대체)
const IMGS = {};
function img(id, kind) {
  const k = id + '_' + kind;
  if (!(k in IMGS)) {
    IMGS[k] = null;
    const im = new Image();
    im.onload = () => { IMGS[k] = im; };
    im.src = IMG + k + '.png';
  }
  return IMGS[k];
}
function faceHtml(a) {
  return '<img src="' + IMG + a.id + '_close.png" onerror="this.outerHTML=\'' + a.emoji + '\'">';
}

// ───────── 마당 ─────────
const BG = new Image(); let bgOk = false; BG.onload = () => { bgOk = true; }; BG.src = IMG + 'yard.jpg';
const GATE = { x: 0.47, y: 1.04 };   // 마당 아래쪽 문 (동물이 들어오고 나가는 곳)
let food = null;       // {x,y,name}
let ani = null;        // {id,x,y,tx,ty,t,dir,state:'wait'|'come'|'sniff'|'leave'}
let spawnAt = 0, last = 0, raf = 0, busy = false;

function msg(t) { $('#kn-msg').textContent = t || ''; }
function say(t, ms) { msg(t); if (ms) setTimeout(() => { if ($('#kn-msg').textContent === t) msg(''); }, ms); }
function coinText() { $('#kn-coin').textContent = '🍔 ' + coinsNow().toLocaleString(); }

function renderFoods() {
  $('#kn-foods').innerHTML = FOODS.map(f => {
    const q = bagQty(f.name);
    return '<button data-f="' + f.name + '" class="' + (S.food === f.name ? 'on ' : '') + (q < 1 ? 'no' : '') + '"><span class="e">' + foodIcon(f, 26) + '</span>' + f.name + ' ×' + q + '</button>';
  }).join('');
  coinText();
}
$('#kn-foods').addEventListener('click', e => {
  const b = e.target.closest('[data-f]'); if (!b) return;
  S.food = b.dataset.f; save(); renderFoods();
});

function draw(ts) {
  raf = requestAnimationFrame(draw);
  const dt = Math.min(0.05, (ts - (last || ts)) / 1000); last = ts;
  cx.setTransform(2, 0, 0, 2, 0, 0);
  const W = VW, H = VH;
  if (bgOk) cx.drawImage(BG, 0, 0, W, H);
  else {
    const g = cx.createLinearGradient(0, 0, 0, H); g.addColorStop(0, '#3f7a45'); g.addColorStop(1, '#2f5a35');
    cx.fillStyle = g; cx.fillRect(0, 0, W, H);
    cx.fillStyle = '#7a5a36'; cx.fillRect(0, 0, W, 10); cx.fillRect(0, H - 10, W, 10); cx.fillRect(0, 0, 10, H); cx.fillRect(W - 10, 0, 10, H);
  }

  // 동물 등장 대기
  if (food && !ani && !busy && performance.now() / 1000 >= spawnAt) spawnAnimal();

  // 먹이
  if (food) {
    cx.font = '34px serif'; cx.textAlign = 'center'; cx.textBaseline = 'middle';
    cx.fillStyle = 'rgba(0,0,0,.25)'; cx.beginPath(); cx.ellipse(food.x, food.y + 16, 16, 6, 0, 0, 7); cx.fill();
    const fim = window.matImage ? window.matImage(food.name) : null;
    cx.fillStyle = '#fff'; if (fim && fim._ok) cx.drawImage(fim, food.x - 22, food.y - 22, 44, 44); else cx.fillText(foodOf(food.name).emoji, food.x, food.y);
  }

  // 동물
  if (ani) {
    ani.t += dt;
    if (ani.state === 'come' && food) {
      const dx = food.x - ani.x, dy = (food.y + 6) - ani.y, d = Math.hypot(dx, dy);
      if (d < 22) { ani.state = 'sniff'; openClose(); }
      else { ani.x += dx / d * CFG.SPEED * dt; ani.y += dy / d * CFG.SPEED * dt; if (Math.abs(dx) > 2) ani.dir = dx < 0 ? -1 : 1; }
    }
    if (ani.state === 'leave') {
      const gx = W * GATE.x, gy = H * GATE.y, dx = gx - ani.x, dy = gy - ani.y, d = Math.hypot(dx, dy);
      if (Math.abs(dx) > 2) ani.dir = dx < 0 ? -1 : 1;
      if (d < 14) { ani = null; } else { ani.x += dx / d * 170 * dt; ani.y += dy / d * 170 * dt; }
    }
    if (ani) {
      const moving = ani.state === 'come' || ani.state === 'leave';
      const hop = moving ? Math.abs(Math.sin(ani.t * 11)) : 0;
      const sq = moving ? 1 + Math.sin(ani.t * 22) * 0.05 : 1;
      const a = byId(ani.id), im = img(a.id, 'top'), S0 = 64;
      cx.fillStyle = 'rgba(0,0,0,.28)'; cx.beginPath(); cx.ellipse(ani.x, ani.y + 22, 22 - hop * 6, 7 - hop * 2, 0, 0, 7); cx.fill();
      cx.save(); cx.translate(ani.x, ani.y - hop * 12); cx.scale(ani.dir * (2 - sq), sq);
      if (im) { const k = S0 / Math.max(im.width, im.height); cx.drawImage(im, -im.width * k / 2, -im.height * k / 2, im.width * k, im.height * k); }
      else { cx.font = '48px serif'; cx.textAlign = 'center'; cx.textBaseline = 'middle'; cx.fillText(a.emoji, 0, 0); }
      cx.restore();
    }
  }
}

function spawnAnimal() {
  const fav = ANIMALS.find(a => a.food === food.name);
  let pick = fav;
  if (!fav || Math.random() > CFG.RIGHT_RATE) {
    const others = ANIMALS.filter(a => !fav || a.id !== fav.id);
    pick = others[Math.floor(Math.random() * others.length)];
  }
  ani = { id: pick.id, x: VW * GATE.x, y: VH * GATE.y, dir: 1, t: 0, state: 'come' };
  say('앗, 누가 먹이 냄새를 맡고 왔어요!', 2200);
}

cv.addEventListener('pointerdown', e => {
  if (busy || food) { if (food) say('먹이는 한 번에 하나만 놓을 수 있어요', 1500); return; }
  if (bagQty(S.food) < 1) { say('가방에 ' + S.food + '이(가) 없어요. 🛒 먹이 가게에서 사요!', 2200); return; }
  const r = cv.getBoundingClientRect();
  const x = (e.clientX - r.left) / r.width * VW, y = (e.clientY - r.top) / r.height * VH;
  const px = Math.max(80, Math.min(VW - 85, x)), py = Math.max(100, Math.min(VH - 110, y));
  try { useFromBag(S.food, 1); } catch (err) {}
  food = { x: px, y: py, name: S.food };
  spawnAt = performance.now() / 1000 + CFG.ARRIVE_DELAY + Math.random() * 1.2;
  msg('먹이를 놓았어요… 누가 올까요?'); renderFoods();
});

// ───────── 클로즈업 (냄새 맡는 화면) ─────────
let meter = null;
function openClose() {
  busy = true;
  const a = byId(ani.id), right = a.food === food.name;
  const box = $('#kn-close'); box.hidden = false;
  box.innerHTML = '<div class="face">' + faceHtml(a) + '</div><div class="food">' + foodIcon(foodOf(food.name), 56) + '</div><div class="t" id="kn-t">킁킁… 킁킁…</div>' +
    (right ? '<div id="kn-meter"><div id="kn-zone"></div><div id="kn-mk"></div></div><button id="kn-grab">지금이다!</button>' : '');
  if (!right) {
    setTimeout(() => finish(false, a, '냄새를 맡더니 고개를 저으며 가버렸어요…'), 2300);
    return;
  }
  const z = CFG.ZONE, zs = 0.2 + Math.random() * (0.6 - z);
  const zone = $('#kn-zone'); zone.style.left = zs * 100 + '%'; zone.style.width = z * 100 + '%';
  meter = { p: 0, v: 1, zs, z, done: false, t0: performance.now() };
  (function tick() {
    if (!meter || meter.done) return;
    const dt = 0.016; meter.p += meter.v * CFG.METER_SPEED * dt;
    if (meter.p >= 1) { meter.p = 1; meter.v = -1; } else if (meter.p <= 0) { meter.p = 0; meter.v = 1; }
    const mk = $('#kn-mk'); if (mk) mk.style.left = meter.p * 100 + '%';
    requestAnimationFrame(tick);
  })();
  $('#kn-grab').onclick = () => {
    if (!meter || meter.done) return; meter.done = true;
    const ok = meter.p >= meter.zs && meter.p <= meter.zs + meter.z;
    finish(ok, a, ok ? null : '타이밍이 어긋나서 놀라 도망쳤어요!');
  };
}

function finish(ok, a, failText) {
  S.tries = (S.tries || 0) + 1;
  const box = $('#kn-close');
  if (ok) {
    const first = !S.got[a.id]; S.got[a.id] = (S.got[a.id] || 0) + 1; save();
    box.innerHTML = '<div class="face">' + faceHtml(a) + '</div><div class="t" style="font-size:18px;font-weight:900">' + (first ? '🎉 ' + a.name + ' 분양 성공! (신규)' : '🐾 ' + a.name + ' 분양 성공!') + '</div>' +
      '<div class="t" style="color:#bcd">' + (first ? '분양 도감에 등록됐어요. 드라마 조연으로 쓸 수 있어요!' : '이미 분양받은 아이예요. (' + S.got[a.id] + '번째)') + '</div>' +
      '<button id="kn-ok" class="kn-back" style="width:auto;padding:11px 32px">확인</button>';
    $('#kn-ok').onclick = () => endClose(false);
    try { window.dispatchEvent(new CustomEvent('ph-kennel-got', { detail: { id: a.id, first } })); } catch (e) {}
  } else {
    save();
    box.innerHTML = '<div class="face" style="animation:none;opacity:.6">' + faceHtml(a) + '</div><div class="t">' + failText + '</div>' +
      '<button id="kn-ok" class="kn-back" style="width:auto;padding:11px 32px">확인</button>';
    $('#kn-ok').onclick = () => endClose(true);
  }
}
function endClose(leave) {
  $('#kn-close').hidden = true; meter = null; busy = false; food = null; msg('');
  if (leave && ani) ani.state = 'leave'; else ani = null;
  renderFoods();
}

// ───────── 가게 / 도감 ─────────
function renderShop() {
  const sh = $('#kn-shop');
  sh.innerHTML = '<h3>🛒 먹이 가게 <span style="font-size:12px;color:#ffd54a;float:right">🍔 ' + coinsNow().toLocaleString() + '</span></h3>' +
    FOODS.map(f => '<div class="kn-row"><div class="e">' + foodIcon(f, 36) + '</div><div class="i">' + f.name + ' <small>' + f.desc + ' · 보유 ' + bagQty(f.name) + '</small></div>' +
      '<button data-buy="' + f.name + '"' + (coinsNow() < f.price ? ' disabled' : '') + '>🍔' + f.price + '</button></div>').join('') +
    '<button class="kn-back" id="kn-shop-x">닫기</button>';
  $('#kn-shop-x').onclick = () => { sh.hidden = true; renderFoods(); };
}
$('#kn-shop').addEventListener('click', e => {
  const b = e.target.closest('[data-buy]'); if (!b || b.disabled) return;
  const f = foodOf(b.dataset.buy);
  if (coinsNow() < f.price) return;
  let ok = false; try { ok = addToBag(f.emoji, f.name, 'material', 1, '분양소 먹이 · ' + f.desc, 1); } catch (err) {}
  if (!ok) return;
  coins -= f.price;
  try { if (typeof saveAll === 'function') saveAll(); if (typeof updateCoinsDisplay === 'function') updateCoinsDisplay(); } catch (err) {}
  renderShop();
});
$('#kn-b-shop').onclick = () => { $('#kn-dex').hidden = true; renderShop(); $('#kn-shop').hidden = false; };
$('#kn-b-dex').onclick = () => {
  const d = $('#kn-dex'); $('#kn-shop').hidden = true;
  d.innerHTML = '<h3>📖 분양 도감 ' + Object.keys(S.got).length + '/' + ANIMALS.length + '</h3>' +
    ANIMALS.map(a => {
      const n = S.got[a.id] || 0;
      return '<div class="kn-row"><div class="e" style="' + (n ? '' : 'filter:grayscale(1) brightness(.4)') + '">' + a.emoji + '</div><div class="i">' + (n ? a.name : '???') +
        '<small>' + (n ? '좋아하는 먹이: ' + foodOf(a.food).emoji + a.food + ' · 분양 ' + n + '회' : '아직 만나지 못했어요') + '</small></div></div>';
    }).join('') + '<button class="kn-back" id="kn-dex-x">닫기</button>';
  d.hidden = false; $('#kn-dex-x').onclick = () => { d.hidden = true; };
};

// ───────── 열기 / 닫기 ─────────
function openKennel() {
  load(); food = null; ani = null; busy = false; meter = null;
  $('#kn-close').hidden = true; $('#kn-shop').hidden = true; $('#kn-dex').hidden = true;
  R.hidden = false; fit(); msg('마당을 탭해서 먹이를 놓아보세요'); renderFoods();
  last = 0; cancelAnimationFrame(raf); raf = requestAnimationFrame(draw);
}
function closeKennel() { if (busy) return; R.hidden = true; cancelAnimationFrame(raf); food = null; ani = null; }
$('#kn-x').onclick = closeKennel;
window.openKennel = openKennel;
window.__kennel = { owned: () => Object.keys(S.got).filter(k => S.got[k] > 0), got: () => S.got, ANIMALS, FOODS, CFG, _state: () => ({ food, ani, busy }) };

// ───────── 주택가 메뉴 버튼 (탐험 버튼 아래) ─────────
let tries = 0;
(function hook() {
  tries++;
  const anchor = document.getElementById('btn-fancafe-housing') || (tries > 200 ? document.getElementById('btn-explore-housing') : null);
  if (!anchor || typeof PLACE_BUTTONS === 'undefined' || typeof ALL_PLACE_BTNS === 'undefined') { if (tries < 500) setTimeout(hook, 50); return; }
  if (document.getElementById('btn-kennel-housing')) return;
  const b = document.createElement('button');
  b.id = 'btn-kennel-housing'; b.textContent = '🐾 분양소';
  b.style.cssText = 'display:none;width:100%;padding:14px;margin-top:10px;background:rgba(120,220,140,0.15);border:1.5px solid #78dc8c;border-radius:12px;color:#fff;font-size:15px;font-weight:700;cursor:pointer;font-family:inherit;';
  b.onclick = openKennel;
  anchor.insertAdjacentElement('afterend', b);
  if (!PLACE_BUTTONS.housing) PLACE_BUTTONS.housing = [];
  if (PLACE_BUTTONS.housing.indexOf('btn-kennel-housing') === -1) PLACE_BUTTONS.housing.push('btn-kennel-housing');
  if (ALL_PLACE_BTNS.indexOf('btn-kennel-housing') === -1) ALL_PLACE_BTNS.push('btn-kennel-housing');
})();
})();

// ════════════════════════════════
// 👆 분양소 타이밍 게이지 "화면 아무 데나 탭" (kennel-tap.js)
// 분양소에서 맞는 먹이를 놓으면 클로즈업 화면에 게이지가 왔다갔다하는데,
// 원래는 아래 작은 "지금이다!" 버튼만 눌러야 멈췄다. (게이지 바나 화면을 눌러도 반응 없음)
// → 이 파일을 넣으면 클로즈업 화면 아무 데나 탭해도 "지금이다!"로 처리된다.
// (kennel.js는 건드리지 않음 / 버튼도 그대로 눌러짐)
// ════════════════════════════════
(function () {
  'use strict';
  if (window.__kennelTapLoaded) return;
  window.__kennelTapLoaded = true;

  var LABEL = '지금이다! (화면 아무 데나 탭)';
  var tries = 0;

  function attach() {
    var box = document.getElementById('kn-close');
    if (!box) {
      if (++tries > 200) return;            // 약 20초 기다려도 없으면 포기 (원래 버튼 방식은 그대로 동작)
      setTimeout(attach, 100);
      return;
    }
    if (window.__kennelTapApplied) return;
    window.__kennelTapApplied = true;

    // 게이지 단계에서만 존재하는 #kn-grab 버튼이 있을 때, 화면 어디를 탭해도 그 버튼을 누른 것으로 처리
    box.addEventListener('click', function (e) {
      var grab = document.getElementById('kn-grab');
      if (!grab) return;                     // 게이지 단계가 아님 (결과 화면 / 틀린 먹이 등)
      if (e.target === grab) return;         // 버튼을 직접 누른 건 원래 동작이 처리
      grab.click();
    });

    // 버튼 글자에 "아무 데나 탭"을 알려줌 (새로 그려질 때마다)
    function label() {
      var g = document.getElementById('kn-grab');
      if (g && !g.getAttribute('data-tapfix')) {
        g.setAttribute('data-tapfix', '1');
        g.textContent = LABEL;
      }
    }
    try { new MutationObserver(label).observe(box, { childList: true, subtree: true }); } catch (e) {}
    label();
  }
  attach();
})();

// ════════════════════════════════
// 🛒 분양소 먹이 수량 구매 (kennel-qty.js)
// 분양소 안 "먹이 가게"에서 먹이 버튼을 누르면, 잡화점처럼 수량 선택 창(슬라이더 / ± / 직접 입력 / 최대)이 떠서
// 한 번에 여러 개를 살 수 있게 한다. (kennel.js / qty-picker.js / game.js는 건드리지 않음)
//
// - 수량 선택 창은 qty-picker.js의 것을 그대로 쓴다 (그래서 qty-picker.js가 로더에 먼저 있어야 함).
// - 한 번에 살 수 있는 최대 개수는 qty-picker.js의 QP_MAX(100개)를 따른다.
// - 가격은 kennel.js의 먹이 가격(window.__kennel.FOODS)을 그대로 읽는다. 가격을 바꾸려면 kennel.js에서 바꾸면 됨.
// ════════════════════════════════
(function () {
  'use strict';
  if (window.__kennelQtyLoaded) return;
  window.__kennelQtyLoaded = true;

  var tries = 0;
  function ready() {
    return typeof qpOpen === 'function' && typeof addToBag === 'function' && typeof saveAll === 'function' &&
      window.__kennel && window.__kennel.FOODS && document.getElementById('kn-shop') && document.getElementById('kn-b-shop');
  }

  function toast(m) {
    try {
      if (typeof qpToast === 'function') qpToast(m);
      else if (typeof showBagToast === 'function') showBagToast(m);
    } catch (e) {}
  }

  function buy(f, n) {
    var total = f.price * n;
    if (coins < total) { toast('코인이 부족해요!'); return; }
    if (typeof qpCanFit === 'function' && !qpCanFit(f.name)) { toast('가방이 꽉 찼어요! 🎒 슬롯을 확장해주세요'); return; }
    var ok = false;
    try { ok = addToBag(f.emoji, f.name, 'material', n, '분양소 먹이 · ' + f.desc, 1); } catch (e) {}
    if (!ok) return;
    coins -= total;
    try { saveAll(); } catch (e) {}
    try { if (typeof updateCoinsDisplay === 'function') updateCoinsDisplay(); } catch (e) {}
    try { if (typeof spawnCoinFloat === 'function') spawnCoinFloat(-total); } catch (e) {}
    // 가게 화면을 다시 그려서 코인/보유 수량 갱신 (kennel.js의 '먹이 가게' 버튼과 같은 동작)
    var shopBtn = document.getElementById('kn-b-shop');
    if (shopBtn) shopBtn.click();
    toast(f.name + ' ' + n + '개 구매 완료!');
  }

  function attach() {
    if (!ready()) {
      if (++tries > 200) return;            // 약 20초 기다려도 안 붙으면 포기 (원래 1개씩 사기는 그대로 동작)
      setTimeout(attach, 100);
      return;
    }
    if (window.__kennelQtyApplied) return;
    window.__kennelQtyApplied = true;

    // 가게 영역에서 먹이 구매 버튼 클릭을 먼저(capture) 가로채서 수량 선택 창으로 바꾼다.
    document.getElementById('kn-shop').addEventListener('click', function (e) {
      var b = e.target.closest ? e.target.closest('[data-buy]') : null;
      if (!b) return;
      e.stopImmediatePropagation();         // kennel.js의 "1개 바로 구매"는 실행되지 않게 막음
      e.preventDefault();
      if (b.disabled) return;
      var f = window.__kennel.FOODS.find(function (x) { return x.name === b.getAttribute('data-buy'); });
      if (!f) return;
      qpOpen({
        mode: 'buy', emoji: f.emoji, name: f.name, unit: f.price,
        max: Math.floor(coins / f.price),
        onConfirm: function (n) { buy(f, n); }
      });
    }, true);
  }
  attach();

  window.__kennelQty = { attach: attach };
})();

// ════════════════════════════════
// 💗 동물 친밀도 (kennel-bond.js)
// 같은 동물을 분양받을 때마다 친밀도가 쌓이고, 레벨이 오를수록 CF 촬영 게스트 보너스(성공 확률)가 커진다.
// (kennel.js는 건드리지 않음. 분양 횟수는 kennel.js가 이미 저장하는 값을 그대로 읽으므로 새 저장값은 없음)
//
// - 분양 성공 화면에 "친밀도 Lv.n" 이 뜨고, 레벨이 오르면 알려줌
// - 🐾 분양 도감에 동물마다 친밀도 레벨 / 보너스 / 다음 레벨까지 남은 횟수가 보임
// - CF 촬영 게스트 보너스에 반영되려면 cf-shoot.js가 이 파일을 읽는 버전이어야 함 (교체본 cf-shoot.js)
//
// 숫자를 바꾸고 싶으면 아래 두 줄만 고치면 됨.
// ════════════════════════════════
(function () {
  'use strict';
  if (window.__kennelBondLoaded) return;
  window.__kennelBondLoaded = true;

  // ── 설정 ──
  var LEVEL_AT = [1, 3, 6, 10, 15];   // 누적 분양 횟수가 이만큼이면 Lv.1 / 2 / 3 / 4 / 5
  var BONUS = [10, 12, 14, 17, 20];   // 레벨별 CF 촬영 성공 확률 보너스(%p) — 처음엔 +10, 최대 +20

  // ════════ 순수 로직 ════════
  function counts() {
    try { return (window.__kennel && window.__kennel.got && window.__kennel.got()) || {}; } catch (e) { return {}; }
  }
  function levelOf(n) {
    var lv = 0;
    for (var i = 0; i < LEVEL_AT.length; i++) if (n >= LEVEL_AT[i]) lv = i + 1;
    return lv;
  }
  function level(id) { return levelOf(counts()[id] || 0); }
  function bonus(id) { var lv = level(id); return lv > 0 ? BONUS[lv - 1] : null; }
  function nextNeed(id) {                       // 다음 레벨까지 남은 분양 횟수 (만렙이면 0)
    var n = counts()[id] || 0, lv = levelOf(n);
    return lv >= LEVEL_AT.length ? 0 : LEVEL_AT[lv] - n;
  }
  function line(id) {                           // 한 줄 설명 (도감용)
    var lv = level(id);
    if (lv < 1) return '';
    var need = nextNeed(id);
    return '💗 친밀도 Lv.' + lv + (need === 0 ? ' MAX' : '') + ' · CF 보너스 +' + BONUS[lv - 1] + '%p' + (need ? ' · 다음 Lv까지 ' + need + '회' : '');
  }

  // ════════ 분양 성공 화면에 친밀도 표시 ════════
  // kennel.js는 분양에 성공하면 'ph-kennel-got' 이벤트를 보낸다. (횟수는 이미 올라간 뒤)
  window.addEventListener('ph-kennel-got', function (e) {
    try {
      var id = e && e.detail && e.detail.id; if (!id) return;
      var n = counts()[id] || 0, now = levelOf(n), before = levelOf(n - 1);
      var box = document.getElementById('kn-close'), ok = document.getElementById('kn-ok');
      if (!box || !ok || box.querySelector('[data-bond]')) return;
      var d = document.createElement('div');
      d.setAttribute('data-bond', '1');
      d.className = 't';
      var up = now > before;
      d.style.cssText = 'font-size:' + (up ? 16 : 13) + 'px;font-weight:' + (up ? 900 : 700) + ';color:' + (up ? '#ffd54a' : '#9fe3c5') + ';text-align:center;line-height:1.5;';
      d.textContent = up ? '💗 친밀도 Lv.' + now + ' 달성! CF 보너스 +' + BONUS[now - 1] + '%p' : line(id);
      ok.parentNode.insertBefore(d, ok);
    } catch (err) {}
  });

  // ════════ 분양 도감에 친밀도 표시 ════════
  var tries = 0;
  function attachDex() {
    var btn = document.getElementById('kn-b-dex');
    if (!btn || !window.__kennel || !window.__kennel.ANIMALS) {
      if (++tries > 200) return;                // 약 20초 기다려도 없으면 포기
      setTimeout(attachDex, 100);
      return;
    }
    if (window.__kennelBondDexApplied) return;
    window.__kennelBondDexApplied = true;
    // kennel.js가 도감을 그린 "다음에" 실행됨 (같은 버튼에 나중에 붙인 리스너라서)
    btn.addEventListener('click', function () {
      try {
        var rows = document.querySelectorAll('#kn-dex .kn-row');
        window.__kennel.ANIMALS.forEach(function (a, i) {
          var row = rows[i], txt = line(a.id);
          if (!row || !txt) return;
          var holder = row.querySelector('.i');
          if (!holder || holder.querySelector('[data-bond]')) return;
          var s = document.createElement('small');
          s.setAttribute('data-bond', '1');
          s.style.color = '#9fe3c5';
          s.textContent = txt;
          holder.appendChild(s);
        });
      } catch (err) {}
    });
  }
  attachDex();

  window.__kennelBond = { level: level, bonus: bonus, nextNeed: nextNeed, line: line, LEVEL_AT: LEVEL_AT, BONUS: BONUS, MAX: LEVEL_AT.length };
})();

