    document.body.appendChild(ov);
    try { if (window.pocaSfx && window.pocaSfx.play) window.pocaSfx.play(k.sfx); } catch (e) {}
  }
  window.showBigDrop = function (kind) {
    if (!KINDS[kind]) return;
    queue.push(kind);
    next();
  };
})();

