  }
  function lockedRule(el) {          // 누른 곳에서 위로 최대 4단계까지 올라가며 짧은 버튼 글자에서 찾음
    for (var n = 0, e = el; e && e !== document.body && n < 5; e = e.parentElement, n++) {
      if (e.id === 'first-hidden-pop' || e.closest && e.closest('#unlock-gate-pop')) return null;
