      if (STAT_MAP[stat]) { try { v += totals()[STAT_MAP[stat]] || 0; } catch (e) {} }
      return v;
    };
    window.getEquippedStat = w;
  });

  // 2) 스태미나 소모 -N% : 10 이상 줄어들 때 그만큼 돌려줌 (체험 카드와 같은 방식)
  whenReady(function () { return typeof window.saveStamina === 'function' && typeof stamina !== 'undefined'; }, function () {
    var orig = window.saveStamina, last = stamina;
    window.saveStamina = function () {
      try {
        var diff = last - stamina, f = totals().stamina || 0;
        if (f > 0 && diff >= 10 && diff <= 60) { var back = Math.floor(diff * f / 100); if (back > 0) stamina += back; }
      } catch (e) {}
      var r = orig.apply(this, arguments);
      last = stamina;
      return r;
    };
  });

  // 3) 소원조각 획득 확률 +N%p
  whenReady(function () { return typeof window.checkWishFragment === 'function'; }, function () {
    var orig = window.checkWishFragment;
    window.checkWishFragment = function (rate) {
      var base = (typeof rate === 'number') ? rate : 0.005;
      var add = 0; try { add = (totals().wish || 0) / 100; } catch (e) {}
      return orig.call(this, base + add);
    };
  });

  // 4) 제작(재봉) 대성공 확률 +N%p : 그 한 번 동안만 great 비율을 올리고 success 에서 뺀다
  whenReady(function () { return typeof window.craftCloth === 'function' && typeof SEWING_RATES !== 'undefined'; }, function () {
    var orig = window.craftCloth;
    window.craftCloth = function () {
      var add = 0; try { add = (totals().great || 0) / 100; } catch (e) {}
      if (add <= 0) return orig.apply(this, arguments);
      var g = SEWING_RATES.great, s = SEWING_RATES.success;
      var move = Math.min(add, Math.max(0, s));
      SEWING_RATES.great = g + move; SEWING_RATES.success = s - move;
      try { return orig.apply(this, arguments); }
      finally { SEWING_RATES.great = g; SEWING_RATES.success = s; }
    };
  });

  // 5-1) 수업 점수 +N% : 연성고등학교 과목 점수를 저장할 때 곱함(100점 상한). 의상의 '수업 점수' 효과도 같이 적용됨
  whenReady(function () { return typeof window.setSchoolScore === 'function'; }, function () {
    var orig = window.setSchoolScore;
    window.setSchoolScore = function (subject, score) {
      try {
        var b = Number(window.getEquippedStat('study')) || 0;
        if (b > 0 && typeof score === 'number') score = Math.min(100, Math.round(score * (1 + b / 100)));
      } catch (e) {}
      return orig.call(this, subject, score);
    };
  });
  // 결과 팝업에 보이는 점수도 같은 보너스를 적용해서 저장된 점수와 맞춤
  whenReady(function () { return typeof window.showSchoolResult === 'function'; }, function () {
    var orig = window.showSchoolResult;
    window.showSchoolResult = function (title, score, sub) {
      try {
        var b = Number(window.getEquippedStat('study')) || 0;
        if (b > 0 && typeof score === 'number') { score = Math.min(100, Math.round(score * (1 + b / 100))); sub = (sub || '') + ' · 수업 점수 보너스 +' + b + '%'; }
      } catch (e) {}
      return orig.call(this, title, score, sub);
    };
  });
  // 5-2) 시험 등급 상승 +N% : 성적표 평균에 곱함 (game.js finishSchoolReport 가 불러감)
  window.__hfxExamBonus = function () { try { return totals().exam || 0; } catch (e) { return 0; } };

  // 5) 알바 경험치 +N% : 알바를 1번 끝낼 때마다(albaDone 증가) 기본 경험치 15의 N%를 더 줌 (소수는 모아서)
  var _albaLast = null, _expCarry = 0;
  setInterval(function () {
    try {
      if (typeof albaDone === 'undefined' || typeof addPlayerExp !== 'function') return;
      if (_albaLast === null) { _albaLast = albaDone; return; }
      var d = albaDone - _albaLast; _albaLast = albaDone;
      if (d <= 0 || d > 5) return;
      _expCarry += d * 15 * (totals().exp || 0) / 100;
      var give = Math.floor(_expCarry);
      if (give > 0) { _expCarry -= give; addPlayerExp(give); }
    } catch (e) {}
  }, 700);

  // 6) 탐험 시간 +N초 (game.js 탐험 타이머가 불러감) / 희귀 NPC 조우율 +N%p (broadcast-expedition.js 가 불러감)
  window.__hfxExploreMs = function () { try { return Math.round((totals().time || 0) * 1000); } catch (e) { return 0; } };
  window.__hfxNpcBonus = function () { try { return (totals().npc || 0) / 100; } catch (e) { return 0; } };

  // 7) 제작 재료 소모 -N (재료마다 최소 1개는 남김) : 재봉 레시피 목록을 줄여서 보여주고 실제로도 적게 씀
