        }, S.loot));
      }, 700);
    }
    drawHud();
    raf = requestAnimationFrame(loop);
    window.__wtTest = { S: S, step: step, draw: draw, useSkill: useSkill, end: end, startAtk: startAtk, avail: avail, ATK: ATK, resolveAtk: resolveAtk };
  }

  function reg() {
